  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Save, Euro, Home, Waves, AlertCircle, CheckCircle } from 'lucide-react'

interface BookingWidgetSetting {
  id: string
  experience_type: 'room' | 'surf-week'
  price_from: number
  is_active: boolean
}

export default function BookingWidgetSettingsPage() {
  const router = useRouter()
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [settings, setSettings] = useState<BookingWidgetSetting[]>([])
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)

  useEffect(() => {
    fetchSettings()
  }, [])

  const fetchSettings = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/admin/booking-widget-settings')
      const data = await response.json()

      if (data.success && data.data) {
        setSettings(data.data)
      } else {
        setMessage({ type: 'error', text: data.error || 'Failed to load settings' })
      }
    } catch (error) {
      console.error('Error fetching settings:', error)
      setMessage({ type: 'error', text: 'Error loading settings' })
    } finally {
      setLoading(false)
    }
  }

  const handlePriceChange = (experienceType: 'room' | 'surf-week', value: string) => {
    const numValue = parseFloat(value)
    if (isNaN(numValue) || numValue < 0) return

    setSettings(prev =>
      prev.map(setting =>
        setting.experience_type === experienceType
          ? { ...setting, price_from: numValue }
          : setting
      )
    )
  }

  const handleSave = async () => {
    try {
      setSaving(true)
      setMessage(null)

      // Validate settings
      for (const setting of settings) {
        if (setting.price_from < 0) {
          setMessage({ type: 'error', text: 'Prices must be positive numbers' })
          setSaving(false)
          return
        }
        if (setting.price_from > 10000) {
          setMessage({ type: 'error', text: 'Prices seem unusually high. Please verify.' })
          setSaving(false)
          return
        }
      }

      const response = await fetch('/api/admin/booking-widget-settings', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ settings }),
      })

      const data = await response.json()

      if (data.success) {
        setMessage({ type: 'success', text: 'Settings saved successfully!' })
        setTimeout(() => setMessage(null), 3000)
      } else {
        setMessage({ type: 'error', text: data.error || 'Failed to save settings' })
      }
    } catch (error) {
      console.error('Error saving settings:', error)
      setMessage({ type: 'error', text: 'Error saving settings' })
    } finally {
      setSaving(false)
    }
  }

  const roomSetting = settings.find(s => s.experience_type === 'room')
  const surfWeekSetting = settings.find(s => s.experience_type === 'surf-week')

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 p-8">
        <div className="max-w-4xl mx-auto">
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-8">
            <div className="animate-pulse space-y-4">
              <div className="h-8 bg-gray-200 rounded w-1/3"></div>
              <div className="h-4 bg-gray-200 rounded w-1/2"></div>
              <div className="h-32 bg-gray-200 rounded mt-6"></div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="mb-6">
          <button
            onClick={() => router.back()}
            className="text-gray-600 hover:text-gray-900 mb-4 flex items-center gap-2"
          >
            <ArrowLeft size={20} />
            Back
          </button>
          <h1 className="text-3xl font-bold text-gray-900">Booking Widget Settings</h1>
          <p className="text-gray-600 mt-2">
            Configure the "from" price points displayed in the booking widget experience selection
          </p>
        </div>

        {/* Message */}
        {message && (
          <div
            className={`mb-6 p-4 rounded-lg flex items-start gap-3 ${
              message.type === 'success'
                ? 'bg-green-50 border border-green-200 text-green-800'
                : 'bg-red-50 border border-red-200 text-red-800'
            }`}
          >
            {message.type === 'success' ? (
              <CheckCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
            ) : (
              <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
            )}
            <span>{message.text}</span>
          </div>
        )}

        {/* Settings Form */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <div className="space-y-6">
            {/* Room Booking Price */}
            <div className="border-b border-gray-200 pb-6">
              <div className="flex items-center gap-3 mb-4">
                <div className="p-2 bg-blue-100 rounded-lg">
                  <Home className="w-5 h-5 text-blue-600" />
                </div>
                <div>
                  <h2 className="text-lg font-semibold text-gray-900">Room Booking</h2>
                  <p className="text-sm text-gray-600">Starting price for room bookings</p>
                </div>
              </div>
              <div className="ml-12">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  "From" Price (€)
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Euro className="w-5 h-5 text-gray-400" />
                  </div>
                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    value={roomSetting?.price_from || 45}
                    onChange={(e) => handlePriceChange('room', e.target.value)}
                    className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-accent focus:border-accent"
                    placeholder="45.00"
                  />
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  This price will appear as "from €{roomSetting?.price_from || 45}" in the booking widget
                </p>
              </div>
            </div>

            {/* Surf Week Price */}
            <div>
              <div className="flex items-center gap-3 mb-4">
                <div className="p-2 bg-orange-100 rounded-lg">
                  <Waves className="w-5 h-5 text-orange-600" />
                </div>
                <div>
                  <h2 className="text-lg font-semibold text-gray-900">All-Inclusive Surf Week</h2>
                  <p className="text-sm text-gray-600">Starting price for surf week packages</p>
                </div>
              </div>
              <div className="ml-12">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  "From" Price (€)
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Euro className="w-5 h-5 text-gray-400" />
                  </div>
                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    value={surfWeekSetting?.price_from || 599}
                    onChange={(e) => handlePriceChange('surf-week', e.target.value)}
                    className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-accent focus:border-accent"
                    placeholder="599.00"
                  />
                </div>
                <p className="text-xs text-gray-500 mt-1">
                  This price will appear as "FROM €{surfWeekSetting?.price_from || 599}" in the booking widget
                </p>
              </div>
            </div>
          </div>

          {/* Save Button */}
          <div className="mt-8 pt-6 border-t border-gray-200 flex justify-end">
            <button
              onClick={handleSave}
              disabled={saving}
              className="inline-flex items-center gap-2 px-6 py-3 bg-accent hover:bg-accent-dark text-white font-semibold rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-accent focus:ring-offset-2"
            >
              {saving ? (
                <>
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  Saving...
                </>
              ) : (
                <>
                  <Save className="w-5 h-5" />
                  Save Settings
                </>
              )}
            </button>
          </div>
        </div>

        {/* Info Box */}
        <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <AlertCircle className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
            <div className="text-sm text-blue-800">
              <p className="font-semibold mb-1">Note:</p>
              <p>
                These prices are displayed as starting points in the booking widget. Actual pricing
                for individual surf weeks and rooms may vary based on dates, occupancy, and other factors.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { ArrowLeft, Calendar, Users, Euro, Edit, Trash2, MapPin, CheckCircle, XCircle, UserPlus } from 'lucide-react'
import Image from 'next/image'
import { ParticipantsList } from '@/components/admin/enrollments/ParticipantsList'
import { EnrollmentModal } from '@/components/admin/enrollments/EnrollmentModal'

interface SurfCamp {
  id: string
  name: string
  start_date: string
  end_date: string
  max_participants: number
  confirmed_booked?: number
  enrolled_count?: number
  available_spots?: number
  price: number
  level: string
  description: string
  includes: string[]
  images: string[]
  is_active: boolean
  location?: string
}

export default function SurfCampClient({ id }: { id: string }) {
  const router = useRouter()
  const [surfCamp, setSurfCamp] = useState<SurfCamp | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [enrollmentModalOpen, setEnrollmentModalOpen] = useState(false)
  const [participantsKey, setParticipantsKey] = useState(0) // Force refresh

  useEffect(() => {
    const fetchSurfCamp = async () => {
      try {
        setLoading(true)
        const response = await fetch(`/api/surf-camps/${id}`)
        const data = await response.json()

        if (data.success) {
          setSurfCamp(data.data.surf_camp)
        } else {
          setError(data.error || 'Failed to fetch surf week')
        }
      } catch (err) {
        setError('Error loading surf week')
        console.error(err)
      } finally {
        setLoading(false)
      }
    }

    fetchSurfCamp()
  }, [id])

  const refreshData = () => {
    // Refresh both surf camp data and participants list
    setParticipantsKey(prev => prev + 1)
    // Re-fetch surf camp to update counts
    fetch(`/api/surf-camps/${id}`)
      .then(res => res.json())
      .then(data => {
        if (data.success) {
          setSurfCamp(data.data.surf_camp)
        }
      })
      .catch(console.error)
  }

  const formatDate = (dateString: string) => {
    // Parse date string as UTC to avoid timezone offset issues
    const [year, month, day] = dateString.split('-').map(Number)
    const date = new Date(Date.UTC(year, month - 1, day))
    return date.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      timeZone: 'UTC'
    })
  }

  const getAvailabilityStatus = (camp: SurfCamp) => {
    const spotsLeft = camp.available_spots ?? (camp.max_participants - (camp.confirmed_booked ?? 0))
    if (spotsLeft <= 0) return { text: 'Fully Booked', color: 'bg-red-100 text-red-800' }
    if (spotsLeft <= 3) return { text: `${spotsLeft} Spots Left`, color: 'bg-orange-100 text-orange-800' }
    return { text: `${spotsLeft} Available`, color: 'bg-green-100 text-green-800' }
  }

  if (loading) {
    return (
      <div className="p-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-1/4 mb-8"></div>
          <div className="h-64 bg-gray-200 rounded-lg"></div>
        </div>
      </div>
    )
  }

  if (error || !surfCamp) {
    return (
      <div className="p-8">
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <p className="text-red-800">{error || 'Surf camp not found'}</p>
          <Link href="/admin/surf-camps" className="text-blue-600 hover:text-blue-800 mt-2 inline-block">
            ← Back to Surf Weeks
          </Link>
        </div>
      </div>
    )
  }

  const availability = getAvailabilityStatus(surfCamp)

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <Link 
          href="/admin/surf-camps" 
          className="inline-flex items-center text-gray-600 hover:text-gray-900 transition-colors"
        >
          <ArrowLeft className="mr-2 h-5 w-5" />
          Back to Surf Weeks
        </Link>
        <div className="flex gap-2">
          <button
            onClick={() => setEnrollmentModalOpen(true)}
            className="inline-flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
          >
            <UserPlus className="h-4 w-4" />
            Enroll
          </button>
          <Link
            href={`/admin/surf-camps/${surfCamp.id}/edit`}
            className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Edit className="h-4 w-4" />
            Edit
          </Link>
        </div>
      </div>

      {/* Main Content */}
      <div className="bg-white rounded-lg shadow-md overflow-hidden">
        {/* Image */}
        {surfCamp.images && surfCamp.images.length > 0 && (
          <div className="relative w-full h-64 md:h-96">
            <Image
              src={surfCamp.images[0]}
              alt={surfCamp.name}
              fill
              style={{ objectFit: 'cover' }}
              className="object-cover"
            />
          </div>
        )}

        <div className="p-6 space-y-6">
          {/* Title and Status */}
          <div className="flex items-start justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900">{surfCamp.name}</h1>
              <p className="text-gray-600 mt-2">{surfCamp.description}</p>
            </div>
            <div className="flex flex-col items-end gap-2">
              <span className={`inline-flex px-3 py-1 rounded-full text-sm font-medium ${availability.color}`}>
                {availability.text}
              </span>
              {surfCamp.is_active ? (
                <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-sm font-medium bg-green-100 text-green-800">
                  <CheckCircle className="h-4 w-4" />
                  Active
                </span>
              ) : (
                <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-sm font-medium bg-gray-100 text-gray-800">
                  <XCircle className="h-4 w-4" />
                  Inactive
                </span>
              )}
            </div>
          </div>

          {/* Key Info Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="bg-gray-50 rounded-lg p-4">
              <div className="flex items-center gap-2 text-gray-600 mb-1">
                <Calendar className="h-5 w-5" />
                <span className="text-sm font-medium">Start Date</span>
              </div>
              <p className="text-lg font-semibold text-gray-900">{formatDate(surfCamp.start_date)}</p>
            </div>

            <div className="bg-gray-50 rounded-lg p-4">
              <div className="flex items-center gap-2 text-gray-600 mb-1">
                <Calendar className="h-5 w-5" />
                <span className="text-sm font-medium">End Date</span>
              </div>
              <p className="text-lg font-semibold text-gray-900">{formatDate(surfCamp.end_date)}</p>
            </div>

            <div className="bg-gray-50 rounded-lg p-4">
              <div className="flex items-center gap-2 text-gray-600 mb-1">
                <Users className="h-5 w-5" />
                <span className="text-sm font-medium">Participants</span>
              </div>
              <p className="text-lg font-semibold text-gray-900">
                {surfCamp.confirmed_booked ?? surfCamp.enrolled_count ?? 0} / {surfCamp.max_participants}
              </p>
            </div>

            <div className="bg-gray-50 rounded-lg p-4">
              <div className="flex items-center gap-2 text-gray-600 mb-1">
                <Euro className="h-5 w-5" />
                <span className="text-sm font-medium">Price</span>
              </div>
              <p className="text-lg font-semibold text-gray-900">€{surfCamp.price}/person</p>
            </div>
          </div>

          {/* Level */}
          <div className="border-t pt-4">
            <span className="inline-flex px-3 py-1 rounded-full text-sm font-medium bg-blue-100 text-blue-800">
              Level: {surfCamp.level}
            </span>
          </div>

          {/* Location */}
          {surfCamp.location && (
            <div className="border-t pt-4">
              <div className="flex items-center gap-2 text-gray-600">
                <MapPin className="h-5 w-5" />
                <span className="font-medium">Location:</span>
                <span>{surfCamp.location}</span>
              </div>
            </div>
          )}

          {/* Includes */}
          {surfCamp.includes && surfCamp.includes.length > 0 && (
            <div className="border-t pt-4">
              <h3 className="text-lg font-semibold text-gray-900 mb-3">What's Included</h3>
              <ul className="grid grid-cols-1 md:grid-cols-2 gap-2">
                {surfCamp.includes.map((item, index) => (
                  <li key={index} className="flex items-center gap-2 text-gray-700">
                    <CheckCircle className="h-4 w-4 text-green-500 flex-shrink-0" />
                    <span>{item}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Additional Images */}
          {surfCamp.images && surfCamp.images.length > 1 && (
            <div className="border-t pt-4">
              <h3 className="text-lg font-semibold text-gray-900 mb-3">Gallery</h3>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {surfCamp.images.slice(1).map((image, index) => (
                  <div key={index} className="relative w-full h-32 rounded-lg overflow-hidden">
                    <Image
                      src={image}
                      alt={`${surfCamp.name} - Image ${index + 2}`}
                      fill
                      style={{ objectFit: 'cover' }}
                      className="object-cover"
                    />
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Participants List */}
      <ParticipantsList 
        key={participantsKey}
        surfCampId={surfCamp.id} 
        onParticipantRemoved={refreshData}
      />

      {/* Enrollment Modal */}
      <EnrollmentModal
        open={enrollmentModalOpen}
        onClose={() => setEnrollmentModalOpen(false)}
        surfCampId={surfCamp.id}
        onEnrolled={refreshData}
      />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { ArrowLeft, Save, Plus, Trash2 } from 'lucide-react'
import { ImageUpload } from '@/components/admin/ImageUpload'
import { TaxCategorySelect } from '@/components/admin/TaxCategorySelect'

interface SurfCampFormData {
  name: string
  description: string
  start_date: string
  end_date: string
  max_participants: number
  price: number
  level: string
  includes: string[]
  images: string[]
  is_active: boolean
  tax_category_id: string | null
}

const surfLevels = ['Beginner', 'Intermediate', 'Advanced', 'All Levels']
const commonIncludes = [
  'Accommodation',
  'Surf Lessons',
  'Equipment Rental',
  'Meals',
  'Transportation',
  'Yoga Classes',
  'Skateboard Sessions',
  'Photography',
  'Video Analysis',
  'Beach Cleanup',
  'Cultural Activities',
  'Airport Transfer',
]

export default function EditSurfCampClient({ id }: { id: string }) {
  const router = useRouter()
  const [formData, setFormData] = useState<SurfCampFormData>({
    name: '',
    description: '',
    start_date: '',
    end_date: '',
    max_participants: 12,
    price: 0,
    level: 'All Levels',
    includes: [],
    images: [],
    is_active: true,
    tax_category_id: null,
  })
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [newInclude, setNewInclude] = useState('')

  useEffect(() => {
    fetchSurfCamp()
  }, [id])

  const fetchSurfCamp = async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/surf-camps/${id}`)
      const data = await response.json()

      if (data.success && data.data.surf_camp) {
        const camp = data.data.surf_camp
        setFormData({
          name: camp.name || '',
          description: camp.description || '',
          start_date: camp.start_date || '',
          end_date: camp.end_date || '',
          max_participants: camp.max_participants || 12,
          price: camp.price || 0,
          level: camp.level || 'All Levels',
          includes: camp.includes || [],
          images: camp.images || [],
          is_active: camp.is_active !== undefined ? camp.is_active : true,
          tax_category_id: camp.tax_category_id || null,
        })
      } else {
        setError('Failed to fetch surf week')
      }
    } catch (err) {
      setError('Error loading surf week')
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const validateForm = () => {
    if (!formData.name?.trim()) {
      setError('Surf week name is required')
      return false
    }
    if (!formData.start_date) {
      setError('Start date is required')
      return false
    }
    if (!formData.end_date) {
      setError('End date is required')
      return false
    }
    if (new Date(formData.end_date) <= new Date(formData.start_date)) {
      setError('End date must be after start date')
      return false
    }
    if (formData.max_participants <= 0) {
      setError('Maximum participants must be greater than 0')
      return false
    }
    if (formData.price < 0) {
      setError('Price cannot be negative')
      return false
    }
    return true
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSaving(true)
    setError(null)

    // Client-side validation
    if (!validateForm()) {
      setSaving(false)
      return
    }

    try {
      const response = await fetch(`/api/surf-camps/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          tax_category_id: formData.tax_category_id,
        }),
      })

      const data = await response.json()

      if (data.success) {
        router.push('/admin/surf-camps')
        router.refresh()
      } else {
        // Provide more detailed error message
        const errorMessage = data.error || data.message || 'Failed to update surf week'
        setError(`${errorMessage}. Please check your input and try again.`)
        console.error('Surf week update error:', data)
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Network error'
      setError(`Failed to update surf week: ${errorMessage}. Please check your connection and try again.`)
      console.error('Surf week update exception:', err)
    } finally {
      setSaving(false)
    }
  }

  const handleIncludeChange = (include: string, checked: boolean) => {
    if (checked) {
      setFormData(prev => ({
        ...prev,
        includes: [...prev.includes, include]
      }))
    } else {
      setFormData(prev => ({
        ...prev,
        includes: prev.includes.filter(i => i !== include)
      }))
    }
  }

  const addCustomInclude = () => {
    if (newInclude.trim() && !formData.includes.includes(newInclude.trim())) {
      setFormData(prev => ({
        ...prev,
        includes: [...prev.includes, newInclude.trim()]
      }))
      setNewInclude('')
    }
  }

  const removeInclude = (include: string) => {
    setFormData(prev => ({
      ...prev,
      includes: prev.includes.filter(i => i !== include)
    }))
  }

  if (loading) {
    return (
      <div className="p-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-1/4 mb-8"></div>
          <div className="h-64 bg-gray-200 rounded-lg"></div>
        </div>
      </div>
    )
  }

  return (
    <div className="p-8">
      <div className="mb-8">
        <div className="flex items-center gap-4 mb-4">
          <Link
            href="/admin/surf-camps"
            className="inline-flex items-center gap-2 px-3 py-2 text-gray-600 hover:text-gray-900 transition-colors"
          >
            <ArrowLeft className="h-4 w-4" />
            Back to Surf Weeks
          </Link>
        </div>
        <h1 className="text-3xl font-bold text-gray-900">Edit Surf Week</h1>
        <p className="text-gray-600 mt-2">Update surf week program details</p>
      </div>

      <form onSubmit={handleSubmit} className="max-w-4xl">
        <div className="bg-white shadow rounded-lg">
          <div className="px-6 py-4 border-b border-gray-200">
            <h3 className="text-lg font-medium text-gray-900">Surf Week Information</h3>
          </div>

          <div className="p-6 space-y-6">
            {/* Basic Information */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="name" className="block text-sm font-medium text-gray-700 mb-2">
                  Camp Name *
                </label>
                <input
                  type="text"
                  id="name"
                  required
                  value={formData.name}
                  onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="e.g., Spring Surf Adventure"
                />
              </div>

              <div>
                <label htmlFor="level" className="block text-sm font-medium text-gray-700 mb-2">
                  Skill Level *
                </label>
                <select
                  id="level"
                  required
                  value={formData.level}
                  onChange={(e) => setFormData(prev => ({ ...prev, level: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                >
                  {surfLevels.map((level) => (
                    <option key={level} value={level}>{level}</option>
                  ))}
                </select>
              </div>
            </div>

            <div>
              <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-2">
                Description *
              </label>
              <textarea
                id="description"
                required
                rows={4}
                value={formData.description}
                onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="Describe the surf week, what participants will learn, and the overall experience..."
              />
            </div>

            {/* Dates */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="start_date" className="block text-sm font-medium text-gray-700 mb-2">
                  Start Date *
                </label>
                <input
                  type="date"
                  id="start_date"
                  required
                  value={formData.start_date}
                  onChange={(e) => setFormData(prev => ({ ...prev, start_date: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>

              <div>
                <label htmlFor="end_date" className="block text-sm font-medium text-gray-700 mb-2">
                  End Date *
                </label>
                <input
                  type="date"
                  id="end_date"
                  required
                  value={formData.end_date}
                  onChange={(e) => setFormData(prev => ({ ...prev, end_date: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
            </div>

            {/* Capacity and Pricing */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="max_participants" className="block text-sm font-medium text-gray-700 mb-2">
                  Max Participants *
                </label>
                <input
                  type="number"
                  id="max_participants"
                  required
                  min="1"
                  max="50"
                  value={formData.max_participants}
                  onChange={(e) => setFormData(prev => ({ ...prev, max_participants: parseInt(e.target.value) }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>

              <div>
                <label htmlFor="price" className="block text-sm font-medium text-gray-700 mb-2">
                  Price per Person (€) *
                </label>
                <input
                  type="number"
                  id="price"
                  required
                  min="0"
                  step="0.01"
                  value={formData.price}
                  onChange={(e) => setFormData(prev => ({ ...prev, price: parseFloat(e.target.value) }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="450.00"
                />
              </div>

              <TaxCategorySelect
                value={formData.tax_category_id}
                onChange={(taxCategoryId) => setFormData(prev => ({ ...prev, tax_category_id: taxCategoryId }))}
                label="Tax Category"
              />
            </div>

            {/* Includes */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                What's Included
              </label>

              {/* Selected Includes */}
              {formData.includes.length > 0 && (
                <div className="mb-4">
                  <div className="flex flex-wrap gap-2">
                    {formData.includes.map((include) => (
                      <span
                        key={include}
                        className="inline-flex items-center gap-1 px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm"
                      >
                        {include}
                        <button
                          type="button"
                          onClick={() => removeInclude(include)}
                          className="ml-1 text-blue-600 hover:text-blue-800"
                        >
                          <Trash2 className="h-3 w-3" />
                        </button>
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {/* Common Includes */}
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 mb-4">
                {commonIncludes.map((include) => (
                  <label key={include} className="flex items-center space-x-2">
                    <input
                      type="checkbox"
                      checked={formData.includes.includes(include)}
                      onChange={(e) => handleIncludeChange(include, e.target.checked)}
                      className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                    />
                    <span className="text-sm text-gray-700">{include}</span>
                  </label>
                ))}
              </div>

              {/* Custom Include */}
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newInclude}
                  onChange={(e) => setNewInclude(e.target.value)}
                  placeholder="Add custom include..."
                  className="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault()
                      addCustomInclude()
                    }
                  }}
                />
                <button
                  type="button"
                  onClick={addCustomInclude}
                  className="px-3 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                >
                  <Plus className="h-4 w-4" />
                </button>
              </div>
            </div>

            {/* Images */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Images
              </label>
              <ImageUpload
                value={formData.images}
                onChange={(urls) => setFormData(prev => ({ ...prev, images: urls }))}
                maxFiles={10}
                bucketName="surf-camp-images"
                storagePath="gallery"
                disabled={saving}
              />
            </div>

            {/* Status */}
            <div>
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={formData.is_active}
                  onChange={(e) => setFormData(prev => ({ ...prev, is_active: e.target.checked }))}
                  className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                />
                <span className="text-sm font-medium text-gray-700">Active (camp is available for booking)</span>
              </label>
            </div>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-lg">
            <p className="text-sm text-red-600">{error}</p>
          </div>
        )}

        {/* Actions */}
        <div className="mt-8 flex justify-end gap-4">
          <Link
            href="/admin/surf-camps"
            className="px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
          >
            Cancel
          </Link>
          <button
            type="submit"
            disabled={saving}
            className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            <Save className="h-4 w-4" />
            {saving ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      </form>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { Plus, Edit, Trash2, Eye, Calendar, Users, Search, Download, UserPlus } from 'lucide-react'
import { RoomCardSkeleton } from '@/components/ui/skeleton-loaders'
import { EnrollmentModal } from '@/components/admin/enrollments/EnrollmentModal'

interface SurfCamp {
  id: string
  name: string
  start_date: string
  end_date: string
  max_participants: number
  enrolled_count: number  // Changed from confirmed_booked to match API
  available_spots: number
  price: number
  level: string
  description: string
  includes: string[]
  images: string[]
  is_active: boolean
}

export default function SurfCampsPage() {
  const [surfCamps, setSurfCamps] = useState<SurfCamp[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [levelFilter, setLevelFilter] = useState('all')
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'inactive' | 'past'>('all')
  const [enrollmentModalOpen, setEnrollmentModalOpen] = useState(false)
  const [selectedCampId, setSelectedCampId] = useState<string>('')

  useEffect(() => {
    fetchSurfCamps()
  }, [])

  const fetchSurfCamps = async () => {
    try {
      setLoading(true)
      setError(null)
      // Admin needs to manage both active + inactive camps
      const response = await fetch('/api/surf-camps?admin=true', {
        credentials: 'include',
      })

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`)
      }

      const data = await response.json()

      if (data.success) {
        const camps = data.data?.surf_camps || data.data || []
        setSurfCamps(Array.isArray(camps) ? camps : [])
      } else {
        setError(data.error || 'Failed to fetch surf weeks')
      }
    } catch (err: unknown) {
      console.error('Error fetching surf weeks:', err)
      const errorMessage = err instanceof Error ? err.message : 'Error loading surf weeks'
      setError(errorMessage)
    } finally {
      setLoading(false)
    }
  }

  const handleDelete = async (campId: string) => {
    if (!confirm('Are you sure you want to delete this surf week? This action cannot be undone.')) return

    try {
      const response = await fetch(`/api/surf-camps/${campId}`, {
        method: 'DELETE',
      })

      const data = await response.json()

      if (data.success) {
        setSurfCamps(surfCamps.filter(camp => camp.id !== campId))
      } else {
        alert('Failed to delete surf week: ' + (data.error || 'Unknown error'))
      }
    } catch (err) {
      console.error('Error deleting surf week:', err)
      alert('Error deleting surf week. Please try again.')
    }
  }

  const toggleActive = async (campId: string) => {
    const camp = surfCamps.find(c => c.id === campId)
    if (!camp) return

    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const endDate = new Date(camp.end_date)
    endDate.setHours(0, 0, 0, 0)
    const isPast = endDate < today
    if (isPast) {
      alert('This surf week has already ended. Past surf weeks are intentionally hidden from the public booking widget, even if activated.')
      return
    }

    // Show confirmation for deactivation
    if (camp.is_active && !confirm('Are you sure you want to deactivate this surf week? It will no longer be available for booking.')) {
      return
    }

    try {
      // Only send database fields, not computed fields like enrolled_count or available_spots
      const updateData = {
        name: camp.name,
        description: camp.description || '',
        start_date: camp.start_date,
        end_date: camp.end_date,
        max_participants: camp.max_participants,
        price: camp.price,
        level: camp.level || 'all',
        includes: camp.includes || [],
        images: camp.images || [],
        is_active: !camp.is_active,
      }

      const response = await fetch(`/api/surf-camps/${campId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(updateData),
      })

      const data = await response.json()

      if (data.success) {
        setSurfCamps(surfCamps.map(c => 
          c.id === campId ? { ...c, is_active: !c.is_active } : c
        ))
      } else {
        alert('Failed to update surf week: ' + (data.error || 'Unknown error'))
      }
    } catch (err) {
      console.error('Error updating surf week:', err)
      alert('Error updating surf week. Please try again.')
    }
  }

  const formatDate = (dateString: string) => {
    // Parse date string as UTC to avoid timezone offset issues
    const [year, month, day] = dateString.split('-').map(Number)
    const date = new Date(Date.UTC(year, month - 1, day))
    return date.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      timeZone: 'UTC'
    })
  }

  const getAvailabilityStatus = (camp: SurfCamp) => {
    // Use available_spots from API if present, otherwise calculate from enrolled_count
    const spotsLeft = camp.available_spots ?? (camp.max_participants - (camp.enrolled_count || 0))
    if (spotsLeft <= 0) return { text: 'Fully Booked', color: 'bg-red-100 text-red-800' }
    if (spotsLeft <= 3) return { text: `${spotsLeft} Spots Left`, color: 'bg-orange-100 text-orange-800' }
    return { text: `${spotsLeft} Available`, color: 'bg-green-100 text-green-800' }
  }

  if (loading) {
    return (
      <div className="p-8">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">Surf Weeks Management</h1>
          <p className="text-gray-600 mt-2">Manage your surf week programs</p>
        </div>

      {/* Explanation */}
      <div className="bg-heiwaOrange-50 border border-heiwaOrange-200 rounded-lg p-4">
        <p className="text-sm text-heiwaOrange-900">
          Public booking only shows surf weeks that are <span className="font-semibold">Active</span> and <span className="font-semibold">not ended</span>.
          Past surf weeks are kept here for reference and reporting.
        </p>
      </div>

      {/* Status Filters */}
      <div className="flex flex-wrap gap-2">
        <button
          type="button"
          onClick={() => setStatusFilter('all')}
          className={
            statusFilter === 'all'
              ? 'px-3 py-1.5 rounded-full bg-gray-900 text-white text-sm'
              : 'px-3 py-1.5 rounded-full bg-gray-100 text-gray-800 text-sm hover:bg-gray-200'
          }
        >
          All
        </button>
        <button
          type="button"
          onClick={() => setStatusFilter('active')}
          className={
            statusFilter === 'active'
              ? 'px-3 py-1.5 rounded-full bg-green-700 text-white text-sm'
              : 'px-3 py-1.5 rounded-full bg-green-50 text-green-800 text-sm hover:bg-green-100'
          }
        >
          Active
        </button>
        <button
          type="button"
          onClick={() => setStatusFilter('inactive')}
          className={
            statusFilter === 'inactive'
              ? 'px-3 py-1.5 rounded-full bg-yellow-700 text-white text-sm'
              : 'px-3 py-1.5 rounded-full bg-yellow-50 text-yellow-800 text-sm hover:bg-yellow-100'
          }
        >
          Inactive
        </button>
        <button
          type="button"
          onClick={() => setStatusFilter('past')}
          className={
            statusFilter === 'past'
              ? 'px-3 py-1.5 rounded-full bg-gray-700 text-white text-sm'
              : 'px-3 py-1.5 rounded-full bg-gray-50 text-gray-800 text-sm hover:bg-gray-100'
          }
        >
          Past
        </button>
      </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {Array.from({ length: 6 }).map((_, i) => (
            <RoomCardSkeleton key={i} />
          ))}
        </div>
      </div>
    )
  }

  // Filter surf weeks
  const filteredCamps = surfCamps.filter(camp => {
    const matchesSearch = camp.name.toLowerCase().includes(searchTerm.toLowerCase())
    const matchesLevel = levelFilter === 'all' || camp.level === levelFilter

    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const endDate = new Date(camp.end_date)
    endDate.setHours(0, 0, 0, 0)
    const isPast = endDate < today
    const isInactive = !camp.is_active

    const matchesStatus =
      statusFilter === 'all'
        ? true
        : statusFilter === 'past'
          ? isPast
          : statusFilter === 'inactive'
            ? (!isPast && isInactive)
            : (!isPast && !isInactive)

    return matchesSearch && matchesLevel && matchesStatus
  })

  if (error) {
    return (
      <div className="p-8">
        <div className="text-center">
          <h1 className="text-3xl font-bold text-gray-900 mb-4">Error</h1>
          <p className="text-gray-600 mb-4">{error}</p>
          <button 
