import { NextRequest, NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase'

interface Enrollment {
  id: string
  client_id: string
  status: string
  skill_level: string
  participant_name: string
  participant_email: string
  participant_phone: string
}

interface Client {
  id: string
  name: string
  email: string
  phone: string
}

interface RoomAssignment {
  id: string
  enrollment_id: string
  room_id: string
  bed_number: number
  rooms?: Array<{
    id: string
    name: string
    booking_type: string
    capacity: number
  }>
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const weekId = searchParams.get('weekId')

    if (!weekId) {
      return NextResponse.json(
        { error: 'weekId is required' },
        { status: 400 }
      )
    }

    // Validate UUID format
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
    if (!uuidRegex.test(weekId)) {
      console.error('Invalid weekId format:', weekId)
      return NextResponse.json(
        { error: 'Invalid weekId format', details: 'weekId must be a valid UUID' },
        { status: 400 }
      )
    }

    // Fetch enrollments for this surf camp
    // Include both 'pending' and 'confirmed' status enrollments
    const { data: enrollments, error: enrollmentsError } = await supabaseAdmin
      .from('surf_camp_enrollments')
      .select(`
        id,
        client_id,
        status,
        skill_level,
        participant_name,
        participant_email,
        participant_phone
      `)
      .eq('surf_camp_id', weekId)
      .in('status', ['pending', 'confirmed'])

    if (enrollmentsError) {
      console.error('Error fetching enrollments:', {
        error: enrollmentsError,
        code: enrollmentsError.code,
        message: enrollmentsError.message,
        details: enrollmentsError.details,
        hint: enrollmentsError.hint,
        weekId
      })
      return NextResponse.json(
        { 
          error: 'Failed to fetch participants', 
          details: enrollmentsError.message,
          code: enrollmentsError.code,
          hint: enrollmentsError.hint || 'Check if surf_camp_enrollments table exists and RLS policies allow access'
        },
        { status: 500 }
      )
    }

    if (!enrollments || enrollments.length === 0) {
      console.log(`No enrollments found for weekId: ${weekId}`)
      return NextResponse.json([])
    }

    // Fetch clients separately to avoid foreign key join issues
    const clientIds = enrollments.map((e: Enrollment) => e.client_id).filter(Boolean)
    let clientMap = new Map<string, Client>()

    if (clientIds.length > 0) {
      const { data: clients, error: clientsError } = await supabaseAdmin
        .from('clients')
        .select('id, name, email, phone')
        .in('id', clientIds)

      if (clientsError) {
        console.error('Error fetching clients:', {
          error: clientsError,
          code: clientsError.code,
          message: clientsError.message,
          clientIds: clientIds.slice(0, 5) // Log first 5 IDs
        })
        // Continue without client details rather than failing
      } else if (clients) {
        clients.forEach((client: Client) => {
          clientMap.set(client.id, client)
        })
        console.log(`Successfully fetched ${clients.length} clients for ${clientIds.length} enrollments`)
      }
    }

    // Fetch room assignments for these enrollments
    const enrollmentIds = enrollments.map((e: Enrollment) => e.id)
    let roomAssignmentMap = new Map<string, {
      roomId: string
      roomName: string
      roomType: string
      bedNumber: number
    }>()

    if (enrollmentIds.length > 0) {
      const { data: roomAssignments, error: raError } = await supabaseAdmin
        .from('room_assignments')
        .select(`
          id,
          enrollment_id,
          room_id,
          bed_number,
          rooms:room_id (
            id,
            name,
            booking_type,
            capacity
          )
        `)
        .in('enrollment_id', enrollmentIds)

      if (!raError && roomAssignments) {
        roomAssignments.forEach((ra: RoomAssignment) => {
          roomAssignmentMap.set(ra.enrollment_id, {
            roomId: ra.room_id,
            roomName: ra.rooms && ra.rooms[0] ? ra.rooms[0].name : 'Unassigned',
            roomType: ra.rooms && ra.rooms[0] && ra.rooms[0].booking_type === 'perBed' ? 'dorm' : 'private',
            bedNumber: ra.bed_number
          })
        })
      }
    }

    // Transform enrollments to participants format
    const participants = enrollments.map((enrollment: Enrollment) => {
      const client = clientMap.get(enrollment.client_id)
      const roomAssignment = roomAssignmentMap.get(enrollment.id)

      return {
        id: enrollment.id, // Use enrollment ID as participant ID
        name: client?.name || enrollment.participant_name || 'Unknown',
        email: client?.email || enrollment.participant_email || '',
        phone: client?.phone || enrollment.participant_phone || '',
        surfLevel: enrollment.skill_level || 'Beginner',
        clientId: enrollment.client_id,
        status: enrollment.status,
        // Room assignment info
        roomId: roomAssignment?.roomId || null,
        roomName: roomAssignment?.roomName || 'Not Assigned',
        roomType: roomAssignment?.roomType || null,
        bedNumber: roomAssignment?.bedNumber || null
      }
    })

    return NextResponse.json(participants)
  } catch (error: unknown) {
    console.error('Unexpected error in participants API:', {
      error: error instanceof Error ? error.message : 'Unknown error',
      stack: error instanceof Error ? error.stack : undefined,
      name: error instanceof Error ? error.name : undefined
    })
    return NextResponse.json(
      { 
        error: 'Internal server error',
        details: error instanceof Error ? error.message : 'Unknown error occurred'
      },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase'

interface Assignment {
  room_id: string
}

interface Room {
  id: string
  name: string
  capacity: number
  booking_type: string
  amenities: string[]
  is_active: boolean
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const weekId = searchParams.get('weekId')

    // Fetch all active rooms
    const { data: rooms, error: roomsError } = await supabaseAdmin
      .from('rooms')
      .select('id, name, capacity, booking_type, amenities, is_active')
      .eq('is_active', true)
      .order('name', { ascending: true })

    if (roomsError) {
      console.error('Error fetching rooms:', roomsError)
      return NextResponse.json(
        { error: 'Failed to fetch rooms', details: roomsError.message },
        { status: 500 }
      )
    }

    // Fetch current room assignments to calculate occupancy
    let occupancyMap = new Map<string, number>()

    if (weekId) {
      // Get assignments for specific surf camp week
      const { data: assignments, error: assignmentsError } = await supabaseAdmin
        .from('room_assignments')
        .select('room_id')
        .eq('surf_camp_id', weekId)
        .eq('status', 'confirmed')

      if (!assignmentsError && assignments) {
        assignments.forEach((a: Assignment) => {
          const count = occupancyMap.get(a.room_id) || 0
          occupancyMap.set(a.room_id, count + 1)
        })
      }
    } else {
      // Get all current active assignments (check-in <= today <= check-out)
      const today = new Date().toISOString().split('T')[0]
      const { data: assignments, error: assignmentsError } = await supabaseAdmin
        .from('room_assignments')
        .select('room_id')
        .lte('check_in_date', today)
        .gte('check_out_date', today)
        .eq('status', 'confirmed')

      if (!assignmentsError && assignments) {
        assignments.forEach((a: Assignment) => {
          const count = occupancyMap.get(a.room_id) || 0
          occupancyMap.set(a.room_id, count + 1)
        })
      }
    }

    // Transform rooms to assignment format with actual occupancy
    const transformedRooms = (rooms || []).map((room: Room) => ({
      id: room.id,
      name: room.name,
      capacity: room.capacity || 1,
      type: room.booking_type === 'perBed' ? 'dorm' : 'private',
      amenities: room.amenities || [],
      currentOccupancy: occupancyMap.get(room.id) || 0,
      availableSpots: (room.capacity || 1) - (occupancyMap.get(room.id) || 0)
    }))

    return NextResponse.json(transformedRooms)
  } catch (error) {
    console.error('Error in rooms API:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase'

// Public endpoint for widget to fetch active price settings
export async function GET(request: NextRequest) {
  try {
    const { data, error } = await supabaseAdmin
      .from('booking_widget_settings')
      .select('experience_type, price_from')
      .eq('is_active', true)

    if (error) {
      console.error('Error fetching booking widget settings:', error)
      return NextResponse.json(
        { success: false, error: error.message || 'Failed to fetch settings' },
        { status: 500 }
      )
    }

    // Transform to object format for easier consumption
    const settings = {
      room: 45, // fallback
      surfWeek: 599 // fallback
    }

    if (data && data.length > 0) {
      data.forEach((setting: { experience_type: string; price_from: number }) => {
        if (setting.experience_type === 'room') {
          settings.room = setting.price_from
        } else if (setting.experience_type === 'surf-week') {
          settings.surfWeek = setting.price_from
        }
      })
    }

    return NextResponse.json({
      success: true,
      data: settings
    }, {
      headers: {
        'Cache-Control': 'public, s-maxage=300, stale-while-revalidate=600'
      }
    })
  } catch (error) {
    console.error('Error in GET booking widget settings:', error)
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Internal server error',
        data: {
          room: 45,
          surfWeek: 599
        }
      },
      { status: 500 }
    )
  }
}

// Booking API - Individual booking operations

import { NextRequest, NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase'
import type { Booking, UpdateBooking } from '@/lib/database.types'
import type { Participant } from '@/lib/types/api.types'
import { requireAdminAuth } from '@/lib/admin-auth'

// GET /api/bookings/[id] - Get a specific booking
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params
    const authError = requireAdminAuth(request)
    if (authError) return authError

    const { data, error } = await supabaseAdmin
      .from('bookings')
      .select('*')
      .eq('id', id)
      .single()

    if (error) {
      if (error.code === 'PGRST116') {
        return NextResponse.json(
          { success: false, error: 'Booking not found' },
          { status: 404 }
        )
      }
      console.error('Error fetching booking:', error)
      return NextResponse.json(
        { success: false, error: 'Failed to fetch booking' },
        { status: 500 }
      )
    }

    // Fetch client details
    let guestName = 'Unknown'
    let guestEmail = ''
    let guestPhone = ''
    let clientNotes = ''

    if (data.client_ids && data.client_ids.length > 0) {
      const firstClientId = data.client_ids[0]
      const { data: client } = await supabaseAdmin
        .from('clients')
        .select('id, name, email, phone, notes')
        .eq('id', firstClientId)
        .single()

      if (client) {
        guestName = client.name || 'Unknown'
        guestEmail = client.email || ''
        guestPhone = client.phone || ''
        clientNotes = client.notes || ''
      }
    }

    // Parse notes to extract dietary preferences
    let dietaryPreferences = ''
    let specialRequests = data.notes || ''

    try {
      const notesData = data.notes ? JSON.parse(data.notes) : null
      if (notesData && typeof notesData === 'object') {
        dietaryPreferences = notesData.dietaryRequirements || notesData.dietary || notesData.diet || ''
        specialRequests = notesData.specialRequests || notesData.requests || notesData.message || data.notes || ''
      } else if (data.notes) {
        const notesLower = data.notes.toLowerCase()
        if (notesLower.includes('diet') || notesLower.includes('vegetarian') || notesLower.includes('vegan') || notesLower.includes('gluten')) {
          specialRequests = data.notes
        }
      }
    } catch {
      specialRequests = data.notes || ''
    }

    // Transform to admin UI format
    const transformedBooking = {
      id: data.id,
      guest_name: guestName,
      guest_email: guestEmail,
      guest_phone: guestPhone,
      type: data.room_type ? 'room' : 'surf_camp',
      item_name: data.room_type || 'Unknown',
      check_in: data.check_in || '',
      check_out: data.check_out || '',
      guests: data.guests || 1,
      total_price: data.total_amount || 0,
      status: data.status || 'pending',
      payment_status: data.payment_status || 'pending',
      created_at: data.created_at,
      special_requests: specialRequests,
      dietary_preferences: dietaryPreferences,
      client_notes: clientNotes,
      notes: data.notes || ''
    }

    return NextResponse.json({
      success: true,
      data: { booking: transformedBooking }
    })
  } catch (error) {
    console.error('Unexpected error:', error)
    return NextResponse.json(
      { success: false, error: 'Internal server error' },
      { status: 500 }
    )
  }
}

// PUT /api/bookings/[id] - Update a booking
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params
    const authError = requireAdminAuth(request)
    if (authError) return authError

    const body = await request.json()

    // Get the existing booking first
    const { data: existingBooking, error: fetchError } = await supabaseAdmin
      .from('bookings')
      .select('*')
      .eq('id', id)
      .single()

    if (fetchError || !existingBooking) {
      return NextResponse.json(
        { success: false, error: 'Booking not found' },
        { status: 404 }
      )
    }

    // Transform admin UI format back to database format
    // The bookings table uses: room_type, check_in, check_out, guests, total_amount, status, payment_status, notes
    const updateData: UpdateBooking = {
      updated_at: new Date().toISOString()
    }

    // Update status if provided
    if (body.status !== undefined) {
      updateData.status = body.status
    }

    // Update payment_status if provided
    if (body.payment_status !== undefined) {
      updateData.payment_status = body.payment_status
    }

    // Update total_amount if provided
    if (body.total_price !== undefined) {
      updateData.total_amount = body.total_price
    }

    // Update notes if provided (preserve JSON structure if it exists)
    if (body.special_requests !== undefined) {
      // If existing notes are JSON, try to preserve structure
      try {
        const existingNotes = existingBooking.notes ? JSON.parse(existingBooking.notes) : null
        if (existingNotes && typeof existingNotes === 'object' && existingNotes.participants) {
          // Preserve JSON structure, only update if it's a simple string
          // Don't overwrite JSON notes with plain text
          console.log('Preserving JSON notes structure')
        } else {
          // Plain text notes, update normally
          updateData.notes = body.special_requests
        }
      } catch {
        // Not JSON, update as plain text
        updateData.notes = body.special_requests
      }
    }

    // Update room_type if provided (for room bookings)
    if (body.type === 'room' && body.item_name !== undefined) {
      updateData.room_type = body.item_name
    } else if (body.type === 'surf_camp') {
      // Surf camp bookings have room_type = null
      updateData.room_type = null
    }

    // Update check_in if provided
    if (body.check_in !== undefined) {
      updateData.check_in = body.check_in
    }

    // Update check_out if provided
    if (body.check_out !== undefined) {
      updateData.check_out = body.check_out
    }

    // Update guests if provided
    if (body.guests !== undefined) {
      updateData.guests = body.guests
    }

    // Update booking
    const { data, error } = await supabaseAdmin
      .from('bookings')
      .update(updateData)
      .eq('id', id)
      .select()
      .single()

    if (error) {
      console.error('Error updating booking:', error)
      console.error('Update data attempted:', updateData)
      return NextResponse.json(
        { success: false, error: 'Failed to update booking', details: error.message },
        { status: 500 }
      )
    }

    // Fetch client details for response transformation
    let guestName = 'Unknown'
    let guestEmail = ''
    let guestPhone = ''

    if (data.client_ids && data.client_ids.length > 0) {
      const firstClientId = data.client_ids[0]
      const { data: client } = await supabaseAdmin
        .from('clients')
        .select('id, name, email, phone')
        .eq('id', firstClientId)
        .single()

      if (client) {
        guestName = client.name || 'Unknown'
        guestEmail = client.email || ''
        guestPhone = client.phone || ''
      }
    }

    // Parse notes for special requests
    let specialRequests = data.notes || ''
    try {
      const notesData = data.notes ? JSON.parse(data.notes) : null
      if (notesData && typeof notesData === 'object' && notesData.participants) {
        // JSON format with participants - aggregate special requests
        specialRequests = notesData.participants
          .map((p: Participant) => p.specialRequests)
          .filter(Boolean)
          .join('\n\n')
      }
    } catch {
      // Not JSON, use as-is
      specialRequests = data.notes || ''
    }

    // Transform response back to admin UI format
    const transformedBooking = {
      id: data.id,
      guest_name: guestName,
      guest_email: guestEmail,
      guest_phone: guestPhone,
      type: data.room_type ? 'room' : 'surf_camp',
      item_name: data.room_type || 'Unknown',
      check_in: data.check_in || '',
      check_out: data.check_out || '',
      guests: data.guests || 1,
      total_price: data.total_amount || 0,
      status: data.status || 'pending',
      payment_status: data.payment_status || 'pending',
      created_at: data.created_at,
      special_requests: specialRequests,
      notes: data.notes || ''
    }

    return NextResponse.json({
      success: true,
      data: { booking: transformedBooking }
    })
  } catch (error) {
    console.error('Unexpected error:', error)
    return NextResponse.json(
      { success: false, error: 'Internal server error' },
      { status: 500 }
    )
  }
}

// PATCH /api/bookings/[id] - Partial update of a booking (e.g., status change)
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params
    const authError = requireAdminAuth(request)
    if (authError) return authError

    const body = await request.json()

    // Get the existing booking first
    const { data: existingBooking, error: fetchError } = await supabaseAdmin
      .from('bookings')
      .select('*')
      .eq('id', id)
      .single()

    if (fetchError || !existingBooking) {
      return NextResponse.json(
        { success: false, error: 'Booking not found' },
        { status: 404 }
      )
    }

    // Build partial update object - only update provided fields
    const updateData: UpdateBooking = {
      updated_at: new Date().toISOString()
    }

    if (body.status !== undefined) {
      updateData.status = body.status
    }
    if (body.payment_status !== undefined) {
      updateData.payment_status = body.payment_status
    }
    if (body.notes !== undefined) {
      updateData.notes = body.notes
    }

    // Update booking
    const { data, error } = await supabaseAdmin
      .from('bookings')
      .update(updateData)
      .eq('id', id)
      .select()
      .single()

    if (error) {
      console.error('Error updating booking:', error)
