          >
            {/* Header - Enhanced with subtle gradient */}
            <div className="flex items-center justify-between p-4 sm:p-5 md:p-6 border-b border-gray-200 bg-gradient-to-r from-gray-50 to-white">
              <h2 className="text-2xl font-bold text-gray-900">
                Book Your Surf Adventure
              </h2>
              <button
                onClick={closeWidget}
                className="p-2 rounded-lg text-gray-500 hover:text-gray-700 hover:bg-gray-100 transition-all duration-micro focus:outline-none focus:ring-2 focus:ring-accent/30 focus:ring-offset-2 min-w-[44px] min-h-[44px] flex items-center justify-center active:scale-95"
                aria-label="Close booking widget"
              >
                <X size={20} />
              </button>
            </div>

            {/* Progress Indicator */}
            <div className="px-4 sm:px-5 md:px-6 py-3 sm:py-4 bg-gray-50 border-b border-gray-200">
              <ProgressIndicator
                currentStep={computed.currentStep}
                stepFlow={computed.stepFlow}
                totalSteps={computed.totalSteps}
                skippedSteps={state.skippedSteps}
                onStepClick={actions.jumpToStep}
              />
            </div>

            {/* Content - Wrapped in error boundary for graceful error handling */}
            <div ref={contentScrollRef} className="flex-1 overflow-y-auto relative shadow-inner">
              <BookingErrorBoundary onReset={actions.reset}>
              <div className="p-3 sm:p-4 md:p-6 lg:p-8">
                {bookingSuccess ? (
                  <div className="text-center space-y-6 animate-fade-in-up">
                    {/* Confetti celebration */}
                    <Confetti isActive={!!bookingSuccess} count={60} duration={3000} />

                    {/* Success Icon with animation */}
                    <div className="relative">
                      <div className="w-20 h-20 bg-success-light rounded-full flex items-center justify-center mx-auto animate-bounce-in">
                        <CheckCircle size={40} className="text-success animate-check-mark" />
                      </div>
                      {/* Pulsing ring effect */}
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-20 h-20 rounded-full border-4 border-success/20 animate-ping" />
                      </div>
                    </div>

                    <div className="space-y-4">
                      <div>
                        <h3 className="text-2xl sm:text-3xl font-bold text-gray-900 mb-2">
                          Booking Confirmed! 🎉
                        </h3>
                        <p className="text-base text-gray-600">
                          Booking #{bookingSuccess.booking?.booking_number || 'N/A'}
                        </p>
                      </div>

                      {/* Premium Booking Details Card */}
                      <div className="bg-gradient-to-br from-gray-50 to-white rounded-xl p-6 border border-gray-200 shadow-card text-left max-w-md mx-auto animate-slide-in-up">
                        <h4 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
                          <span className="w-8 h-8 bg-accent/10 rounded-lg flex items-center justify-center">
                            <Calendar size={16} className="text-accent" />
                          </span>
                          Booking Details
                        </h4>

                        <div className="space-y-3">
                          {/* Booking Type */}
                          <div className="flex justify-between items-center py-2 border-b border-gray-100">
                            <span className="text-sm text-gray-500">Type</span>
                            <span className="font-medium text-gray-900">
                              {state.experienceType === 'room' ? 'Room Booking' : 'Surf Week Package'}
                            </span>
                          </div>

                          {/* Dates */}
                          {state.dates.checkIn && state.dates.checkOut && (
                            <div className="flex justify-between items-center py-2 border-b border-gray-100">
                              <span className="text-sm text-gray-500">Dates</span>
                              <span className="font-medium text-gray-900 text-right">
                                {formatDateUTC(state.dates.checkIn)} - {formatDateUTC(state.dates.checkOut)}
                              </span>
                            </div>
                          )}

                          {/* Guests */}
                          <div className="flex justify-between items-center py-2 border-b border-gray-100">
                            <span className="text-sm text-gray-500">Guests</span>
                            <span className="font-medium text-gray-900">{state.guests}</span>
                          </div>

                          {/* Payment Method */}
                          <div className="flex justify-between items-center py-2 border-b border-gray-100">
                            <span className="text-sm text-gray-500">Payment</span>
                            <span className="font-medium text-gray-900">
                              {state.paymentMethod === 'card_stripe' ? 'Credit Card' : 'Bank Transfer'}
                            </span>
                          </div>

                          {/* Total Amount - Highlighted */}
                          <div className="flex justify-between items-center pt-3 mt-2 border-t-2 border-gray-200">
                            <span className="text-base font-medium text-gray-700">Total Paid</span>
                            <span className="text-2xl font-bold text-success">
                              €{state.pricing.total?.toFixed(2) || '0.00'}
                            </span>
                          </div>
                        </div>
                      </div>

                      {/* Next Steps Card */}
                      <div className="bg-info-light rounded-xl p-5 text-left max-w-md mx-auto border border-info/20 animate-slide-in-up" style={{ animationDelay: '100ms' }}>
                        <h4 className="font-semibold text-info-dark mb-3 flex items-center gap-2">
                          <Info size={18} />
                          What's Next?
                        </h4>
                        <ul className="text-sm text-info-dark space-y-2">
                          {state.paymentMethod === 'card_stripe' ? (
                            <>
                              <li className="flex items-start gap-2">
                                <span className="text-info mt-0.5">✓</span>
                                <span>Payment processing will complete shortly</span>
                              </li>
                              <li className="flex items-start gap-2">
                                <span className="text-info mt-0.5">✓</span>
                                <span>Confirmation email sent to your inbox</span>
                              </li>
                              <li className="flex items-start gap-2">
                                <span className="text-info mt-0.5">✓</span>
                                <span>Check your email for booking details</span>
                              </li>
                            </>
                          ) : (
                            <>
                              <li className="flex items-start gap-2">
                                <span className="text-info mt-0.5">✓</span>
                                <span>Confirmation email sent to your inbox</span>
                              </li>
                              <li className="flex items-start gap-2">
                                <span className="text-info mt-0.5">→</span>
                                <span>Complete bank transfer within 24 hours</span>
                              </li>
                              <li className="flex items-start gap-2">
                                <span className="text-info mt-0.5">→</span>
                                <span>Send transfer confirmation to bookings@heiwahouse.com</span>
                              </li>
                            </>
                          )}
                        </ul>
                      </div>
                    </div>

                    {/* Close Button - Prominent styling */}
                    <Button
                      variant="success"
                      size="lg"
                      onClick={closeWidget}
                      className="w-full max-w-xs mx-auto shadow-lg shadow-success/20 hover:shadow-xl hover:shadow-success/30"
                    >
                      Close & Return to Site
                    </Button>
                  </div>
                ) : (
                  renderCurrentStep()
                )}
              </div>
              </BookingErrorBoundary>
            </div>

            {/* Footer Navigation */}
            {!bookingSuccess && computed.currentStepType !== 'review-pay' && (
              <div className="flex items-center justify-between px-4 sm:px-5 md:px-6 py-3 sm:py-4 border-t border-gray-200 bg-white">
                <div className="relative group">
                  {/* Back Button - Tailwind styled */}
                  <Button
                    variant="outline"
                    size="lg"
                    onClick={actions.prevStep}
                    disabled={computed.isFirstStep}
                    aria-label="Go back to previous step"
                    className="gap-2"
                  >
                    <ArrowLeft size={16} className="flex-shrink-0" />
                    <span>Back</span>
                  </Button>

                  {/* Tooltip */}
                  {!computed.isFirstStep && (
                    <div className="
                      absolute bottom-full left-1/2 transform -translate-x-1/2 mb-2
                      px-3 py-2 bg-gray-900 text-white text-xs rounded-lg
                      opacity-0 group-hover:opacity-100 transition-opacity duration-micro
                      pointer-events-none whitespace-nowrap z-50
                    ">
                      <div className="flex items-center gap-2">
                        <Info size={12} />
                        <span>Edit previous step</span>
                      </div>
                      {/* Arrow */}
                      <div className="absolute top-full left-1/2 transform -translate-x-1/2 -mt-1">
                        <div className="border-4 border-transparent border-t-gray-900" />
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex items-center gap-3 sm:gap-4">
                  <div className="text-right">
                    <div className="text-lg sm:text-xl font-bold text-gray-900">
                      €{state.pricing.total?.toFixed(2) || '0.00'}
                    </div>
                    <div className="text-sm text-gray-500 hidden sm:block">Total</div>
                  </div>

                  {/* Next Button - Using Button component with loading state */}
                  <Button
                    size="lg"
                    onClick={actions.nextStep}
                    disabled={!computed.canProceedToNextStep || state.isLoading}
                    isLoading={state.isLoading}
                    loadingText="Loading..."
                    aria-label={computed.isLastStep ? 'Complete booking' : 'Continue to next step'}
                    className={computed.isLastStep ? '' : 'pl-8 pr-6'}
                  >
                    {computed.isLastStep ? (
                      'Complete Booking'
                    ) : (
                      <>
                        <span>Next</span>
                        <ArrowRight size={16} />
                      </>
                    )}
                  </Button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { ChevronLeft, ChevronRight, X, ZoomIn, Users, ImageOff } from 'lucide-react';

// Local fallback images from the property
export const FALLBACK_IMAGES = [
  '/images/rooms/room1.jpg',
  '/images/rooms/room2.webp',
  '/images/rooms/room3.webp',
  '/images/rooms/dorm.webp',
  '/images/DSC02099-scaled.jpg',
  '/images/DSC03521-scaled.jpg',
];

// Image loading states
export type ImageLoadState = 'loading' | 'loaded' | 'error' | 'fallback';

interface ImageWithFallbackProps {
  src: string;
  alt: string;
  fallbackIndex?: number;
  className?: string;
  onLoadComplete?: () => void;
}

/**
 * Robust image component with fallback chain and loading states
 * Prevents broken image icons by gracefully handling errors
 */
export function ImageWithFallback({
  src,
  alt,
  fallbackIndex = 0,
  className = '',
  onLoadComplete,
}: ImageWithFallbackProps) {
  // If no src provided, start with fallback immediately
  const initialSrc = src && src.trim() !== '' ? src : FALLBACK_IMAGES[fallbackIndex % FALLBACK_IMAGES.length];
  const [loadState, setLoadState] = useState<ImageLoadState>(src && src.trim() !== '' ? 'loading' : 'fallback');
  const [currentSrc, setCurrentSrc] = useState(initialSrc);
  const [fallbackAttempt, setFallbackAttempt] = useState(src && src.trim() !== '' ? 0 : 1);

  // Reset state when src changes
  useEffect(() => {
    if (src && src.trim() !== '' && src !== currentSrc) {
      setCurrentSrc(src);
      setLoadState('loading');
      setFallbackAttempt(0);
    } else if (!src || src.trim() === '') {
      // If src becomes empty, use fallback
      setCurrentSrc(FALLBACK_IMAGES[fallbackIndex % FALLBACK_IMAGES.length]);
      setLoadState('fallback');
      setFallbackAttempt(1);
    }
  }, [src, currentSrc, fallbackIndex]);

  const handleLoad = useCallback(() => {
    setLoadState(fallbackAttempt > 0 ? 'fallback' : 'loaded');
    onLoadComplete?.();
  }, [fallbackAttempt, onLoadComplete]);

  const handleError = useCallback(() => {
    // Try next fallback image
    if (fallbackAttempt < FALLBACK_IMAGES.length) {
      const nextFallback = FALLBACK_IMAGES[(fallbackIndex + fallbackAttempt) % FALLBACK_IMAGES.length];
      setCurrentSrc(nextFallback);
      setFallbackAttempt(prev => prev + 1);
    } else {
      // All fallbacks exhausted
      setLoadState('error');
    }
  }, [fallbackAttempt, fallbackIndex]);

  // Show placeholder for error state
  if (loadState === 'error') {
    return (
      <div className={`flex items-center justify-center bg-gray-200 ${className}`}>
        <ImageOff className="text-gray-400" size={24} />
      </div>
    );
  }

  return (
    <>
      {loadState === 'loading' && (
        <div className={`absolute inset-0 flex items-center justify-center bg-gray-100 animate-pulse ${className}`}>
          <div className="w-8 h-8 border border-gray-300 border-t-gray-600 rounded-full animate-spin" />
        </div>
      )}
      <img
        src={currentSrc}
        alt={alt}
        className={`${className} ${loadState === 'loading' ? 'opacity-0' : 'opacity-100'} transition-opacity duration-200`}
        onLoad={handleLoad}
        onError={handleError}
      />
    </>
  );
}

interface RoomImageGalleryProps {
  images: string[];
  roomName: string;
  roomDescription?: string;
  roomAmenities?: string[];
  roomType?: string;
  maxOccupancy?: number;
  pricePerNight?: number;
  isOpen: boolean;
  onClose: () => void;
}

export function RoomImageGallery({
  images,
  roomName,
  roomDescription,
  roomAmenities,
  roomType,
  maxOccupancy,
  pricePerNight,
  isOpen,
  onClose
}: RoomImageGalleryProps) {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  // Keyboard navigation
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      switch (e.key) {
        case 'ArrowLeft':
          setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
          break;
        case 'ArrowRight':
          setCurrentImageIndex((prev) => (prev + 1) % images.length);
          break;
        case 'Escape':
          onClose();
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, images.length, onClose]);

  if (!isOpen || images.length === 0) return null;

  const nextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const goToImage = (index: number) => {
    setCurrentImageIndex(index);
  };

  return (
    <div 
      className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-90"
      role="dialog"
      aria-modal="true"
      aria-label={`Image gallery for ${roomName}`}
    >
      <div className="relative w-full h-full max-w-6xl max-h-screen p-4 flex flex-col">
        {/* Main image area - full width */}
        <div className="relative flex-1 min-h-0">
          {/* Close button - improved touch target */}
          <button
            onClick={onClose}
            aria-label="Close gallery"
            className="absolute top-4 right-4 z-10 p-3 min-w-[44px] min-h-[44px] bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full text-white motion-safe:transition-all motion-safe:duration-200 motion-reduce:transition-none focus:outline-none focus:ring-2 focus:ring-white/50"
          >
            <X size={24} />
          </button>

          {/* Room name and image counter */}
          <div className="absolute top-4 left-4 z-10 bg-black bg-opacity-50 px-4 py-2 rounded-lg">
            <h3 className="text-white text-lg font-semibold">{roomName}</h3>
            <p className="text-white text-sm opacity-80">
              {currentImageIndex + 1} of {images.length}
            </p>
          </div>

          {/* Main image */}
          <div className="relative w-full h-full flex items-center justify-center">
            <ImageWithFallback
              src={images[currentImageIndex]}
              alt={`${roomName} - ${currentImageIndex + 1}`}
              fallbackIndex={currentImageIndex}
              className="max-w-full max-h-full object-contain rounded-lg"
            />

            {/* Navigation arrows - improved touch targets (min 44px) */}
            {images.length > 1 && (
              <>
                <button
                  onClick={prevImage}
                  aria-label="Previous image"
                  className="absolute left-2 sm:left-4 top-1/2 transform -translate-y-1/2 p-3 min-w-[44px] min-h-[44px] bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full text-white motion-safe:transition-all motion-safe:duration-200 motion-reduce:transition-none focus:outline-none focus:ring-2 focus:ring-white/50"
                >
                  <ChevronLeft size={24} />
                </button>
                <button
                  onClick={nextImage}
                  aria-label="Next image"
                  className="absolute right-2 sm:right-4 top-1/2 transform -translate-y-1/2 p-3 min-w-[44px] min-h-[44px] bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full text-white motion-safe:transition-all motion-safe:duration-200 motion-reduce:transition-none focus:outline-none focus:ring-2 focus:ring-white/50"
                >
                  <ChevronRight size={24} />
                </button>
              </>
            )}
          </div>

          {/* Thumbnail navigation - improved touch targets (min 44px) */}
          {images.length > 1 && (
            <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex gap-2 bg-black bg-opacity-50 p-3 rounded-lg max-w-[90%] overflow-x-auto scrollbar-thin scrollbar-thumb-white/30 scrollbar-track-transparent">
              {/* Scroll indicator for mobile */}
              {images.length > 4 && (
                <div className="absolute -top-6 left-1/2 transform -translate-x-1/2 text-white/60 text-xs">
                  Swipe to see more →
                </div>
              )}
              {images.map((image, index) => (
                <button
                  key={`${roomName}-thumb-${index}`}
                  onClick={() => goToImage(index)}
                  aria-label={`View image ${index + 1} of ${images.length}`}
                  aria-current={index === currentImageIndex ? 'true' : undefined}
