                                      ? 'bg-accent border-accent'
                                      : 'bg-white/90 backdrop-blur-sm border-gray-300'
                                  }`}
                                >
                                  {isSelected && (
                                    <Check size={14} className="text-white stroke-[3]" />
                                  )}
                                </div>
