interface BulkActionsProps {
  selectedCount: number
  totalCount: number
  onSelectAll: () => void
  onDeselectAll: () => void
  actions: Array<{
    label: string
    icon?: React.ReactNode
    onClick: () => void
    variant?: 'default' | 'destructive'
    disabled?: boolean
  }>
  className?: string
}

export function BulkActions({
  selectedCount,
  totalCount,
  onSelectAll,
  onDeselectAll,
  actions,
  className = '',
}: BulkActionsProps) {
  const [showActions, setShowActions] = useState(false)

  if (selectedCount === 0) {
    return null
  }

  return (
    <div data-testid="bulk-actions" className={`bg-blue-50 border border-blue-200 rounded-lg p-4 ${className}`}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <span className="text-sm font-medium text-blue-900">
            {selectedCount} of {totalCount} selected
          </span>
          <div className="flex items-center gap-2">
            <button
              onClick={onSelectAll}
              className="text-sm text-blue-600 hover:text-blue-800 underline"
            >
              Select all
            </button>
            <span className="text-blue-300">|</span>
            <button
              onClick={onDeselectAll}
              className="text-sm text-blue-600 hover:text-blue-800 underline"
            >
              Clear selection
            </button>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {actions.map((action, index) => {
            // Determine data-testid based on action label
            const labelLower = action.label.toLowerCase()
            let testId: string | undefined
            if (labelLower.includes('delete')) {
              testId = 'bulk-delete'
            } else if (labelLower === 'mark confirmed' || labelLower.includes('confirmed')) {
              testId = 'bulk-status-confirmed'
            } else if (labelLower.includes('status') || labelLower.includes('update status')) {
              testId = 'bulk-status-update'
            }

            return (
              <Button
                key={index}
                variant={action.variant || 'default'}
                size="sm"
                onClick={action.onClick}
                disabled={action.disabled}
                className="flex items-center gap-2"
                data-testid={testId}
              >
                {action.icon}
                {action.label}
              </Button>
            )
          })}
        </div>
      </div>
    </div>
  )
}

