'use client'

import { useState, useEffect, memo, useCallback, useMemo } from 'react'
import { motion } from 'framer-motion'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { DndProvider, useDrag, useDrop } from 'react-dnd'
import { HTML5Backend } from 'react-dnd-html5-backend'
import {
  Users,
  Bed,
  MapPin,
  Save,
  RotateCcw as RefreshIcon,
  AlertCircle,
  CheckCircle
} from 'lucide-react'
import { toast } from 'react-toastify'

interface Participant {
  id: string
  name: string
  email: string
  surfLevel: string
  bookingId: string
}

interface Room {
  id: string
  name: string
  capacity: number
  type: 'private' | 'dorm'
  currentOccupancy: number
  amenities: string[]
}

interface Assignment {
  roomId: string
  participantIds: string[]
}

interface AssignmentBoardProps {
  weekId: string
  onSave: (assignments: Assignment[]) => void
}

// Drag and drop item types
const ItemTypes = {
  PARTICIPANT: 'participant'
}

// Draggable participant component
interface DraggableParticipantProps {
  participant: Participant
}

const DraggableParticipant: React.FC<DraggableParticipantProps> = memo(({ participant }) => {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: ItemTypes.PARTICIPANT,
    item: { type: ItemTypes.PARTICIPANT, id: participant.id },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
    canDrag: () => true,
  }), [participant.id])

  return (
    <div
      ref={drag as unknown as React.Ref<HTMLDivElement>}
      className={`p-3 bg-white border rounded-lg cursor-move transition-all ${
        isDragging ? 'opacity-50 shadow-lg' : 'hover:shadow-md'
      }`}
      style={{
        opacity: isDragging ? 0.5 : 1,
      }}
    >
      <div className="flex items-center space-x-2">
        <Users className="w-4 h-4 text-gray-500" />
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium truncate">{participant.name}</p>
          <p className="text-xs text-gray-500 truncate">{participant.email}</p>
        </div>
        <Badge className="text-xs bg-orange-600 text-white hover:bg-orange-700">
          {participant.surfLevel}
        </Badge>
      </div>
    </div>
  )
}, (prevProps, nextProps) => {
  return prevProps.participant.id === nextProps.participant.id &&
         prevProps.participant.name === nextProps.participant.name &&
         prevProps.participant.email === nextProps.participant.email &&
         prevProps.participant.surfLevel === nextProps.participant.surfLevel
})

// Droppable room component
interface DroppableRoomProps {
  room: Room
  assignedParticipants: Participant[]
  onDrop: (participantId: string) => void
  onRemove: (participantId: string) => void
}

const DroppableRoom: React.FC<DroppableRoomProps> = memo(({
  room,
  assignedParticipants,
  onDrop,
  onRemove
}) => {
  const [{ isOver }, drop] = useDrop(() => ({
    accept: ItemTypes.PARTICIPANT,
    drop: (item: { id: string }) => onDrop(item.id),
    collect: (monitor) => ({
      isOver: monitor.isOver(),
    }),
    canDrop: () => true,
  }), [onDrop])

  const occupancyRate = (assignedParticipants.length / room.capacity) * 100
  const isFull = assignedParticipants.length >= room.capacity
  const isOverCapacity = assignedParticipants.length > room.capacity

  return (
    <motion.div
      ref={drop as unknown as React.Ref<HTMLDivElement>}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className={`border-2 border-dashed rounded-lg p-4 min-h-[200px] transition-all ${
        isOver
          ? 'border-orange-400 bg-orange-50'
          : isFull
            ? 'border-red-300 bg-red-50'
            : 'border-gray-300 hover:border-gray-400 hover:bg-gray-50'
      }`}
    >
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center space-x-2">
          <MapPin className="w-5 h-5 text-gray-600" />
          <h3 className="font-medium">{room.name}</h3>
          <Badge className="bg-orange-600 text-white hover:bg-orange-700">
            {room.type}
          </Badge>
        </div>
        <div className="flex items-center space-x-2">
          <Users className="w-4 h-4 text-gray-500" />
          <span className="text-sm text-gray-600">
            {assignedParticipants.length}/{room.capacity}
          </span>
        </div>
      </div>

      {/* Occupancy bar */}
      <div className="mb-3">
        <div className="flex justify-between text-xs text-gray-500 mb-1">
          <span>Occupancy</span>
          <span>{Math.round(occupancyRate)}%</span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div
            className={`h-2 rounded-full transition-all duration-300 ${
              isOverCapacity ? 'bg-red-500' : 'bg-green-500'
            }`}
            style={{ width: `${Math.min(occupancyRate, 100)}%` }}
          />
        </div>
      </div>

      {/* Assigned participants */}
      <div className="space-y-2">
        {assignedParticipants.length === 0 ? (
          <p className="text-sm text-gray-500 text-center py-4">
            Drop participants here
          </p>
        ) : (
          assignedParticipants.map((participant) => (
            <div
              key={participant.id}
              className="flex items-center justify-between p-2 bg-gray-50 rounded"
            >
              <div className="flex items-center space-x-2">
                <Users className="w-4 h-4 text-gray-500" />
                <div>
                  <p className="text-sm font-medium">{participant.name}</p>
                  <p className="text-xs text-gray-500">{participant.surfLevel}</p>
                </div>
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onRemove(participant.id)}
                className="text-red-600 hover:text-red-700"
              >
                ×
              </Button>
            </div>
          ))
        )}
      </div>

      {isOverCapacity && (
        <div className="mt-2 flex items-center space-x-1 text-red-600 text-xs">
          <AlertCircle className="w-3 h-3" />
          <span>Over capacity!</span>
        </div>
      )}
    </motion.div>
  )
}, (prevProps, nextProps) => {
  return prevProps.room.id === nextProps.room.id &&
         prevProps.assignedParticipants.length === nextProps.assignedParticipants.length &&
         prevProps.assignedParticipants.every((p, i) => p.id === nextProps.assignedParticipants[i]?.id) &&
         prevProps.onDrop === nextProps.onDrop &&
         prevProps.onRemove === nextProps.onRemove
})

export default function AssignmentBoard({ weekId, onSave }: AssignmentBoardProps) {
  const [participants, setParticipants] = useState<Participant[]>([])
  const [rooms, setRooms] = useState<Room[]>([])
  const [assignments, setAssignments] = useState<Assignment[]>([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)

  // Fetch real data from API
  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true)

        // Fetch participants for the selected week
        const participantsResponse = await fetch(`/api/assignments/participants?weekId=${weekId}`)
        if (!participantsResponse.ok) {
          throw new Error('Failed to fetch participants')
        }
        const participantsData = await participantsResponse.json()

        // Fetch rooms
        const roomsResponse = await fetch('/api/assignments/rooms')
        if (!roomsResponse.ok) {
          throw new Error('Failed to fetch rooms')
        }
        const roomsData = await roomsResponse.json()

        // Transform rooms
        const transformedRooms: Room[] = Array.isArray(roomsData) ? roomsData.map((room) => ({
          id: (room as { id: string }).id,
          name: (room as { name: string }).name,
          capacity: (room as { capacity: number }).capacity,
          type: ((room as { type?: string }).type || 'private') as 'private' | 'dorm',
          currentOccupancy: 0,
          amenities: (room as { amenities?: string[] }).amenities || []
        })) : []

        // Fetch existing assignments
        const assignmentsResponse = await fetch(`/api/assignments?weekId=${weekId}`)
        const assignmentsData = assignmentsResponse.ok ? await assignmentsResponse.json() : []

        setParticipants(participantsData || [])
        setRooms(transformedRooms)
        setAssignments(assignmentsData || [])
        setLoading(false)
      } catch (error) {
        console.error('Error fetching assignment data:', error)
        toast.error('Failed to load assignment data')
        setParticipants([])
        setRooms([])
        setAssignments([])
        setLoading(false)
      }
    }

    if (weekId) {
      fetchData()
    }
  }, [weekId])

  const handleParticipantDrop = useCallback((roomId: string, participantId: string) => {
    // Find the room to check capacity
    const room = rooms.find(r => r.id === roomId)
    if (!room) return

    setAssignments(prev => {
      const existing = prev.find(a => a.roomId === roomId)
      const currentCount = existing?.participantIds.length || 0

      // Check if already assigned to this room
      if (existing?.participantIds.includes(participantId)) {
        return prev
      }

      // Prevent overbooking - check capacity before allowing drop
      if (currentCount >= room.capacity) {
        toast.error(`${room.name} is at full capacity (${room.capacity} beds)`)
        return prev
      }

      if (existing) {
        const updated = prev.map(a =>
          a.roomId === roomId
            ? { ...a, participantIds: [...a.participantIds, participantId] }
            : { ...a, participantIds: a.participantIds.filter(id => id !== participantId) }
        )
        return updated
      } else {
        const newAssignment: Assignment = {
          roomId,
          participantIds: [participantId]
        }
        return [...prev.filter(a => a.participantIds.length > 0), newAssignment]
      }
    })
  }, [rooms])

  const handleParticipantRemove = useCallback((roomId: string, participantId: string) => {
    setAssignments(prev =>
      prev.map(a =>
        a.roomId === roomId
          ? { ...a, participantIds: a.participantIds.filter(id => id !== participantId) }
          : a
      ).filter(a => a.participantIds.length > 0)
    )
  }, [])

  const getAssignedParticipants = useCallback((roomId: string) => {
    const assignment = assignments.find(a => a.roomId === roomId)
    if (!assignment) return []
    return assignment.participantIds.map(id =>
      participants.find(p => p.id === id)
    ).filter(Boolean) as Participant[]
  }, [assignments, participants])

  const unassignedParticipants = useMemo(() => {
    const assignedIds = assignments.flatMap(a => a.participantIds)
    return participants.filter(p => !assignedIds.includes(p.id))
  }, [assignments, participants])

  const dropHandlers = useMemo(() => {
    const handlers = new Map<string, (participantId: string) => void>()
    rooms.forEach(room => {
      handlers.set(room.id, (participantId: string) => handleParticipantDrop(room.id, participantId))
    })
    return handlers
  }, [rooms, handleParticipantDrop])

  const removeHandlers = useMemo(() => {
    const handlers = new Map<string, (participantId: string) => void>()
    rooms.forEach(room => {
      handlers.set(room.id, (participantId: string) => handleParticipantRemove(room.id, participantId))
    })
    return handlers
  }, [rooms, handleParticipantRemove])

  const handleSave = async () => {
    setSaving(true)
    try {
      const response = await fetch('/api/assignments', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          weekId,
          assignments
        })
      })

      if (!response.ok) {
        const errorText = await response.text()
        let errorMessage = `HTTP ${response.status}: ${response.statusText}`
        try {
          const errorJson = JSON.parse(errorText)
          errorMessage = errorJson.error || errorJson.message || errorMessage
        } catch {
          errorMessage = errorText || errorMessage
        }
        throw new Error(`Failed to save assignments: ${errorMessage}`)
      }

      const result = await response.json()

      if (!result.success) {
        throw new Error(result.error || result.message || 'Failed to save assignments')
      }

      // Verify the save persisted - API returns { success: true, message: "Saved X assignments" }
      // The message includes the count, so if it exists, we know assignments were saved
      if (!result.message || !result.message.includes('Saved')) {
        console.warn('Assignment save response missing expected message format:', result)
        // Don't throw error - success flag is the primary indicator
      }

      toast.success(result.message || 'Assignments saved successfully!')
      onSave(assignments)

      // Optionally refresh assignments from server to verify persistence
      // This could be done by calling a refresh callback if provided
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to save assignments'
      console.error('Error saving assignments:', error)
      toast.error(errorMessage)
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-600"></div>
      </div>
    )
  }

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Room Assignments</h2>
            <p className="text-gray-600">Drag participants to assign them to rooms</p>
          </div>
          <div className="flex items-center space-x-2">
            <Button variant="outline" onClick={() => window.location.reload()}>
              <RefreshIcon className="w-4 h-4 mr-2" />
              Refresh
            </Button>
            <Button onClick={handleSave} disabled={saving}>
              {saving ? (
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
              ) : (
                <Save className="w-4 h-4 mr-2" />
              )}
              Save Assignments
            </Button>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center space-x-2">
                <Users className="w-5 h-5 text-orange-600" />
                <div>
                  <p className="text-2xl font-bold">{participants.length}</p>
                  <p className="text-sm text-gray-600">Total Participants</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center space-x-2">
                <Bed className="w-5 h-5 text-green-600" />
                <div>
                  <p className="text-2xl font-bold">{assignments.length}</p>
                  <p className="text-sm text-gray-600">Rooms Assigned</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center space-x-2">
                <CheckCircle className="w-5 h-5 text-orange-600" />
                <div>
                  <p className="text-2xl font-bold">{unassignedParticipants.length}</p>
                  <p className="text-sm text-gray-600">Unassigned</p>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Assignment Interface */}
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Unassigned Participants */}
          <div className="lg:col-span-1">
            <Card>
              <CardHeader>
                <CardTitle className="text-lg">Unassigned Participants</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {unassignedParticipants.map((participant) => (
                    <DraggableParticipant
                      key={`unassigned-${participant.id}`}
                      participant={participant}
                    />
                  ))}
                  {unassignedParticipants.length === 0 && (
                    <p className="text-sm text-gray-500 text-center py-4">
                      All participants assigned!
                    </p>
                  )}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Rooms */}
          <div className="lg:col-span-3">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {rooms.map((room) => (
                <DroppableRoom
                  key={room.id}
                  room={room}
                  assignedParticipants={getAssignedParticipants(room.id)}
                  onDrop={dropHandlers.get(room.id)!}
                  onRemove={removeHandlers.get(room.id)!}
                />
              ))}
            </div>
          </div>
        </div>
      </div>
    </DndProvider>
  )
}

'use client'

import { useState, useRef } from 'react'
import { Upload, X, Image as ImageIcon } from 'lucide-react'
import Image from 'next/image'

interface CoverImageUploadProps {
  value?: string
  onChange: (url: string) => void
  altText?: string
  onAltTextChange?: (alt: string) => void
}

export function CoverImageUpload({ value, onChange, altText, onAltTextChange }: CoverImageUploadProps) {
  const [uploading, setUploading] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = async (file: File) => {
    if (!file.type.startsWith('image/')) {
      alert('File must be an image')
      return
    }

    const maxSize = 5 * 1024 * 1024 // 5MB
    if (file.size > maxSize) {
      alert('File size must be less than 5MB')
      return
    }

    setUploading(true)
    const formData = new FormData()
    formData.append('file', file)
    formData.append('bucket', 'blog-images')
    formData.append('path', 'covers')

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData
      })

      const data = await response.json()

      if (data.success) {
        onChange(data.data.url)
        if (!altText && onAltTextChange) {
          onAltTextChange(file.name.replace(/\.[^/.]+$/, ''))
        }
      } else {
        alert(data.error || 'Failed to upload image')
      }
    } catch (error) {
      alert('Error uploading image')
      console.error(error)
    } finally {
      setUploading(false)
      if (fileInputRef.current) {
        fileInputRef.current.value = ''
      }
    }
  }

  return (
    <div className="space-y-4">
      {value ? (
        <div className="relative group">
          <div className="relative h-64 w-full rounded-lg overflow-hidden border border-gray-300">
            <Image
              src={value}
              alt={altText || 'Cover image'}
              fill
              className="object-cover"
            />
          </div>
          <button
            type="button"
            onClick={() => onChange('')}
            className="absolute top-2 right-2 bg-red-600 text-white rounded-full p-2 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-700"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      ) : (
        <div
          onClick={() => fileInputRef.current?.click()}
          className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center cursor-pointer hover:border-gray-400 transition-colors"
        >
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            onChange={(e) => {
              const file = e.target.files?.[0]
              if (file) handleFileSelect(file)
            }}
            className="hidden"
          />
          <Upload className="h-12 w-12 text-gray-400 mx-auto mb-4" />
          <p className="text-sm text-gray-600">Click to upload cover image</p>
          <p className="text-xs text-gray-500 mt-1">Max 5MB</p>
        </div>
      )}

      {value && onAltTextChange && (
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Alt Text
          </label>
          <input
            type="text"
            value={altText || ''}
            onChange={(e) => onAltTextChange(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
            placeholder="Describe the image for accessibility"
          />
        </div>
      )}
    </div>
  )
}

'use client'

import { X } from 'lucide-react'

interface Participant {
  name?: string
  firstName?: string
  lastName?: string
  email?: string
  phone?: string
  dietaryRequirements?: string
  specialRequests?: string
}

interface Booking {
  id: string
  guest_name: string
  guest_email: string
  guest_phone: string
  type: 'room' | 'surf_camp'
  item_name: string
  check_in: string
  check_out: string
  guests: number
  total_price: number
  status: 'pending' | 'confirmed' | 'cancelled' | 'completed'
  payment_status: 'pending' | 'paid' | 'refunded'
  created_at: string
  special_requests?: string
  dietary_preferences?: string
  client_notes?: string
  notes?: string
  participants?: Participant[]
  room_assignments?: Array<{
    roomId: string
    roomName: string
    roomType: string
    maxOccupancy: number
    clientId: string
    clientName: string
    enrollmentId: string
  }>
}

interface ViewBookingModalProps {
  isOpen: boolean
  booking: Booking | null
  onClose: () => void
  onEdit?: (booking: Booking) => void
  onDelete?: (bookingId: string) => void
  onSendEmail?: (booking: Booking) => void
}

export function ViewBookingModal({
  isOpen,
  booking,
  onClose,
  onEdit,
  onDelete,
  onSendEmail,
}: ViewBookingModalProps) {
  if (!isOpen || !booking) return null

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'confirmed':
        return 'bg-green-100 text-green-800'
      case 'cancelled':
        return 'bg-red-100 text-red-800'
      case 'completed':
        return 'bg-blue-100 text-blue-800'
      default:
        return 'bg-yellow-100 text-yellow-800'
    }
  }

  const getPaymentStatusColor = (status: string) => {
    switch (status) {
      case 'paid':
        return 'bg-green-100 text-green-800'
      case 'refunded':
        return 'bg-red-100 text-red-800'
      default:
        return 'bg-yellow-100 text-yellow-800'
    }
  }

  const formatDate = (dateString: string) => {
    try {
      return new Date(dateString).toLocaleDateString('en-GB', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
      })
    } catch {
      return dateString
    }
  }

  const formatDateTime = (dateString: string) => {
    try {
      return new Date(dateString).toLocaleDateString('en-GB', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      })
    } catch {
      return dateString
    }
  }

  // Get participants - FIRST check API-provided data, THEN parse from notes
  const getParticipants = (): Participant[] => {
    // Priority 1: Use participants array from API response (already parsed by GET endpoint)
    if (booking.participants && Array.isArray(booking.participants) && booking.participants.length > 0) {
      console.log('Using API-provided participants:', booking.participants)
      return booking.participants
    }

    // Priority 2: Parse from notes if no participants array provided
    if (!booking.notes) return []

    try {
      // Try to parse notes as JSON
      const notesData = JSON.parse(booking.notes)
      if (notesData && notesData.participants && Array.isArray(notesData.participants)) {
        console.log('Parsed participants from JSON notes:', notesData.participants)
        return notesData.participants
      }
    } catch {
      // Not JSON, try to parse from text format
      console.log('Parsing participants from text notes')
      const participants: Participant[] = []

      // Split by "Guest X:" pattern to find each guest section
      // Handle both "Guest 1: Name" and "\n\nGuest 1: Name" patterns
      const guestPattern = /(?:^|\n)Guest (\d+):\s*([^\n]+)/g
      let match
      const guestData: Map<number, Participant> = new Map()

      // First pass: extract guest names
      const notes = booking.notes
      while ((match = guestPattern.exec(notes)) !== null) {
        const guestNum = parseInt(match[1])
        const guestName = match[2].trim()
        if (!guestData.has(guestNum)) {
          guestData.set(guestNum, {
            name: guestName,
            firstName: guestName.split(' ')[0],
            lastName: guestName.split(' ').slice(1).join(' ')
          })
        }
      }

      // Second pass: extract details for each guest
      // Split notes into sections by double newline or by "Guest X:" markers
      const lines = notes.split('\n')
      let currentGuest = 0

      for (const line of lines) {
        const guestMatch = line.match(/^Guest (\d+):\s*(.+)/)
        if (guestMatch) {
          currentGuest = parseInt(guestMatch[1])
          const name = guestMatch[2].trim()
          if (!guestData.has(currentGuest)) {
            guestData.set(currentGuest, {
              name: name,
              firstName: name.split(' ')[0],
              lastName: name.split(' ').slice(1).join(' ')
            })
          }
        } else if (currentGuest > 0 && guestData.has(currentGuest)) {
          const participant = guestData.get(currentGuest)!

          if (line.startsWith('Email:')) {
            participant.email = line.replace(/Email:\s*/i, '').trim()
          } else if (line.startsWith('Phone:')) {
            participant.phone = line.replace(/Phone:\s*/i, '').trim()
          } else if (line.startsWith('Dietary Requirements:')) {
            participant.dietaryRequirements = line.replace(/Dietary Requirements:\s*/i, '').trim()
          } else if (line.startsWith('Special Requests:')) {
            participant.specialRequests = line.replace(/Special Requests:\s*/i, '').trim()
          }
        }
      }

      // Convert map to array, sorted by guest number
      const sortedGuests = Array.from(guestData.entries())
        .sort((a, b) => a[0] - b[0])
        .map(([_, p]) => p)

      if (sortedGuests.length > 0) {
        console.log('Parsed participants from text:', sortedGuests)
        return sortedGuests
      }
    }

    return []
  }

  const participants = getParticipants()
  const hasMultipleParticipants = participants.length > 1 || (participants.length === 0 && booking.guests > 1)

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto" data-testid="view-booking-modal">
        {/* Header */}
        <div className="sticky top-0 px-6 py-4 border-b border-gray-200 flex justify-between items-center bg-white">
          <h3 className="text-lg font-semibold text-gray-900">Booking Details</h3>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 transition-colors"
            aria-label="Close modal"
          >
            <X className="h-6 w-6" />
          </button>
        </div>

        {/* Content */}
        <div className="px-6 py-4 space-y-6">
          {/* Booking ID and Status */}
          <div className="flex justify-between items-start" data-testid="booking-id-display">
            <div>
              <p className="text-sm text-gray-500">Booking ID</p>
              <p className="text-lg font-semibold text-gray-900">{booking.id}</p>
            </div>
            <div className="flex gap-2" data-testid="payment-status-display">
              <span className={`inline-flex px-3 py-1 text-xs font-semibold rounded-full ${getStatusColor(booking.status)}`} data-testid={`status-${booking.status}`}>
                {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
              </span>
              <span className={`inline-flex px-3 py-1 text-xs font-semibold rounded-full ${getPaymentStatusColor(booking.payment_status)}`}>
                {booking.payment_status.charAt(0).toUpperCase() + booking.payment_status.slice(1)}
              </span>
            </div>
          </div>

          {/* Guest Information */}
          <div className="border-t pt-4" data-testid="guest-details-display">
            <h4 className="font-medium text-gray-900 mb-3">
              {hasMultipleParticipants ? `Participants (${participants.length || booking.guests})` : 'Guest Information'}
            </h4>

            {hasMultipleParticipants && participants.length > 0 ? (
              <div className="space-y-4">
                {participants.map((participant, index) => (
                  <div key={index} className="bg-gray-50 rounded-lg p-4 border border-gray-200">
                    <h5 className="font-semibold text-gray-900 mb-3">Guest {index + 1}</h5>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      <div>
                        <p className="text-xs text-gray-500">Name</p>
                        <p className="text-sm font-medium text-gray-900">
                          {participant.name || `${participant.firstName || ''} ${participant.lastName || ''}`.trim() || 'Not provided'}
                        </p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-500">Email</p>
                        <p className="text-sm font-medium text-gray-900">{participant.email || 'Not provided'}</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-500">Phone</p>
                        <p className="text-sm font-medium text-gray-900">{participant.phone || 'Not provided'}</p>
                      </div>
                      {participant.dietaryRequirements && (
                        <div>
                          <p className="text-xs text-gray-500">Dietary Requirements</p>
                          <p className="text-sm text-gray-700">{participant.dietaryRequirements}</p>
                        </div>
                      )}
                      {participant.specialRequests && (
                        <div className="md:col-span-2">
                          <p className="text-xs text-gray-500">Special Requests</p>
                          <p className="text-sm text-gray-700 whitespace-pre-wrap">{participant.specialRequests}</p>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-gray-500">Name</p>
                  <p className="text-sm font-medium text-gray-900">{booking.guest_name}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-500">Email</p>
                  <p className="text-sm font-medium text-gray-900">{booking.guest_email}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-500">Phone</p>
                  <p className="text-sm font-medium text-gray-900">{booking.guest_phone}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-500">Number of Guests</p>
                  <p className="text-sm font-medium text-gray-900">{booking.guests}</p>
                </div>
              </div>
            )}
          </div>

          {/* Room Assignments - Only for surf camp bookings */}
          {booking.type === 'surf_camp' && booking.room_assignments && booking.room_assignments.length > 0 && (
            <div className="border-t pt-4">
              <h4 className="font-medium text-gray-900 mb-3">Room Assignments</h4>
              <div className="space-y-3">
                {booking.room_assignments.map((assignment, index) => (
                  <div key={index} className="bg-blue-50 rounded-lg p-3 border border-blue-200">
                    <div className="flex justify-between items-start">
                      <div>
                        <p className="text-sm font-semibold text-gray-900">{assignment.clientName}</p>
                        <p className="text-xs text-gray-600">Room: {assignment.roomName}</p>
                        <p className="text-xs text-gray-500 capitalize">{assignment.roomType} • Max {assignment.maxOccupancy} guests</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Booking Details */}
          <div className="border-t pt-4" data-testid="booking-details-display">
            <h4 className="font-medium text-gray-900 mb-3">Booking Details</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-gray-500">Type</p>
                <p className="text-sm font-medium text-gray-900">
                  {booking.type === 'room' ? 'Room' : 'Surf Camp'}
                </p>
              </div>
              <div>
                <p className="text-sm text-gray-500">Item</p>
                <p className="text-sm font-medium text-gray-900">{booking.item_name}</p>
              </div>
              <div>
                <p className="text-sm text-gray-500">Check-in</p>
                <p className="text-sm font-medium text-gray-900">{formatDate(booking.check_in)}</p>
              </div>
              <div>
                <p className="text-sm text-gray-500">Check-out</p>
                <p className="text-sm font-medium text-gray-900">{formatDate(booking.check_out)}</p>
              </div>
            </div>
          </div>

          {/* Pricing */}
          <div className="border-t pt-4">
            <h4 className="font-medium text-gray-900 mb-3">Pricing</h4>
            <div className="bg-gray-50 rounded-lg p-4">
              <div className="flex justify-between items-center">
                <span className="text-gray-600">Total Amount</span>
                <span className="text-2xl font-bold text-gray-900">€{booking.total_price.toFixed(2)}</span>
              </div>
            </div>
          </div>

          {/* Dietary Preferences - Only show if not already displayed per participant */}
          {booking.dietary_preferences && !hasMultipleParticipants && (
            <div className="border-t pt-4">
              <h4 className="font-medium text-gray-900 mb-3">Dietary Preferences</h4>
              <p className="text-sm text-gray-600 bg-gray-50 rounded-lg p-3">
                {booking.dietary_preferences}
              </p>
            </div>
          )}

          {/* Special Requests - Only show if not already displayed per participant */}
          {booking.special_requests && !hasMultipleParticipants && (
            <div className="border-t pt-4">
              <h4 className="font-medium text-gray-900 mb-3">Special Requests</h4>
              <p className="text-sm text-gray-600 bg-gray-50 rounded-lg p-3 whitespace-pre-wrap">
                {booking.special_requests}
              </p>
            </div>
          )}

          {/* Client Notes */}
          {booking.client_notes && (
            <div className="border-t pt-4">
              <h4 className="font-medium text-gray-900 mb-3">Client Notes</h4>
              <p className="text-sm text-gray-600 bg-gray-50 rounded-lg p-3 whitespace-pre-wrap">
                {booking.client_notes}
              </p>
            </div>
          )}

          {/* Internal Notes - Extract from JSON notes if present */}
          {(() => {
            try {
              if (booking.notes && booking.notes.trim().startsWith('{')) {
                const notesData = JSON.parse(booking.notes)
                if (notesData.internal_notes) {
                  return (
                    <div className="border-t pt-4">
                      <h4 className="font-medium text-gray-900 mb-3">Internal Notes</h4>
                      <p className="text-sm text-gray-600 bg-yellow-50 rounded-lg p-3 whitespace-pre-wrap border border-yellow-200">
                        {notesData.internal_notes}
                      </p>
                    </div>
                  )
                }
              }
              return null
            } catch {
              return null
            }
          })()}

          {/* Raw Notes - Only show for non-JSON notes that aren't special requests */}
          {booking.notes && 
           booking.notes !== booking.special_requests && 
           participants.length === 0 &&
           !booking.notes.trim().startsWith('{') &&
           !booking.notes.includes('[Internal Notes]:') && (
            <div className="border-t pt-4">
              <h4 className="font-medium text-gray-900 mb-3">Additional Notes</h4>
              <p className="text-sm text-gray-600 bg-gray-50 rounded-lg p-3 whitespace-pre-wrap">
                {booking.notes}
              </p>
            </div>
          )}

          {/* Internal Notes from text format */}
          {booking.notes && 
           booking.notes.includes('[Internal Notes]:') && (
            <div className="border-t pt-4">
              <h4 className="font-medium text-gray-900 mb-3">Internal Notes</h4>
              <p className="text-sm text-gray-600 bg-yellow-50 rounded-lg p-3 whitespace-pre-wrap border border-yellow-200">
                {booking.notes.split('[Internal Notes]:')[1]?.trim() || ''}
              </p>
            </div>
          )}

          {/* Created Date */}
          <div className="border-t pt-4">
            <p className="text-xs text-gray-500">
              Created on {formatDateTime(booking.created_at)}
            </p>
          </div>

          {/* Action Buttons */}
          <div className="border-t pt-4 flex justify-between">
            <div className="flex gap-2">
              {onEdit && (
                <button
                  onClick={() => onEdit(booking)}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                  data-testid="edit-booking-btn"
                >
                  Edit
                </button>
              )}
              {onSendEmail && (
                <button
                  onClick={() => onSendEmail(booking)}
                  className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
                  data-testid="send-email-btn"
                >
                  Send Email
                </button>
              )}
              {onDelete && (
                <button
                  onClick={() => onDelete(booking.id)}
                  className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                  data-testid="delete-booking-btn"
                >
                  Delete
                </button>
              )}
            </div>
            <button
              onClick={onClose}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

