'use client'

import { useState } from 'react'
import { CalendarEvent, getEventTypeConfig } from './calendar-constants'
import { Input } from '@/components/ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Button } from '@/components/ui/button'
import { Check, X, ExternalLink } from 'lucide-react'
import { toast } from 'react-toastify'
import { cn } from '@/lib/utils'

interface EventCardProps {
  event: CalendarEvent
  onUpdate: (event: CalendarEvent) => void
  onViewFull: (event: CalendarEvent) => void
}

// Helper to determine if a color is a valid hex color
const isHexColor = (color?: string): boolean => {
  if (!color) return false
  return /^#([0-9A-Fa-f]{3}){1,2}$/.test(color)
}

// Helper to create a lighter shade of a hex color for background
const getLighterShade = (hexColor: string, opacity: number = 0.15): string => {
  const hex = hexColor.replace('#', '')
  const r = parseInt(hex.substring(0, 2), 16)
  const g = parseInt(hex.substring(2, 4), 16)
  const b = parseInt(hex.substring(4, 6), 16)
  return `rgba(${r}, ${g}, ${b}, ${opacity})`
}

export function EventCard({ event, onUpdate, onViewFull }: EventCardProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editedTitle, setEditedTitle] = useState(event.title)
  const [editedStatus, setEditedStatus] = useState(event.status || 'confirmed')
  const [saving, setSaving] = useState(false)

  const config = getEventTypeConfig(event.event_type)
  const Icon = config.icon

  // Use custom color from event if it's a valid hex, otherwise use config color
  const hasCustomColor = isHexColor(event.color)
  const effectiveColor = hasCustomColor ? event.color! : config.color

  const displayTitle = event.guest_name
    ? `${event.guest_name}${event.room_name ? ` - ${event.room_name}` : ''}`
    : event.title

  const handleSave = async () => {
    setSaving(true)
    try {
      const response = await fetch(`/api/calendar-events/${event.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: editedTitle,
          status: editedStatus,
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to update event')
      }

      const data = await response.json()
      onUpdate({ ...event, title: editedTitle, status: editedStatus as CalendarEvent['status'] })
      toast.success('Event updated')
      setIsEditing(false)
    } catch (error) {
      toast.error('Failed to update event')
    } finally {
      setSaving(false)
    }
  }

  const handleCancel = () => {
    setEditedTitle(event.title)
    setEditedStatus(event.status || 'confirmed')
    setIsEditing(false)
  }

  const handleQuickStatusChange = async (newStatus: string) => {
    setSaving(true)
    try {
      const response = await fetch(`/api/calendar-events/${event.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })

      if (!response.ok) {
        throw new Error('Failed to update status')
      }

      onUpdate({ ...event, status: newStatus as CalendarEvent['status'] })
      toast.success('Status updated')
    } catch (error) {
      toast.error('Failed to update status')
    } finally {
      setSaving(false)
    }
  }

  const formatTime = (dateStr: string) => {
    const date = new Date(dateStr)
    return date.toLocaleTimeString('en-GB', { hour: 'numeric', minute: '2-digit' })
  }

  const formatDateRange = () => {
    const start = new Date(event.start_date)
    const end = new Date(event.end_date || event.start_date)
    const startStr = start.toLocaleDateString('en-GB', { month: 'short', day: 'numeric' })
    const endStr = end.toLocaleDateString('en-GB', { month: 'short', day: 'numeric' })

    if (startStr === endStr) {
      return startStr
    }
    return `${startStr} - ${endStr}`
  }

  return (
    <div
      className={cn(
        'rounded-lg border p-3 transition-all',
        !hasCustomColor && config.bgColor,
        !hasCustomColor && config.borderColor,
        event.status === 'cancelled' && 'opacity-60'
      )}
      style={hasCustomColor ? {
        backgroundColor: getLighterShade(effectiveColor),
        borderColor: effectiveColor,
      } : undefined}
    >
      {/* Header with type label */}
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5">
          <Icon className="h-4 w-4" style={{ color: effectiveColor }} />
          <span className="text-xs font-medium uppercase tracking-wide" style={{ color: effectiveColor }}>
            {config.label}{event.blocks_bookings ? ' (Blocks Bookings)' : ''}
          </span>
        </div>
        <button
          onClick={() => onViewFull(event)}
          className="text-gray-500 hover:text-gray-700 p-1"
          title="View full details"
        >
          <ExternalLink className="h-4 w-4" />
        </button>
      </div>

      {/* Title - editable */}
      {isEditing ? (
        <div className="space-y-2">
          <Input
            value={editedTitle}
            onChange={(e) => setEditedTitle(e.target.value)}
            className="text-sm font-medium bg-white"
            autoFocus
          />
          <Select value={editedStatus} onValueChange={(v) => setEditedStatus(v as 'confirmed' | 'pending' | 'cancelled')}>
            <SelectTrigger className="bg-white text-sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="confirmed">Confirmed</SelectItem>
              <SelectItem value="pending">Pending</SelectItem>
              <SelectItem value="cancelled">Cancelled</SelectItem>
            </SelectContent>
          </Select>
          <div className="flex gap-2">
            <Button size="sm" onClick={handleSave} disabled={saving} className="flex-1">
              <Check className="h-4 w-4 mr-1" />
              Save
            </Button>
            <Button size="sm" variant="outline" onClick={handleCancel} disabled={saving}>
              <X className="h-4 w-4" />
            </Button>
          </div>
        </div>
      ) : (
        <div
          onClick={() => setIsEditing(true)}
          className="cursor-pointer hover:bg-white/50 rounded p-1 -m-1 transition-colors"
        >
          <p
            className={cn(
              'font-medium text-gray-900',
              event.status === 'cancelled' && 'line-through'
            )}
          >
            {displayTitle}
          </p>
        </div>
      )}

      {/* Details */}
      {!isEditing && (
        <div className="mt-2 space-y-1 text-sm text-gray-600">
          <p>{formatDateRange()}</p>
          {event.participant_count && (
            <p>{event.participant_count} participants</p>
          )}
          {event.location && <p>{event.location}</p>}

          {/* Status indicator with quick change */}
          <div className="flex items-center gap-2 mt-2">
            <span className="text-xs text-gray-500">Status:</span>
            <Select
              value={event.status || 'confirmed'}
              onValueChange={handleQuickStatusChange}
              disabled={saving}
            >
              <SelectTrigger className="h-7 w-auto text-xs bg-white/80 border-0 shadow-sm">
                <div className="flex items-center gap-1.5">
                  <span
                    className={cn(
                      'w-2 h-2 rounded-full',
                      event.status === 'confirmed' && 'bg-green-500',
                      event.status === 'pending' && 'bg-yellow-500',
                      event.status === 'cancelled' && 'bg-gray-400',
                      !event.status && 'bg-green-500'
                    )}
                  />
                  <SelectValue />
                </div>
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="confirmed">Confirmed</SelectItem>
                <SelectItem value="pending">Pending</SelectItem>
                <SelectItem value="cancelled">Cancelled</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useMemo, useState, useRef } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { CalendarEvent, isDateInRange } from './calendar-constants'
import { GanttEventBar } from './GanttEventBar'
import { EventPopover } from './EventPopover'
import { cn } from '@/lib/utils'

type ViewType = 'quarter' | 'year'

interface GanttTimelineProps {
  viewType: ViewType
  currentDate: Date
  events: CalendarEvent[]
  onDateChange: (date: Date) => void
  onEventViewDetails: (event: CalendarEvent) => void
}

const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
]

const MONTH_ABBREV = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'
]

function getDaysInMonth(year: number, month: number): number {
  return new Date(year, month + 1, 0).getDate()
}

function getQuarterMonths(date: Date): { year: number; month: number }[] {
  const quarter = Math.floor(date.getMonth() / 3)
  const year = date.getFullYear()
  return [
    { year, month: quarter * 3 },
    { year, month: quarter * 3 + 1 },
    { year, month: quarter * 3 + 2 },
  ]
}

function getYearMonths(date: Date): { year: number; month: number }[] {
  const year = date.getFullYear()
  return Array.from({ length: 12 }, (_, i) => ({ year, month: i }))
}

interface MonthRow {
  year: number
  month: number
  daysInMonth: number
  events: { event: CalendarEvent; startDay: number; endDay: number }[]
}

export function GanttTimeline({
  viewType,
  currentDate,
  events,
  onDateChange,
  onEventViewDetails,
}: GanttTimelineProps) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const [popoverEvent, setPopoverEvent] = useState<CalendarEvent | null>(null)
  const [popoverAnchor, setPopoverAnchor] = useState<HTMLElement | null>(null)

  const today = useMemo(() => new Date(), [])

  const months = useMemo(() => {
    return viewType === 'quarter' ? getQuarterMonths(currentDate) : getYearMonths(currentDate)
  }, [viewType, currentDate])

  const monthRows: MonthRow[] = useMemo(() => {
    return months.map(({ year, month }) => {
      const daysInMonth = getDaysInMonth(year, month)
      const monthStart = new Date(year, month, 1)
      const monthEnd = new Date(year, month, daysInMonth)

      // Find events that overlap with this month
      const monthEvents = events
        .map((event) => {
          const eventStart = new Date(event.start_date)
          const eventEnd = new Date(event.end_date || event.start_date)

          // Check if event overlaps with this month
          if (eventEnd < monthStart || eventStart > monthEnd) {
            return null
          }

          // Calculate start and end days within this month
          const startDay = eventStart < monthStart ? 1 : eventStart.getDate()
          const endDay = eventEnd > monthEnd ? daysInMonth : eventEnd.getDate()

          return { event, startDay, endDay }
        })
        .filter((e): e is NonNullable<typeof e> => e !== null)

      return { year, month, daysInMonth, events: monthEvents }
    })
  }, [months, events])

  // Calculate max events in any row to set row height
  const maxEventsInRow = useMemo(() => {
    return Math.max(1, ...monthRows.map((r) => r.events.length))
  }, [monthRows])

  const handlePrev = () => {
    if (viewType === 'quarter') {
      onDateChange(new Date(currentDate.getFullYear(), currentDate.getMonth() - 3, 1))
    } else {
      onDateChange(new Date(currentDate.getFullYear() - 1, 0, 1))
    }
  }

  const handleNext = () => {
    if (viewType === 'quarter') {
      onDateChange(new Date(currentDate.getFullYear(), currentDate.getMonth() + 3, 1))
    } else {
      onDateChange(new Date(currentDate.getFullYear() + 1, 0, 1))
    }
  }

  const getHeaderTitle = () => {
    if (viewType === 'year') {
      return currentDate.getFullYear().toString()
    }
    const quarter = Math.floor(currentDate.getMonth() / 3) + 1
    return `Q${quarter} ${currentDate.getFullYear()}`
  }

  const handleEventClick = (event: CalendarEvent, anchorEl: HTMLElement) => {
    setPopoverEvent(event)
    setPopoverAnchor(anchorEl)
  }

  const handleClosePopover = () => {
    setPopoverEvent(null)
    setPopoverAnchor(null)
  }

  const handleViewDetails = (event: CalendarEvent) => {
    handleClosePopover()
    onEventViewDetails(event)
  }

  // Check if today is in a specific month
  const isTodayInMonth = (year: number, month: number) => {
    return today.getFullYear() === year && today.getMonth() === month
  }

  // Day width based on view type
  const dayWidth = viewType === 'year' ? 16 : 28

  return (
    <div className="bg-white rounded-lg border border-gray-200 overflow-hidden">
      {/* Header with navigation */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-200 bg-gray-50">
        <button
          onClick={handlePrev}
          className="p-2 hover:bg-gray-200 rounded-lg transition-colors"
          aria-label={viewType === 'quarter' ? 'Previous quarter' : 'Previous year'}
        >
          <ChevronLeft className="h-5 w-5 text-gray-600" />
        </button>
        <h2 className="text-lg font-semibold text-gray-900">{getHeaderTitle()}</h2>
        <button
          onClick={handleNext}
          className="p-2 hover:bg-gray-200 rounded-lg transition-colors"
          aria-label={viewType === 'quarter' ? 'Next quarter' : 'Next year'}
        >
          <ChevronRight className="h-5 w-5 text-gray-600" />
        </button>
      </div>

      {/* Timeline */}
      <div className="overflow-x-auto" ref={scrollRef}>
        <div className="min-w-max">
          {monthRows.map(({ year, month, daysInMonth, events: monthEvents }) => {
            const rowHeight = Math.max(60, monthEvents.length * 28 + 16)

            return (
              <div key={`${year}-${month}`} className="flex border-b border-gray-100">
                {/* Month label */}
                <div className="w-24 flex-shrink-0 px-3 py-2 bg-gray-50 border-r border-gray-200 font-medium text-sm text-gray-700 sticky left-0 z-10">
                  {viewType === 'year' ? MONTH_ABBREV[month] : MONTH_NAMES[month]}
                </div>

                {/* Days grid */}
                <div
                  className="relative flex-1"
                  style={{ height: `${rowHeight}px` }}
                >
                  {/* Day columns */}
                  <div className="absolute inset-0 flex">
                    {Array.from({ length: daysInMonth }, (_, i) => {
                      const day = i + 1
                      const isToday = isTodayInMonth(year, month) && today.getDate() === day
                      const isWeekend = new Date(year, month, day).getDay() % 6 === 0

                      return (
                        <div
                          key={day}
                          className={cn(
                            'border-r border-gray-100 flex-shrink-0 relative',
                            isWeekend && 'bg-gray-50/50',
                            isToday && 'bg-blue-50'
                          )}
                          style={{ width: `${dayWidth}px` }}
                        >
                          {/* Day number header */}
                          <div
                            className={cn(
                              'text-xs text-center py-1 border-b border-gray-100',
                              isToday ? 'text-blue-600 font-semibold' : 'text-gray-400'
                            )}
                          >
                            {day}
                          </div>
                          {/* Today marker line */}
                          {isToday && (
                            <div className="absolute top-0 bottom-0 left-1/2 w-0.5 bg-blue-500 z-5" />
                          )}
                        </div>
                      )
                    })}
                  </div>

                  {/* Event bars */}
                  <div className="absolute inset-0 pt-6 px-0">
                    {monthEvents.map((eventData, idx) => (
                      <GanttEventBar
                        key={eventData.event.id}
                        event={eventData.event}
                        startDay={eventData.startDay}
                        endDay={eventData.endDay}
                        dayWidth={dayWidth}
                        row={idx}
                        onClick={handleEventClick}
                      />
                    ))}
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      </div>

      {/* Empty state */}
      {events.length === 0 && (
        <div className="text-center py-12 text-gray-500">
          No events scheduled for this {viewType === 'quarter' ? 'quarter' : 'year'}
        </div>
      )}

      {/* Popover */}
      {popoverEvent && popoverAnchor && (
        <EventPopover
          event={popoverEvent}
          anchorEl={popoverAnchor}
          onClose={handleClosePopover}
          onViewDetails={handleViewDetails}
        />
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { Save, Clock, RotateCcw, RotateCw } from 'lucide-react'
import AdminButton from '@/components/admin/ui/AdminButton'
import AdminAlert from '@/components/admin/ui/AdminAlert'

interface AutoSaveState<T> {
  data: T
  timestamp: number
  action: string
}

interface AutoSaveManagerProps<T> {
  data: T
  onSave: (data: T) => Promise<void>
  debounceMs?: number
  maxHistory?: number
}

export default function AutoSaveManager<T extends object>({
  data,
  onSave,
  debounceMs = 3000,
  maxHistory = 20
}: AutoSaveManagerProps<T>) {
  const [isSaving, setIsSaving] = useState(false)
  const [lastSaved, setLastSaved] = useState<Date | null>(null)
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle')
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  // Undo/Redo state
  const [history, setHistory] = useState<AutoSaveState<T>[]>([])
  const [historyIndex, setHistoryIndex] = useState(-1)
  const [canUndo, setCanUndo] = useState(false)
  const [canRedo, setCanRedo] = useState(false)

  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const lastDataRef = useRef<T>(data)

  // Add state to history
  const addToHistory = useCallback((newData: T, action: string = 'Edit') => {
    const newState: AutoSaveState<T> = {
      data: JSON.parse(JSON.stringify(newData)),
      timestamp: Date.now(),
      action
    }

    setHistory(prev => {
      // Remove any states after current index
      const newHistory = prev.slice(0, historyIndex + 1)
      // Add new state
      newHistory.push(newState)
      // Limit history size
      if (newHistory.length > maxHistory) {
        return newHistory.slice(-maxHistory)
      }
      return newHistory
    })

    setHistoryIndex(prev => Math.min(prev + 1, maxHistory - 1))
  }, [historyIndex, maxHistory])

  // Update undo/redo availability
  useEffect(() => {
    setCanUndo(historyIndex > 0)
    setCanRedo(historyIndex < history.length - 1)
  }, [historyIndex, history.length])

  // Handle data changes
  const handleChange = useCallback((newData: T, action: string = 'Edit') => {
    // Clear existing save timeout
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current)
    }

    // Check if data actually changed
    if (JSON.stringify(newData) !== JSON.stringify(lastDataRef.current)) {
      setHasUnsavedChanges(true)
      setSaveStatus('idle')

      // Add to history for undo/redo
      addToHistory(newData, action)

      // Set up auto-save
      saveTimeoutRef.current = setTimeout(() => {
        handleAutoSave()
      }, debounceMs)

      lastDataRef.current = newData
    }
  }, [debounceMs, addToHistory])

  // Auto-save function
  const handleAutoSave = useCallback(async () => {
    if (!hasUnsavedChanges || isSaving) return

    try {
      setIsSaving(true)
      setSaveStatus('saving')
      setErrorMessage(null)

      await onSave(lastDataRef.current)

      setLastSaved(new Date())
      setHasUnsavedChanges(false)
      setSaveStatus('saved')

      // Clear success status after 3 seconds
      setTimeout(() => {
        if (saveStatus === 'saved') {
          setSaveStatus('idle')
        }
      }, 3000)
    } catch (error) {
      console.error('Auto-save failed:', error)
      setErrorMessage('Auto-save failed. Please try saving manually.')
      setSaveStatus('error')
    } finally {
      setIsSaving(false)
    }
  }, [hasUnsavedChanges, isSaving, onSave, saveStatus])

  // Manual save function
  const handleManualSave = useCallback(async () => {
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current)
    }
    await handleAutoSave()
  }, [handleAutoSave]);

  // Undo function
  const handleUndo = useCallback(() => {
    if (canUndo && historyIndex > 0) {
      const newIndex = historyIndex - 1
      const previousState = history[newIndex]

      setHistoryIndex(newIndex)
      lastDataRef.current = previousState.data
      setHasUnsavedChanges(true)
      setSaveStatus('idle')

      // Trigger parent update
      if (window.onDataChange) {
        window.onDataChange(previousState.data, 'Undo')
      }
    }
  }, [canUndo, historyIndex, history])

  // Redo function
  const handleRedo = useCallback(() => {
    if (canRedo && historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1
      const nextState = history[newIndex]

      setHistoryIndex(newIndex)
      lastDataRef.current = nextState.data
      setHasUnsavedChanges(true)
      setSaveStatus('idle')

      // Trigger parent update
      if (window.onDataChange) {
        window.onDataChange(nextState.data, 'Redo')
      }
    }
  }, [canRedo, historyIndex, history])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current)
      }
    }
  }, [])

  // Format time ago
  const formatTimeAgo = (date: Date) => {
    const seconds = Math.floor((Date.now() - date.getTime()) / 1000)

    if (seconds < 60) return 'just now'
    if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`
    if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`
    return `${Math.floor(seconds / 86400)}d ago`
  }

  return (
    <div className="space-y-4">
      {/* Save Status Bar */}
      <div className="flex items-center justify-between p-3 bg-gray-50 border border-gray-200 rounded-lg">
        <div className="flex items-center space-x-4">
          {/* Status Indicator */}
          <div className="flex items-center space-x-2">
            <div className={`w-2 h-2 rounded-full ${
              saveStatus === 'saved' ? 'bg-green-500' :
              saveStatus === 'saving' ? 'bg-yellow-500 animate-pulse' :
              saveStatus === 'error' ? 'bg-red-500' :
              hasUnsavedChanges ? 'bg-orange-500' : 'bg-gray-400'
            }`} />
            <span className="text-sm text-gray-600">
              {saveStatus === 'saved' ? 'Saved' :
               saveStatus === 'saving' ? 'Saving...' :
               saveStatus === 'error' ? 'Error' :
               hasUnsavedChanges ? 'Unsaved changes' : 'Up to date'}
            </span>
          </div>

          {/* Last Saved */}
          {lastSaved && (
            <div className="flex items-center text-sm text-gray-500">
              <Clock className="w-4 h-4 mr-1" />
              {formatTimeAgo(lastSaved)}
            </div>
          )}

          {/* History Info */}
          {history.length > 0 && (
            <div className="text-sm text-gray-500">
              History: {historyIndex + 1}/{history.length}
            </div>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex items-center space-x-2">
          {/* Undo/Redo */}
          <AdminButton
            variant="ghost"
            size="sm"
            onClick={handleUndo}
            disabled={!canUndo}
            title="Undo"
          >
            <RotateCcw className="w-4 h-4" />
          </AdminButton>

          <AdminButton
            variant="ghost"
            size="sm"
            onClick={handleRedo}
            disabled={!canRedo}
            title="Redo"
          >
            <RotateCw className="w-4 h-4" />
          </AdminButton>

          {/* Save Button */}
          <AdminButton
            variant="primary"
            size="sm"
            onClick={handleManualSave}
            disabled={!hasUnsavedChanges || isSaving}
          >
            <Save className="w-4 h-4 mr-1" />
            {isSaving ? 'Saving...' : 'Save'}
          </AdminButton>
        </div>
      </div>

      {/* Error Message */}
      {errorMessage && (
        <AdminAlert variant="error">
          {errorMessage}
        </AdminAlert>
      )}

      {/* Success Message */}
      {saveStatus === 'saved' && (
        <AdminAlert variant="success">
          All changes saved successfully
        </AdminAlert>
      )}

      {/* Auto-save Info */}
      <div className="text-xs text-gray-500">
        Auto-save is enabled. Changes are automatically saved after {debounceMs/1000} seconds of inactivity.
      </div>
    </div>
  )
}

// Global callback for data changes
declare global {
  interface Window {
    onDataChange?: (data: unknown, action: string) => void
  }
}

'use client'

import React from 'react'
import Link from 'next/link'
import { ChevronRight } from 'lucide-react'

interface CMSCardProps {
  title: string
  description: string
  icon?: React.ReactNode
  status?: 'published' | 'draft' | 'archived'
  metadata?: {
    label: string
    value: string
  }[]
  actions?: {
    label: string
    icon?: React.ReactNode
    onClick?: () => void
    href?: string
    variant?: 'primary' | 'secondary' | 'danger'
  }[]
  onClick?: () => void
  href?: string
  className?: string
}

export function CMSCard({
  title,
  description,
  icon,
  status,
  metadata = [],
  actions = [],
  onClick,
  href,
  className = '',
}: CMSCardProps) {
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'published':
        return 'bg-green-100 text-green-800'
      case 'draft':
        return 'bg-yellow-100 text-yellow-800'
      case 'archived':
        return 'bg-gray-100 text-gray-800'
      default:
        return 'bg-blue-100 text-blue-800'
    }
  }

  const getActionColor = (variant?: string) => {
    switch (variant) {
      case 'primary':
        return 'text-heiwaOrange-600 hover:text-heiwaOrange-700'
      case 'danger':
        return 'text-red-600 hover:text-red-700'
      default:
        return 'text-gray-600 hover:text-gray-700'
    }
  }

  const content = (
    <div className={`bg-white border border-gray-200 rounded-lg p-5 sm:p-6 hover:shadow-lg hover:border-blue-200 transition-all duration-200 ${className}`}>
      {/* Header */}
      <div className="flex items-start justify-between mb-3 sm:mb-4 gap-2">
        <div className="flex items-start gap-2 sm:gap-3 flex-1 min-w-0">
          {icon && (
            <div className="flex-shrink-0 w-8 h-8 sm:w-10 sm:h-10 bg-heiwaOrange-100 rounded-lg flex items-center justify-center text-heiwaOrange-600">
              {icon}
            </div>
          )}
          <div className="flex-1 min-w-0">
            <h3 className="text-base sm:text-lg font-semibold text-gray-900 truncate">{title}</h3>
            <p className="text-gray-600 text-xs sm:text-sm mt-1 line-clamp-2">{description}</p>
          </div>
        </div>
        {status && (
          <span className={`inline-flex items-center px-3 sm:px-3.5 py-1 rounded-full text-xs sm:text-sm font-semibold ${getStatusColor(status)} flex-shrink-0 shadow-sm`}>
            {status.charAt(0).toUpperCase() + status.slice(1)}
          </span>
        )}
      </div>

      {/* Metadata */}
      {metadata.length > 0 && (
        <div className="mb-4 sm:mb-5 pb-4 sm:pb-5 border-t border-gray-100 pt-4 sm:pt-5">
          <div className="space-y-3">
            {metadata.map((item, idx) => (
              <div key={idx} className="min-w-0">
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-1">{item.label}</p>
                <p className="text-sm sm:text-base font-medium text-gray-900">{item.value}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Actions */}
      {actions.length > 0 && (
        <div className="flex items-center gap-1 sm:gap-2 pt-3 sm:pt-4 border-t border-gray-100 flex-wrap">
          {actions.map((action, idx) => {
            const buttonContent = (
              <>
                {action.icon && <span className="w-3 h-3 sm:w-4 sm:h-4">{action.icon}</span>}
                <span className="hidden sm:inline">{!action.icon && action.label}</span>
              </>
            )
            const buttonClass = `inline-flex items-center gap-1 px-2 sm:px-3 py-1.5 sm:py-2 rounded-md text-xs sm:text-sm font-medium transition-colors ${getActionColor(action.variant)}`

            if (action.href) {
              return (
                <Link
                  key={idx}
                  href={action.href}
                  onClick={(e) => e.stopPropagation()}
                  className={buttonClass}
                  title={action.label}
                >
                  {buttonContent}
                </Link>
              )
            }

            return (
              <button
                key={idx}
                onClick={(e) => {
                  e.stopPropagation()
                  e.preventDefault()
                  action.onClick?.()
                }}
                className={buttonClass}
                title={action.label}
              >
                {buttonContent}
              </button>
            )
          })}
        </div>
      )}
    </div>
  )

  if (href) {
    return <Link href={href}>{content}</Link>
  }

  if (onClick) {
    return (
      <button onClick={onClick} className="w-full text-left">
        {content}
      </button>
    )
  }

  return content
}

export default CMSCard

