import { useState, useEffect, useRef } from 'react'
import { Users, MessageSquare, Lock, Unlock, AlertCircle } from 'lucide-react'
import AdminButton from '@/components/admin/ui/AdminButton'
import AdminModal from '@/components/admin/ui/AdminModal'
import AdminAlert from '@/components/admin/ui/AdminAlert'

interface ActiveUser {
  id: string
  name: string
  email: string
  avatar?: string
  color: string
  cursor?: {
    section: string
    position: number
  }
  lastSeen: Date
}

interface Comment {
  id: string
  userId: string
  userName: string
  sectionId: string
  content: string
  createdAt: Date
  resolved: boolean
}

interface CollaborationManagerProps {
  pageSlug: string
  currentUser: {
    id: string
    name: string
    email: string
  }
  isLocked: boolean
  onLockToggle: (locked: boolean) => void
}

export default function CollaborationManager({
  pageSlug,
  currentUser,
  isLocked,
  onLockToggle
}: CollaborationManagerProps) {
  const [activeUsers, setActiveUsers] = useState<ActiveUser[]>([])
  const [comments, setComments] = useState<Comment[]>([])
  const [showUsers, setShowUsers] = useState(false)
  const [showComments, setShowComments] = useState(false)
  const [newComment, setNewComment] = useState('')
  const [selectedSection, setSelectedSection] = useState('')
  const [connectionError, setConnectionError] = useState<string | null>(null)

  const wsRef = useRef<WebSocket | null>(null)
  const heartbeatRef = useRef<NodeJS.Timeout | null>(null)

  // Generate random color for user
  const generateUserColor = () => {
    const colors = [
      '#3B82F6', '#EF4444', '#10B981', '#F59E0B', 
      '#8B5CF6', '#EC4899', '#14B8A6', '#F97316'
    ]
    return colors[Math.floor(Math.random() * colors.length)]
  }

  // Initialize WebSocket connection
  useEffect(() => {
    const initWebSocket = () => {
      try {
        // For demo purposes, we'll simulate WebSocket connection
        // In production, this would connect to your WebSocket server
        setConnectionError(null)

        // Simulate active users
        setActiveUsers([
          {
            id: currentUser.id,
            name: currentUser.name,
            email: currentUser.email,
            color: generateUserColor(),
            lastSeen: new Date()
          }
        ])

        // Start heartbeat
        heartbeatRef.current = setInterval(() => {
          // Send heartbeat to WebSocket server
          console.log('Heartbeat sent')
        }, 30000)

      } catch (error) {
        console.error('WebSocket connection failed:', error)
        setConnectionError('Failed to connect to collaboration server')
      }
    }

    initWebSocket()

    return () => {
      if (wsRef.current) {
        wsRef.current.close()
      }
      if (heartbeatRef.current) {
        clearInterval(heartbeatRef.current)
      }
    }
  }, [currentUser])

  // Handle lock toggle
  const handleLockToggle = () => {
    const newLockState = !isLocked
    onLockToggle(newLockState)

    // Notify other users
    if (wsRef.current) {
      wsRef.current.send(JSON.stringify({
        type: 'lock_change',
        pageSlug,
        locked: newLockState,
        userId: currentUser.id
      }))
    }
  }

  // Add comment
  const handleAddComment = () => {
    if (!newComment.trim() || !selectedSection) return

    const comment: Comment = {
      id: Date.now().toString(),
      userId: currentUser.id,
      userName: currentUser.name,
      sectionId: selectedSection,
      content: newComment.trim(),
      createdAt: new Date(),
      resolved: false
    }

    setComments(prev => [...prev, comment])
    setNewComment('')
    setSelectedSection('')

    // Send to WebSocket
    if (wsRef.current) {
      wsRef.current.send(JSON.stringify({
        type: 'new_comment',
        pageSlug,
        comment
      }))
    }
  }

  // Resolve comment
  const handleResolveComment = (commentId: string) => {
    setComments(prev => 
      prev.map(c => c.id === commentId ? { ...c, resolved: true } : c)
    )

    // Send to WebSocket
    if (wsRef.current) {
      wsRef.current.send(JSON.stringify({
        type: 'resolve_comment',
        pageSlug,
        commentId,
        userId: currentUser.id
      }))
    }
  }

  // Get user initials
  const getUserInitials = (name: string) => {
    return name
      .split(' ')
      .map(word => word.charAt(0))
      .join('')
      .toUpperCase()
      .slice(0, 2)
  }

  // Format time ago
  const formatTimeAgo = (date: Date) => {
    const seconds = Math.floor((Date.now() - date.getTime()) / 1000)

    if (seconds < 60) return 'just now'
    if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`
    if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`
    return `${Math.floor(seconds / 86400)}d ago`
  }

  const unresolvedComments = comments.filter(c => !c.resolved)

  return (
    <div className="space-y-4">
      {/* Connection Status */}
      {connectionError && (
        <AdminAlert variant="error">
          <div className="flex items-center">
            <AlertCircle className="w-4 h-4 mr-2" />
            {connectionError}
          </div>
        </AdminAlert>
      )}

      {/* Collaboration Bar */}
      <div className="flex items-center justify-between p-3 bg-gray-50 border border-gray-200 rounded-lg">
        <div className="flex items-center space-x-4">
          {/* Active Users */}
          <div className="flex items-center space-x-2">
            <Users className="w-4 h-4 text-gray-500" />
            <div className="flex -space-x-2">
              {activeUsers.slice(0, 3).map(user => (
                <div
                  key={user.id}
                  className="w-8 h-8 rounded-full flex items-center justify-center text-white text-xs font-medium border-2 border-white"
                  style={{ backgroundColor: user.color }}
                  title={user.name}
                >
                  {getUserInitials(user.name)}
                </div>
              ))}
              {activeUsers.length > 3 && (
                <div className="w-8 h-8 rounded-full bg-gray-300 flex items-center justify-center text-gray-600 text-xs font-medium border-2 border-white">
                  +{activeUsers.length - 3}
                </div>
              )}
            </div>
            <button
              onClick={() => setShowUsers(true)}
              className="text-sm text-blue-600 hover:text-blue-700"
            >
              {activeUsers.length} active
            </button>
          </div>

          {/* Comments */}
          <div className="flex items-center space-x-2">
            <MessageSquare className="w-4 h-4 text-gray-500" />
            <button
              onClick={() => setShowComments(true)}
              className="text-sm text-blue-600 hover:text-blue-700"
            >
              {unresolvedComments.length} comments
            </button>
          </div>

          {/* Page Lock Status */}
          <div className="flex items-center space-x-2">
            {isLocked ? (
              <Lock className="w-4 h-4 text-orange-500" />
            ) : (
              <Unlock className="w-4 h-4 text-green-500" />
            )}
            <span className="text-sm text-gray-600">
              {isLocked ? 'Page locked' : 'Page unlocked'}
            </span>
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center space-x-2">
          <AdminButton
            variant="outline"
            size="sm"
            onClick={handleLockToggle}
          >
            {isLocked ? (
              <>
                <Unlock className="w-4 h-4 mr-1" />
                Unlock
              </>
            ) : (
              <>
                <Lock className="w-4 h-4 mr-1" />
                Lock
              </>
            )}
          </AdminButton>
        </div>
      </div>

      {/* Active Users Modal */}
      <AdminModal
        isOpen={showUsers}
        onClose={() => setShowUsers(false)}
        title="Active Users"
        size="md"
      >
        <div className="space-y-3">
          {activeUsers.length === 0 ? (
            <p className="text-gray-500 text-center py-4">No active users</p>
          ) : (
            activeUsers.map(user => (
              <div key={user.id} className="flex items-center justify-between p-3 border border-gray-200 rounded-lg">
                <div className="flex items-center space-x-3">
                  <div
                    className="w-10 h-10 rounded-full flex items-center justify-center text-white font-medium"
                    style={{ backgroundColor: user.color }}
                  >
                    {getUserInitials(user.name)}
                  </div>
                  <div>
                    <p className="font-medium text-gray-900">{user.name}</p>
                    <p className="text-sm text-gray-500">{user.email}</p>
                  </div>
                </div>
                <div className="text-sm text-gray-500">
                  {formatTimeAgo(user.lastSeen)}
                </div>
              </div>
            ))
          )}
        </div>
      </AdminModal>

      {/* Comments Modal */}
      <AdminModal
        isOpen={showComments}
        onClose={() => setShowComments(false)}
        title="Comments"
        size="lg"
      >
        <div className="space-y-4">
          {/* Add Comment */}
          <div className="border border-gray-200 rounded-lg p-4">
            <h4 className="font-medium text-gray-900 mb-3">Add Comment</h4>
            <div className="space-y-3">
              <input
                type="text"
                value={selectedSection}
                onChange={(e) => setSelectedSection(e.target.value)}
                placeholder="Section ID (optional)"
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <textarea
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder="Write your comment..."
                rows={3}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <AdminButton
                variant="primary"
                onClick={handleAddComment}
                disabled={!newComment.trim()}
              >
                Add Comment
              </AdminButton>
            </div>
          </div>

          {/* Comments List */}
          <div className="space-y-3 max-h-64 overflow-y-auto">
            {comments.length === 0 ? (
              <p className="text-gray-500 text-center py-4">No comments yet</p>
            ) : (
              comments.map(comment => (
                <div
                  key={comment.id}
                  className={`p-4 border rounded-lg ${
                    comment.resolved ? 'border-gray-200 bg-gray-50' : 'border-blue-200 bg-blue-50'
                  }`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center space-x-2 mb-2">
                        <span className="font-medium text-gray-900">{comment.userName}</span>
                        <span className="text-sm text-gray-500">
                          {formatTimeAgo(comment.createdAt)}
                        </span>
                        {comment.sectionId && (
                          <span className="text-xs text-gray-500 bg-gray-200 px-2 py-1 rounded">
                            {comment.sectionId}
                          </span>
                        )}
                      </div>
                      <p className="text-gray-700">{comment.content}</p>
                    </div>
                    {!comment.resolved && (
                      <AdminButton
                        variant="outline"
                        size="sm"
                        onClick={() => handleResolveComment(comment.id)}
                      >
                        Resolve
                      </AdminButton>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </AdminModal>
    </div>
  )
}

'use client'

import { useState, useRef } from 'react'
import { Upload, X, Image as ImageIcon } from 'lucide-react'
import AdminButton from '@/components/admin/ui/AdminButton'

interface ImageUploadProps {
  value: string
  onChange: (url: string) => void
  placeholder?: string
  accept?: string
  maxSize?: number // in MB
}

export default function ImageUpload({
  value,
  onChange,
  placeholder = 'Upload an image or enter URL',
  accept = 'image/*',
  maxSize = 5
}: ImageUploadProps) {
  const [uploading, setUploading] = useState(false)
  const [dragActive, setDragActive] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFileSelect = async (file: File) => {
    setError(null)

    // Validate file size
    if (file.size > maxSize * 1024 * 1024) {
      setError(`File size must be less than ${maxSize}MB`)
      return
    }

    // Validate file type
    if (!file.type.startsWith('image/')) {
      setError('Only image files are allowed')
      return
    }

    try {
      setUploading(true)

      // For now, we'll create a local URL
      // In production, you would upload to Supabase Storage or CDN
      const url = URL.createObjectURL(file)
      onChange(url)
    } catch {
      setError('Failed to upload image')
    } finally {
      setUploading(false)
    }
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    setDragActive(false)

    const files = Array.from(e.dataTransfer.files)
    if (files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setDragActive(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setDragActive(false)
  }

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (files && files.length > 0) {
      handleFileSelect(files[0])
    }
  }

  const handleUrlChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange(e.target.value)
  }

  const handleRemove = () => {
    onChange('')
    setError(null)
  }

  return (
    <div className="space-y-4">
      {/* Upload Area */}
      {!value && (
        <div
          className={`border-2 border-dashed rounded-lg p-6 text-center transition-colors ${
            dragActive
              ? 'border-blue-500 bg-blue-50'
              : 'border-gray-300 hover:border-gray-400'
          }`}
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
        >
          <div className="flex flex-col items-center">
            <ImageIcon className="w-12 h-12 text-gray-400 mb-3" />
            <p className="text-gray-600 mb-2">
              {uploading ? 'Uploading...' : placeholder}
            </p>
            <p className="text-sm text-gray-500 mb-4">
              Drag and drop an image here, or click to browse
            </p>
            <AdminButton
              variant="outline"
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
            >
              <Upload className="w-4 h-4 mr-2" />
              {uploading ? 'Uploading...' : 'Choose File'}
            </AdminButton>
          </div>
          <input
            ref={fileInputRef}
            type="file"
            accept={accept}
            onChange={handleFileInputChange}
            className="hidden"
          />
        </div>
      )}

      {/* URL Input */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Or enter image URL
        </label>
        <input
          type="url"
          value={value}
          onChange={handleUrlChange}
          placeholder="https://example.com/image.jpg"
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        />
      </div>

      {/* Preview */}
      {value && (
        <div>
          <div className="flex items-center justify-between mb-2">
            <label className="block text-sm font-medium text-gray-700">
              Preview
            </label>
            <AdminButton
              variant="ghost"
              size="sm"
              onClick={handleRemove}
            >
              <X className="w-4 h-4 mr-1" />
              Remove
            </AdminButton>
          </div>
          <div className="border border-gray-200 rounded-lg overflow-hidden">
            <img
              src={value}
              alt="Preview"
              className="w-full h-48 object-cover"
              onError={(e) => {
                e.currentTarget.src = '/images/placeholder.jpg'
              }}
            />
          </div>
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="text-red-600 text-sm">
          {error}
        </div>
      )}

      {/* File Info */}
      {value && !value.startsWith('blob:') && (
        <div className="text-xs text-gray-500">
          Image URL: {value}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { DragDropContext, Droppable, Draggable } from '@hello-pangea/dnd'
import { Plus, Settings, Eye, Save, ArrowLeft, Trash2 } from 'lucide-react'
import AdminButton from '@/components/admin/ui/AdminButton'
import AdminAlert from '@/components/admin/ui/AdminAlert'
import AdminModal from '@/components/admin/ui/AdminModal'
import SectionCard from './SectionCard'
import PageMetadataEditor from './PageMetadataEditor'
import SectionEditModal from './SectionEditModal'
import SectionTypeSelector from './SectionTypeSelector'
import AutoSaveManager from './AutoSaveManager'
import VersionHistory from './VersionHistory'
import CollaborationManager from './CollaborationManager'
import { PageSection, PageData } from '@/lib/cms-types'

interface PageEditorProps {
  pageSlug: string
  onBack: () => void
  initialData?: PageData
}

const pageTitles: Record<string, string> = {
  flow: 'Heiwa Flow',
  play: 'Heiwa Play',
  surf: 'Heiwa Surf',
  'surf-weeks': 'Surf Weeks',
  'the-spot': 'The Spot',
  about: 'About Us',
  contact: 'Contact'
}

const pageDescriptions: Record<string, string> = {
  flow: 'Yoga, massage, ice bath, sauna, and wellness services',
  play: 'Activities, experiences, and recreational services',
  surf: 'Surf lessons, equipment, and surf week information',
  'surf-weeks': 'Manage surf weeks listing, process, and content sections',
  'the-spot': 'Beach club, restaurant, and local attractions',
  about: 'Company story, team, and mission',
  contact: 'Contact information, location, and inquiry forms'
}

export default function PageEditor({ pageSlug, onBack, initialData }: PageEditorProps) {
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState<string | null>(null)
  const [pageData, setPageData] = useState<PageData | null>(null)
  const [showAddSection, setShowAddSection] = useState(false)
  const [showPageSettings, setShowPageSettings] = useState(false)
  const [hasChanges, setHasChanges] = useState(false)
  const [showVersionHistory, setShowVersionHistory] = useState(false)
  const [isPageLocked, setIsPageLocked] = useState(false)
  const [autoSaveEnabled, setAutoSaveEnabled] = useState(true)

  // Auto-save functionality
  useEffect(() => {
    if (!hasChanges) return

    const timer = setTimeout(() => {
      handleAutoSave()
    }, 3000) // Auto-save after 3 seconds of inactivity

    return () => clearTimeout(timer)
  }, [hasChanges, pageData])

  const fetchPageData = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)

      // Fetch sections and metadata in parallel
      const [sectionsResponse, metadataResponse] = await Promise.all([
        fetch(`/api/admin/pages?page_slug=${encodeURIComponent(pageSlug)}`, {
          method: 'GET',
          headers: { 'Content-Type': 'application/json' }
        }),
        fetch(`/api/cms/pages/${encodeURIComponent(pageSlug)}`, {
          method: 'GET',
          headers: { 'Content-Type': 'application/json' }
        })
      ])

      const sectionsResult = await sectionsResponse.json().catch(() => null)
      if (!sectionsResponse.ok || !sectionsResult?.success) {
        throw new Error(sectionsResult?.error || `Failed to load page data (${sectionsResponse.status})`)
      }

      const sections = (sectionsResult.data || []) as PageSection[]

      // Parse metadata response - may not exist for new pages
      let seoTitle = pageTitles[pageSlug] || ''
      let seoDescription = pageDescriptions[pageSlug] || ''
      let featuredImage = ''
      let lastModified = new Date().toISOString()

      if (metadataResponse.ok) {
        const metadataResult = await metadataResponse.json().catch(() => null)
        if (metadataResult?.success && metadataResult?.data) {
          const meta = metadataResult.data
          seoTitle = meta.title || seoTitle
          seoDescription = meta.meta_description || seoDescription
          featuredImage = meta.og_image || ''
          lastModified = meta.updated_at || lastModified
        }
      }

      setPageData({
        slug: pageSlug,
        title: pageTitles[pageSlug] || pageSlug.charAt(0).toUpperCase() + pageSlug.slice(1),
        description: pageDescriptions[pageSlug] || '',
        sections: sections || [],
        metadata: {
          seoTitle,
          seoDescription,
          featuredImage,
          lastModified
        }
      })
    } catch (err) {
      setError('Failed to load page data')
    } finally {
      setLoading(false)
    }
  }, [pageSlug])

  useEffect(() => {
    fetchPageData()
  }, [fetchPageData])

  const handleSave = async () => {
    try {
      setSaving(true)
      setError(null)
      setSuccess(null)

      // Save all changes
      await handleAutoSave()

      setSuccess('Page saved successfully')
      setTimeout(() => setSuccess(null), 3000)
      setHasChanges(false)
    } catch (err) {
      setError('Failed to save page')
    } finally {
      setSaving(false)
    }
  }

  const handleDragEnd = async (result: { source: { index: number }; destination: { index: number } | null }) => {
    if (!result.destination || !pageData) return

    const items = Array.from(pageData.sections)
    const [reorderedItem] = items.splice(result.source.index, 1)
    items.splice(result.destination.index, 0, reorderedItem)

    // Update order indices
    const updatedSections = items.map((section, index) => ({
      ...section,
      order_index: index
    }))

    setPageData({ ...pageData, sections: updatedSections })
    setHasChanges(true)

    // Update database
    try {
      const updatePromises = updatedSections.map(async (section) => {
        const response = await fetch(`/api/admin/pages/${section.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ order_index: section.order_index }),
        })

        if (!response.ok) {
          const errorText = await response.text()
          let errorMessage = `HTTP ${response.status}: ${response.statusText}`
          try {
            const errorJson = JSON.parse(errorText)
            errorMessage = errorJson.error || errorJson.message || errorMessage
          } catch {
            errorMessage = errorText || errorMessage
          }
          throw new Error(`Failed to update order for section ${section.id}: ${errorMessage}`)
        }

        const result = await response.json()
        if (!result.success) {
          throw new Error(`Failed to update order: ${result.error || 'Unknown error'}`)
        }

        return result.data
      })

      await Promise.all(updatePromises)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to update section order'
      console.error('Error updating section order:', err)
      setError(errorMessage)
    }
  }

  const handleAddSection = async (sectionType: string, sectionName: string) => {
    if (!pageData) return

    try {
      setError(null)
      const newSection = {
        page_slug: pageSlug,
        section_type: sectionType,
        section_name: sectionName || `${sectionType} section`,
        content: {}, // JSONB field - empty object is valid
        order_index: pageData.sections.length,
        is_active: true
      }

      const response = await fetch('/api/admin/pages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newSection),
      })

      const responseData = await response.json()

      if (!response.ok) {
        const errorMessage = responseData.error || responseData.message || `Failed to create section (${response.status})`
        console.error('Failed to add section:', {
          status: response.status,
          error: responseData.error,
          message: responseData.message,
          data: responseData
        })
        throw new Error(errorMessage)
      }

      if (!responseData.success) {
        throw new Error(responseData.error || 'Section creation failed')
      }

      const { data } = responseData
      setPageData({
        ...pageData,
        sections: [...pageData.sections, data]
      })
      setHasChanges(true)
      setShowAddSection(false)
      setSuccess('Section added successfully')
      setTimeout(() => setSuccess(null), 3000)
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to add section. Please check the console for details.'
      console.error('Error adding section:', err)
      setError(errorMessage)
    }
  }

  const handleEditSection = (section: PageSection) => {
    setSelectedSection(section)
    setShowEditSection(true)
  }

  const handleSaveSection = async (updatedSection: PageSection) => {
    try {
      const response = await fetch(`/api/admin/pages/${updatedSection.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          section_name: updatedSection.section_name,
          content: updatedSection.content,
          updated_at: updatedSection.updated_at
        }),
      })

      if (!response.ok) {
        const errorText = await response.text()
        let errorMessage = `HTTP ${response.status}: ${response.statusText}`
        try {
          const errorJson = JSON.parse(errorText)
          errorMessage = errorJson.error || errorJson.message || errorMessage
        } catch {
          errorMessage = errorText || errorMessage
        }
        throw new Error(`Failed to update section: ${errorMessage}`)
      }

      const result = await response.json()
      if (!result.success) {
        throw new Error(`Failed to save section: ${result.error || 'Unknown error'}`)
      }

      // Verify the save persisted
      if (!result.data || !result.data.id) {
        throw new Error('Save response missing data - save may not have persisted')
      }

      if (pageData) {
        setPageData({
          ...pageData,
          sections: pageData.sections.map(s => 
            s.id === updatedSection.id ? updatedSection : s
          )
        })
        setHasChanges(true)
        setSuccess('Section saved successfully')
        setTimeout(() => setSuccess(null), 3000)
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to save section'
      console.error('Error saving section:', err)
      setError(errorMessage)
    }
  }

  const handleCreateVersion = async (data: PageData, notes?: string) => {
    try {
      const response = await fetch('/api/admin/page-versions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          page_slug: pageSlug,
          content: data,
          notes: notes || undefined,
        })
      })

      if (!response.ok) {
        const result = await response.json().catch(() => null)
        throw new Error(result?.error || `Failed to create version (${response.status})`)
      }
    } catch (err) {
      console.error('Failed to create version:', err)
    }
  }

  const handleRestoreVersion = async (version: { content: Record<string, unknown> }) => {
    try {
      // Restore the content
      setPageData(version.content as unknown as PageData)
      setHasChanges(true)
      setSuccess('Version restored successfully')
      setTimeout(() => setSuccess(null), 3000)
    } catch (err) {
      setError('Failed to restore version')
    }
  }

  const handleAutoSave = async (data?: PageData) => {
    const dataToSave = data || pageData
    if (!dataToSave || !autoSaveEnabled) return

    try {
      setSaving(true)

      // Create version history entry
      await handleCreateVersion(dataToSave, 'Auto-save')

      // Update all sections
      const savePromises = dataToSave.sections.map(async (section) => {
        const response = await fetch(`/api/admin/pages/${section.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            section_name: section.section_name,
            content: section.content,
            order_index: section.order_index,
            is_active: section.is_active,
            updated_at: new Date().toISOString()
          }),
        })

        if (!response.ok) {
          const errorText = await response.text()
          let errorMessage = `HTTP ${response.status}: ${response.statusText}`
          try {
            const errorJson = JSON.parse(errorText)
            errorMessage = errorJson.error || errorJson.message || errorMessage
          } catch {
            errorMessage = errorText || errorMessage
          }
          throw new Error(`Failed to save section ${section.section_name || section.id}: ${errorMessage}`)
        }

        const result = await response.json()
        if (!result.success) {
          throw new Error(`Failed to save section ${section.section_name || section.id}: ${result.error || 'Unknown error'}`)
        }

        // Verify the save persisted - API returns { success: true, data: {...} }
        if (!result.data || !result.data.id) {
          throw new Error(`Save response missing data for section ${section.section_name || section.id}`)
        }

        return result.data
      })

      await Promise.all(savePromises)
      setHasChanges(false)
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Auto-save failed'
      console.error('Auto-save error:', err)
      setError(errorMessage)
      // Don't clear hasChanges on error so user can retry
    } finally {
      setSaving(false)
    }
  }

  const handleDeleteSection = async (sectionId: string) => {
    if (!confirm('Are you sure you want to delete this section?')) return

    try {
      const response = await fetch(`/api/admin/pages/${sectionId}`, {
        method: 'DELETE',
      })

      if (!response.ok) throw new Error('Failed to delete section')

      if (pageData) {
        setPageData({
          ...pageData,
          sections: pageData.sections.filter(s => s.id !== sectionId)
        })
        setHasChanges(true)
      }
    } catch (err) {
      setError('Failed to delete section')
    }
  }

  const handleDuplicateSection = async (section: PageSection) => {
    if (!pageData) return

    try {
      const duplicatedSection = {
        page_slug: pageSlug,
        section_type: section.section_type,
        section_name: `${section.section_name} (Copy)`,
        content: section.content,
        order_index: pageData.sections.length,
        is_active: true
      }

      const response = await fetch('/api/admin/pages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(duplicatedSection),
      })

      if (!response.ok) throw new Error('Failed to duplicate section')

      const { data } = await response.json()
      setPageData({
        ...pageData,
        sections: [...pageData.sections, data]
      })
      setHasChanges(true)
    } catch (err) {
      setError('Failed to duplicate section')
    }
  }

  const handleToggleActive = async (sectionId: string, isActive: boolean) => {
    try {
      const response = await fetch(`/api/admin/pages/${sectionId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          is_active: isActive,
          updated_at: new Date().toISOString()
        }),
      })

      if (!response.ok) throw new Error('Failed to update section')

      if (pageData) {
        setPageData({
          ...pageData,
          sections: pageData.sections.map(s => 
            s.id === sectionId ? { ...s, is_active: isActive } : s
          )
        })
        setHasChanges(true)
      }
    } catch (err) {
      setError('Failed to update section status')
    }
  }

  if (loading) {
    return (
      <div className="animate-pulse">
        <div className="h-8 bg-gray-200 rounded w-1/4 mb-6"></div>
        <div className="h-4 bg-gray-200 rounded w-1/2 mb-8"></div>
        <div className="space-y-4">
          {[1, 2, 3].map(i => (
            <div key={i} className="bg-white border border-gray-200 rounded-lg p-6">
              <div className="h-6 bg-gray-200 rounded w-3/4 mb-2"></div>
              <div className="h-4 bg-gray-200 rounded w-full"></div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  if (!pageData) {
    return (
      <div className="text-center">
        <h3 className="text-lg font-medium text-gray-900 mb-2">Page not found</h3>
        <p className="text-gray-500">The page you're looking for doesn't exist.</p>
      </div>
    )
  }

  return (
    <div className="max-w-6xl mx-auto">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center">
          <button
            onClick={onBack}
            className="mr-4 p-2 hover:bg-gray-100 rounded-lg"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-3xl font-bold text-gray-900 mb-2">{pageData.title}</h1>
            <p className="text-gray-600">/{pageData.slug} • {pageData.description}</p>
          </div>
        </div>
        <div className="flex items-center space-x-3">
          {hasChanges && (
            <span className="text-sm text-orange-600 font-medium">Unsaved changes</span>
          )}
          <AdminButton variant="outline" onClick={() => setShowVersionHistory(true)}>
            <Clock className="w-4 h-4 mr-2" />
            Version History
          </AdminButton>
          <AdminButton variant="outline" onClick={() => setShowPageSettings(true)}>
            <Settings className="w-4 h-4 mr-2" />
            Page Settings
          </AdminButton>
          <AdminButton variant="outline">
            <Eye className="w-4 h-4 mr-2" />
            Preview
          </AdminButton>
          <AdminButton variant="primary" onClick={handleSave} disabled={saving}>
            <Save className="w-4 h-4 mr-2" />
            {saving ? 'Saving...' : 'Save'}
          </AdminButton>
        </div>
      </div>

      {/* Auto-Save Manager */}
      {autoSaveEnabled && (
        <AutoSaveManager
          data={pageData}
          onSave={handleAutoSave}
          debounceMs={3000}
          maxHistory={20}
        />
      )}

      {/* Collaboration Manager */}
      <CollaborationManager
        pageSlug={pageSlug}
        currentUser={{
          id: 'admin',
          name: 'Admin User',
          email: 'admin@heiwa-house.com'
        }}
        isLocked={isPageLocked}
        onLockToggle={setIsPageLocked}
      />

      {/* Alerts */}
      {error && (
        <div className="mb-6">
          <AdminAlert variant="error">
            {error}
          </AdminAlert>
        </div>
      )}
      {success && (
        <div className="mb-6">
          <AdminAlert variant="success">
            {success}
          </AdminAlert>
        </div>
      )}

      {/* Page Sections */}
      <div className="bg-white border border-gray-200 rounded-lg">
        <div className="p-6 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold text-gray-900">Content Sections</h2>
            <AdminButton variant="primary" size="sm" onClick={() => setShowAddSection(true)}>
              <Plus className="w-4 h-4 mr-2" />
              Add Section
            </AdminButton>
          </div>
        </div>

        {pageData.sections.length === 0 ? (
          <div className="p-12 text-center">
            <div className="text-gray-400 mb-4">
              <Plus className="w-12 h-12 mx-auto" />
            </div>
            <h3 className="text-lg font-medium text-gray-900 mb-2">No sections yet</h3>
            <p className="text-gray-500 mb-4">Start building your page by adding your first section</p>
            <AdminButton variant="primary" onClick={() => setShowAddSection(true)}>
              <Plus className="w-4 h-4 mr-2" />
              Add Your First Section
            </AdminButton>
          </div>
        ) : (
          <DragDropContext onDragEnd={handleDragEnd}>
            <Droppable droppableId="sections">
              {(provided) => (
                <div
                  {...provided.droppableProps}
                  ref={provided.innerRef}
                  className="space-y-4"
                >
                  {pageData.sections.map((section, index) => (
                    <Draggable key={section.id} draggableId={section.id} index={index}>
                      {(provided, snapshot) => (
                        <div
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          className={`${snapshot.isDragging ? 'bg-gray-50 shadow-lg' : ''}`}
                        >
                          <SectionCard
                            section={section}
                            index={index}
                            onEdit={() => handleEditSection(section)}
                            onDelete={() => handleDeleteSection(section.id)}
                            onDuplicate={() => handleDuplicateSection(section)}
                            onToggleActive={(isActive) => handleToggleActive(section.id, isActive)}
                            dragHandleProps={provided.dragHandleProps}
                          />
                        </div>
                      )}
                    </Draggable>
                  ))}
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          </DragDropContext>
        )}
      </div>

      {/* Add Section Modal */}
      <AdminModal
        isOpen={showAddSection}
        onClose={() => setShowAddSection(false)}
        title="Add Section"
      >
        <SectionTypeSelector
          onSelect={(type, name) => handleAddSection(type, name)}
          onCancel={() => setShowAddSection(false)}
        />
      </AdminModal>

      {/* Page Settings Modal */}
      <AdminModal
        isOpen={showPageSettings}
        onClose={() => setShowPageSettings(false)}
        title="Page Settings"
      >
        <PageMetadataEditor
          pageData={pageData}
          onSave={async (metadata: PageData['metadata']) => {
            try {
              // Save metadata to API
              const response = await fetch(`/api/cms/pages/${pageSlug}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  title: metadata.seoTitle,
                  meta_description: metadata.seoDescription,
                  meta_keywords: '',
                  og_image: metadata.featuredImage || '',
                  is_published: true
                })
              })

              if (!response.ok) {
                const result = await response.json().catch(() => null)
                throw new Error(result?.error || `Failed to save SEO settings (${response.status})`)
              }

              const result = await response.json()
              if (!result.success) {
                throw new Error(result.error || 'Failed to save SEO settings')
              }

              // Update local state on success
              setPageData({ ...pageData, metadata })
              setSuccess('Page settings saved successfully')
              setTimeout(() => setSuccess(null), 3000)
              setShowPageSettings(false)
            } catch (err) {
              const errorMessage = err instanceof Error ? err.message : 'Failed to save page settings'
              console.error('Error saving page metadata:', err)
              setError(errorMessage)
            }
          }}
          onCancel={() => setShowPageSettings(false)}
        />
      </AdminModal>

      {/* Edit Section Modal */}
      <SectionEditModal
        isOpen={showEditSection}
        onClose={() => setShowEditSection(false)}
        section={selectedSection}
        onSave={handleSaveSection}
      />

      {/* Version History Modal */}
      <VersionHistory
        pageSlug={pageSlug}
        isOpen={showVersionHistory}
        onClose={() => setShowVersionHistory(false)}
        onRestore={handleRestoreVersion}
      />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { X } from 'lucide-react'
import AdminButton from '@/components/admin/ui/AdminButton'
import AdminModal from '@/components/admin/ui/AdminModal'
import AdminInput from '@/components/admin/ui/AdminInput'
import AdminTextarea from '@/components/admin/ui/AdminTextarea'
import AdminSelect from '@/components/admin/ui/AdminSelect'
import RichTextEditor from './RichTextEditor'
import { ImagePicker } from '@/components/admin/inline-editor/ImagePicker'
import { PageSection } from '@/lib/cms-types'

interface SectionEditModalProps {
  isOpen: boolean
  onClose: () => void
  section: PageSection | null
  onSave: (section: PageSection) => void
}

export default function SectionEditModal({
  isOpen,
  onClose,
  section,
  onSave
}: SectionEditModalProps) {
  const [formData, setFormData] = useState({
    section_name: '',
    title: '',
    subtitle: '',
    description: '',
    content: '',
    image_url: '',
    video_url: '',
    button_text: '',
    button_link: '',
    background_color: '',
    text_color: '',
    // Surf page specific fields
    disclaimer: '',
    imageUrl: '',
    mapImageUrl: '',
    footerText: '',
    epicImageUrl: '',
    epicImageCaption: '',
    videoUrl: '',
    videoCaption: '',
    buttonText: '',
    buttonUrl: ''
  })
  const [saving, setSaving] = useState(false)

  useEffect(() => {
    if (section) {
      // Handle both object content (JSONB) and string content
      const content = typeof section.content === 'string'
        ? (() => {
            try {
              return JSON.parse(section.content)
            } catch {
              return { content: section.content }
            }
          })()
        : (section.content || {})

      setFormData({
        section_name: section.section_name || '',
        title: content.title || '',
        subtitle: content.subtitle || '',
        description: content.description || '',
        content: content.content || '',
        image_url: content.image_url || '',
        video_url: content.video_url || '',
        button_text: content.button_text || '',
        button_link: content.button_link || '',
        background_color: content.background_color || '',
        text_color: content.text_color || '',
        // Surf page specific fields
        disclaimer: content.disclaimer || '',
        imageUrl: content.imageUrl || '',
        mapImageUrl: content.mapImageUrl || '',
        footerText: content.footerText || '',
        epicImageUrl: content.epicImageUrl || '',
        epicImageCaption: content.epicImageCaption || '',
        videoUrl: content.videoUrl || '',
        videoCaption: content.videoCaption || '',
        buttonText: content.buttonText || '',
        buttonUrl: content.buttonUrl || ''
      })
    } else {
      // Reset form when section is null
      setFormData({
        section_name: '',
        title: '',
        subtitle: '',
        description: '',
        content: '',
        image_url: '',
        video_url: '',
        button_text: '',
        button_link: '',
        background_color: '',
        text_color: '',
        // Surf page specific fields
        disclaimer: '',
        imageUrl: '',
        mapImageUrl: '',
        footerText: '',
        epicImageUrl: '',
        epicImageCaption: '',
        videoUrl: '',
        videoCaption: '',
        buttonText: '',
        buttonUrl: ''
      })
    }
  }, [section])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!section) return

    try {
      setSaving(true)

      // Ensure content is an object, even if it was empty
      const existingContent = typeof section.content === 'object' && section.content !== null
        ? section.content
        : {}

      // Build content based on section type
      let updatedContent: Record<string, unknown> = {
        ...existingContent,
        title: formData.title,
        subtitle: formData.subtitle,
        description: formData.description,
        content: formData.content,
        image_url: formData.image_url,
        video_url: formData.video_url,
        button_text: formData.button_text,
        button_link: formData.button_link,
        background_color: formData.background_color,
        text_color: formData.text_color
      }

      // Add surf-specific fields based on section type
      if (section.section_type === 'local_break') {
        updatedContent = {
          ...updatedContent,
          disclaimer: formData.disclaimer,
          imageUrl: formData.imageUrl || formData.image_url
        }
      } else if (section.section_type === 'surf_lessons') {
        // Convert content paragraphs from newline-separated text to array
        const paragraphs = formData.content
          ? formData.content.split(/\n\n+/).filter(p => p.trim())
          : []
        updatedContent = {
          ...updatedContent,
          paragraphs: paragraphs.length > 0 ? paragraphs : existingContent.paragraphs,
          buttonText: formData.buttonText || formData.button_text,
          buttonUrl: formData.buttonUrl || formData.button_link
        }
      } else if (section.section_type === 'surf_conditions') {
        updatedContent = {
          ...updatedContent,
          epicImageUrl: formData.epicImageUrl,
          epicImageCaption: formData.epicImageCaption,
          videoUrl: formData.videoUrl || formData.video_url,
          videoCaption: formData.videoCaption
        }
      } else if (section.section_type === 'world_class_surfing') {
        updatedContent = {
          ...updatedContent,
          mapImageUrl: formData.mapImageUrl,
          footerText: formData.footerText
        }
      }

      const updatedSection: PageSection = {
        ...section,
        section_name: formData.section_name,
        content: updatedContent,
        updated_at: new Date().toISOString()
      }

      onSave(updatedSection)
      onClose()
    } catch (err) {
      console.error('Failed to save section:', err)
    } finally {
      setSaving(false)
    }
  }

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }))
  }

  const renderSectionFields = () => {
    if (!section) return null

    switch (section.section_type) {
      case 'hero':
        return (
          <div className="space-y-4">
            <AdminInput
              label="Hero Title"
              value={formData.title}
              onChange={(value) => handleInputChange('title', value)}
              placeholder="Enter hero title"
              maxLength={100}
              required
            />
            <AdminInput
              label="Hero Subtitle"
              value={formData.subtitle}
              onChange={(value) => handleInputChange('subtitle', value)}
              placeholder="Enter hero subtitle"
              maxLength={200}
            />
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Hero Description
              </label>
              <RichTextEditor
                value={formData.description}
                onChange={(value) => handleInputChange('description', value)}
                placeholder="Enter hero description"
                maxLength={500}
                height={150}
              />
            </div>
            <AdminInput
              label="Button Text"
              value={formData.button_text}
              onChange={(value) => handleInputChange('button_text', value)}
              placeholder="e.g., Get Started"
              maxLength={50}
            />
            <AdminInput
              label="Button Link"
              value={formData.button_link}
              onChange={(value) => handleInputChange('button_link', value)}
              placeholder="/contact"
              maxLength={200}
            />
            <ImagePicker
              label="Background Image"
              value={formData.image_url}
              onChange={(value) => handleInputChange('image_url', value)}
              placeholder="Select background image..."
            />
          </div>
        )

      case 'intro':
        return (
          <div className="space-y-4">
            <AdminInput
              label="Section Title"
              value={formData.title}
              onChange={(value) => handleInputChange('title', value)}
              placeholder="Enter section title"
              maxLength={100}
              required
            />
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Content
              </label>
              <RichTextEditor
                value={formData.content}
                onChange={(value) => handleInputChange('content', value)}
                placeholder="Enter section content"
                maxLength={1000}
                height={200}
              />
            </div>
            <ImagePicker
              label="Image"
              value={formData.image_url}
              onChange={(value) => handleInputChange('image_url', value)}
              placeholder="Select image..."
            />
          </div>
        )

      case 'text':
        return (
          <div className="space-y-4">
            <AdminInput
              label="Text Title"
              value={formData.title}
              onChange={(value) => handleInputChange('title', value)}
              placeholder="Enter text title"
              maxLength={100}
              required
            />
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Text Content
              </label>
              <RichTextEditor
                value={formData.content}
                onChange={(value) => handleInputChange('content', value)}
                placeholder="Enter text content"
                maxLength={2000}
                height={300}
              />
            </div>
          </div>
        )

      case 'features':
        return (
          <div className="space-y-4">
            <AdminInput
              label="Features Title"
              value={formData.title}
              onChange={(value) => handleInputChange('title', value)}
              placeholder="e.g., Our Features"
              maxLength={100}
              required
            />
            <AdminTextarea
              label="Features Description"
              value={formData.description}
              onChange={(value) => handleInputChange('description', value)}
              placeholder="Describe the features"
              maxLength={300}
              rows={3}
            />
            <div className="p-4 bg-gray-50 rounded-lg">
              <p className="text-sm text-gray-600">
                Feature items are managed through the content editor. 
                This section shows the main title and description.
              </p>
            </div>
          </div>
        )

      case 'gallery':
        return (
          <div className="space-y-4">
            <AdminInput
              label="Gallery Title"
              value={formData.title}
              onChange={(value) => handleInputChange('title', value)}
              placeholder="e.g., Photo Gallery"
              maxLength={100}
              required
            />
            <AdminTextarea
              label="Gallery Description"
              value={formData.description}
              onChange={(value) => handleInputChange('description', value)}
              placeholder="Describe the gallery"
              maxLength={300}
              rows={3}
            />
            <div className="p-4 bg-gray-50 rounded-lg">
              <p className="text-sm text-gray-600">
                Images are managed through the media library. 
                This section controls the title and description.
              </p>
            </div>
          </div>
        )

      case 'pricing':
        return (
          <div className="space-y-4">
            <AdminInput
              label="Pricing Title"
              value={formData.title}
              onChange={(value) => handleInputChange('title', value)}
              placeholder="e.g., Our Pricing"
              maxLength={100}
              required
            />
            <AdminTextarea
              label="Pricing Description"
              value={formData.description}
              onChange={(value) => handleInputChange('description', value)}
              placeholder="Describe pricing options"
              maxLength={300}
