"use client"

// Media Library Component
// Comprehensive media management with drag-and-drop upload

import React, { useState, useEffect, useRef } from 'react'
import {
  AdminButton,
  AdminInput,
  AdminSelect,
  AdminModal,
  AdminAlert,
  AdminTable,
  type AdminTableColumn
} from '../ui'
import { MediaItem } from '@/lib/cms-validators'
import {
  Upload,
  Image as ImageIcon,
  Video,
  FileText
} from 'lucide-react'
import { formatDateCompact } from '@/lib/utils'

interface MediaLibraryProps {
  className?: string
  onSelect?: (media: MediaItem) => void
  multiSelect?: boolean
  maxSelections?: number
}

const FILE_TYPES = [
  { value: 'image', label: 'Images' },
  { value: 'video', label: 'Videos' },
  { value: 'document', label: 'Documents' }
] as const

const CATEGORIES = [
  { value: 'general', label: 'General' },
  { value: 'hero', label: 'Hero' },
  { value: 'activities', label: 'Activities' },
  { value: 'testimonials', label: 'Testimonials' },
  { value: 'blog', label: 'Blog' }
] as const

const MediaLibrary: React.FC<MediaLibraryProps> = ({
  className,
  onSelect,
  multiSelect = false,
  maxSelections = 10
}) => {
  const [media, setMedia] = useState<MediaItem[]>([])
  const [loading, setLoading] = useState(true)
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [selectedMedia, setSelectedMedia] = useState<MediaItem[]>([])
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false)
  const [isPreviewModalOpen, setIsPreviewModalOpen] = useState(false)
  const [previewMedia, setPreviewMedia] = useState<MediaItem | null>(null)
  const [alert, setAlert] = useState<{ type: 'success' | 'error'; message: string } | null>(null)
  const [filters, setFilters] = useState({
    search: '',
    file_type: '',
    category: '',
    is_active: true
  })

  const fileInputRef = useRef<HTMLInputElement>(null)

  // Load media
  const loadMedia = async () => {
    try {
      setLoading(true)
      setError(null)

      const params = new URLSearchParams()
      if (filters.file_type) params.set('file_type', filters.file_type)
      if (filters.category) params.set('category', filters.category)
      if (filters.search) params.set('search', filters.search)
      params.set('sort_by', 'created_at')
      params.set('sort_order', 'desc')
      params.set('limit', '200')

      const response = await fetch(`/api/cms/media?${params.toString()}`, { method: 'GET' })
      const result = await response.json().catch(() => null)
      if (!response.ok) {
        throw new Error(result?.message || `Failed to load media (${response.status})`)
      }

      setMedia(result?.data || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load media')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadMedia()
  }, [loadMedia, filters])

  // Show alert
  const showAlert = (type: 'success' | 'error', message: string) => {
    setAlert({ type, message })
    setTimeout(() => setAlert(null), 5000)
  }

  // Handle file upload
  const handleFileUpload = async (files: FileList) => {
    if (files.length === 0) return

    setUploading(true)
    const uploadPromises = Array.from(files).map(async (file) => {
      try {
        const form = new FormData()
        form.set('file', file)
        form.set('alt_text', '')
        form.set('category', 'general')
        form.set('tags', '')

        const response = await fetch('/api/cms/media', {
          method: 'POST',
          credentials: 'include',
          body: form,
        })

        const result = await response.json().catch(() => null)
        if (!response.ok) {
          throw new Error(result?.message || `Upload failed (${response.status})`)
        }

        return result?.data
      } catch (err) {
        console.error('Upload error:', err)
        throw err
      }
    })

    try {
      const results = await Promise.allSettled(uploadPromises)
      const successful = results.filter(r => r.status === 'fulfilled').length
      const failed = results.filter(r => r.status === 'rejected').length

      if (successful > 0) {
        showAlert('success', `${successful} file(s) uploaded successfully`)
      }
      if (failed > 0) {
        showAlert('error', `${failed} file(s) failed to upload`)
      }

      loadMedia()
      setIsUploadModalOpen(false)
    } catch (err) {
      showAlert('error', 'Upload failed')
    } finally {
      setUploading(false)
    }
  }

  // Handle delete
  const handleDelete = async (item: MediaItem) => {
    if (!confirm('Are you sure you want to delete this media file?')) return

    try {
      const response = await fetch(`/api/cms/media?id=${encodeURIComponent(String(item.id))}`, {
        method: 'DELETE',
      })
      const result = await response.json().catch(() => null)
      if (!response.ok) {
        throw new Error(result?.message || `Failed to delete media (${response.status})`)
      }

      showAlert('success', 'Media deleted successfully')
      loadMedia()
    } catch (err) {
      showAlert('error', err instanceof Error ? err.message : 'Failed to delete media')
    }
  }

  // Handle selection
  const handleSelect = (item: MediaItem) => {
    if (onSelect) {
      onSelect(item)
      return
    }

    if (multiSelect) {
      const isSelected = selectedMedia.some(m => m.id === item.id)
      if (isSelected) {
        setSelectedMedia(selectedMedia.filter(m => m.id !== item.id))
      } else if (selectedMedia.length < maxSelections) {
        setSelectedMedia([...selectedMedia, item])
      }
    } else {
      setSelectedMedia([item])
    }
  }

  // Table columns
  const columns: AdminTableColumn<MediaItem>[] = [
    {
      key: 'file_type',
      title: 'Type',
      render: (value: unknown) => {
        const icon = value === 'image' ? ImageIcon : value === 'video' ? Video : FileText
        return React.createElement(icon, { className: 'w-5 h-5' })
      }
    },
    {
      key: 'original_name',
      title: 'Filename'
    },
    {
      key: 'file_size',
      title: 'Size',
      render: (value: unknown) => formatFileSize(Number(value))
    },
    {
      key: 'category',
      title: 'Category'
    },
    {
      key: 'created_at',
      title: 'Uploaded',
      render: (value: unknown) => formatDateCompact(String(value))
    }
  ]

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-orange-600"></div>
      </div>
    )
  }

  return (
    <div className={className}>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold text-gray-900">Media Library</h1>
        <AdminButton
          variant="primary"
          icon="upload"
          onClick={() => setIsUploadModalOpen(true)}
        >
          Upload Files
        </AdminButton>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-4 mb-6">
        <AdminInput
          placeholder="Search files..."
          value={filters.search}
          onChange={(value) => setFilters({ ...filters, search: value })}
          className="flex-1 min-w-[200px]"
        />

        <AdminSelect
          placeholder="File type"
          options={[{ value: '', label: 'All Types' }, ...FILE_TYPES]}
          value={filters.file_type}
          onChange={(value) => setFilters({ ...filters, file_type: value as '' | 'image' | 'video' | 'document' })}
          className="min-w-[150px]"
        />

        <AdminSelect
          placeholder="Category"
          options={[{ value: '', label: 'All Categories' }, ...CATEGORIES]}
          value={filters.category}
          onChange={(value) => setFilters({ ...filters, category: value as '' | 'general' | 'hero' | 'activities' | 'testimonials' | 'blog' })}
          className="min-w-[150px]"
        />
      </div>

      {/* Alert */}
      {alert && (
        <div className="mb-4">
          <AdminAlert
            variant={alert.type}
            dismissible
            onDismiss={() => setAlert(null)}
          >
            {alert.message}
          </AdminAlert>
        </div>
      )}

      {/* Error */}
      {error && (
        <AdminAlert variant="error" className="mb-4">
          {error}
        </AdminAlert>
      )}

      {/* Table */}
      <AdminTable
        data={media as MediaItem[]}
        columns={columns}
        empty="No media files found. Upload your first file to get started."
        selectable={multiSelect || !!onSelect}
        selectedRows={selectedMedia as MediaItem[]}
        onSelectionChange={(rows) => setSelectedMedia(rows as MediaItem[])}
        onRowClick={(row) => handleSelect(row as MediaItem)}
      />

      {/* Upload Modal */}
      <AdminModal
        isOpen={isUploadModalOpen}
        onClose={() => setIsUploadModalOpen(false)}
        title="Upload Files"
        size="md"
      >
        <div className="space-y-4">
          <div
            className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center hover:border-orange-500 transition-colors cursor-pointer"
            onClick={() => fileInputRef.current?.click()}
          >
            <Upload className="w-12 h-12 mx-auto mb-4 text-gray-400" />
            <p className="text-gray-600 mb-2">Click to upload or drag and drop</p>
            <p className="text-sm text-gray-500">Images, videos, and documents</p>
            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept="image/*,video/*,.pdf,.doc,.docx"
              onChange={(e) => e.target.files && handleFileUpload(e.target.files)}
              className="hidden"
            />
          </div>

          <div className="flex justify-end gap-2">
            <AdminButton
              variant="outline"
              onClick={() => setIsUploadModalOpen(false)}
              disabled={uploading}
            >
              Cancel
            </AdminButton>
            <AdminButton
              variant="primary"
              onClick={() => fileInputRef.current?.click()}
              loading={uploading}
            >
              Select Files
            </AdminButton>
          </div>
        </div>
      </AdminModal>

      {/* Preview Modal */}
      <AdminModal
        isOpen={isPreviewModalOpen}
        onClose={() => setIsPreviewModalOpen(false)}
        title="Media Preview"
        size="lg"
      >
        {previewMedia && (
          <div className="space-y-4">
            {previewMedia.file_type === 'image' && (
              <img
                src={previewMedia.public_url}
                alt={previewMedia.alt_text}
                className="w-full h-auto rounded-lg"
              />
            )}

            {previewMedia.file_type === 'video' && (
              <video
                src={previewMedia.public_url}
                controls
                className="w-full h-auto rounded-lg"
              />
            )}

            {previewMedia.file_type === 'document' && (
              <div className="text-center py-8">
                <FileText className="w-16 h-16 mx-auto mb-4 text-gray-400" />
                <p className="text-gray-600">{previewMedia.original_name}</p>
              </div>
            )}

            <div className="grid grid-cols-2 gap-4 text-sm">
              <div>
                <span className="font-medium">Filename:</span>
                <p className="text-gray-600">{previewMedia.original_name}</p>
              </div>
              <div>
                <span className="font-medium">Size:</span>
                <p className="text-gray-600">{formatFileSize(previewMedia.file_size || 0)}</p>
              </div>
              <div>
                <span className="font-medium">Type:</span>
                <p className="text-gray-600">{previewMedia.file_type}</p>
              </div>
              <div>
                <span className="font-medium">Category:</span>
                <p className="text-gray-600">{previewMedia.category}</p>
              </div>
            </div>
          </div>
        )}
      </AdminModal>
    </div>
  )
}

export default MediaLibrary

'use client'

import { useState, useEffect } from 'react'
import { Plus, Edit, Trash2, Eye, EyeOff, GripVertical, FileText, Image, Video, Star, Layout, DollarSign } from 'lucide-react'
import AdminButton from '@/components/admin/ui/AdminButton'
import AdminModal from '@/components/admin/ui/AdminModal'
import AdminAlert from '@/components/admin/ui/AdminAlert'
import { formatDateCompact } from '@/lib/utils'

interface PageContent {
  id: string
  page_slug: string
  section_type: string
  section_name: string
  content: Record<string, unknown>
  order_index: number
  is_active: boolean
  created_at: string
  updated_at: string
}

const PAGES = [
  { value: 'flow', label: 'Flow - Yoga & Wellness' },
  { value: 'play', label: 'Play - Activities & Fun' },
  { value: 'surf', label: 'Surf - Surfing & Lessons' },
  { value: 'the-spot', label: 'The Spot - Location & Venue' },
  { value: 'about', label: 'About - Our Story' },
  { value: 'contact', label: 'Contact - Get in Touch' }
]

const SECTION_TYPES = [
  { value: 'hero', label: 'Hero Section', icon: Layout },
  { value: 'intro', label: 'Introduction', icon: FileText },
  { value: 'features', label: 'Features Grid', icon: Star },
  { value: 'gallery', label: 'Gallery', icon: Image },
  { value: 'pricing', label: 'Pricing', icon: DollarSign },
  { value: 'text', label: 'Text Content', icon: FileText },
  { value: 'image_text', label: 'Image & Text', icon: Image },
  { value: 'video', label: 'Video Section', icon: Video },
  { value: 'custom', label: 'Custom Content', icon: FileText }
]

export function PageContentEditor() {
  const [selectedPage, setSelectedPage] = useState('flow')
  const [pageContent, setPageContent] = useState<PageContent[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [showModal, setShowModal] = useState(false)
  const [editingSection, setEditingSection] = useState<PageContent | null>(null)
  const [success, setSuccess] = useState<string | null>(null)

  useEffect(() => {
    fetchPageContent()
  }, [selectedPage])

  const fetchPageContent = async () => {
    setLoading(true)
    setError(null)

    try {
      const response = await fetch(`/api/admin/pages?page_slug=${selectedPage}`)
      const data = await response.json()

      if (data.success) {
        setPageContent(data.data)
      } else {
        setError(data.error || 'Failed to fetch page content')
      }
    } catch (err) {
      setError('Error loading page content')
    } finally {
      setLoading(false)
    }
  }

  const handleCreateSection = () => {
    setEditingSection(null)
    setShowModal(true)
  }

  const handleEditSection = (section: PageContent) => {
    setEditingSection(section)
    setShowModal(true)
  }

  const handleDeleteSection = async (id: string) => {
    if (!confirm('Are you sure you want to delete this section?')) return

    try {
      const response = await fetch(`/api/admin/pages/${id}`, {
        method: 'DELETE'
      })
      const data = await response.json()

      if (data.success) {
        setSuccess('Section deleted successfully')
        fetchPageContent()
        setTimeout(() => setSuccess(null), 3000)
      } else {
        setError(data.error || 'Failed to delete section')
      }
    } catch (err) {
      setError('Error deleting section')
    }
  }

  const handleToggleActive = async (section: PageContent) => {
    try {
      const response = await fetch(`/api/admin/pages/${section.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          ...section,
          is_active: !section.is_active,
          updated_by: 'admin'
        })
      })
      const data = await response.json()

      if (data.success) {
        setSuccess(`Section ${section.is_active ? 'deactivated' : 'activated'} successfully`)
        fetchPageContent()
        setTimeout(() => setSuccess(null), 3000)
      } else {
        setError(data.error || 'Failed to update section')
      }
    } catch (err) {
      setError('Error updating section')
    }
  }

  const getSectionIcon = (sectionType: string) => {
    const section = SECTION_TYPES.find(s => s.value === sectionType)
    return section ? section.icon : FileText
  }

  const getSectionTypeLabel = (sectionType: string) => {
    const section = SECTION_TYPES.find(s => s.value === sectionType)
    return section ? section.label : sectionType
  }

  if (loading) {
    return (
      <div className="animate-pulse">
        <div className="h-8 bg-gray-200 rounded w-1/4 mb-6"></div>
        <div className="space-y-4">
          {[1, 2, 3].map(i => (
            <div key={i} className="h-24 bg-gray-200 rounded"></div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Page Content Editor</h2>
          <p className="text-gray-600 mt-1">Manage content sections for your pages</p>
        </div>
        <AdminButton onClick={handleCreateSection}>
          <Plus className="h-4 w-4 mr-2" />
          Add Section
        </AdminButton>
      </div>

      {/* Page Selector */}
      <div className="bg-white rounded-lg shadow p-6">
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Select Page
        </label>
        <select
          value={selectedPage}
          onChange={(e) => setSelectedPage(e.target.value)}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
        >
          {PAGES.map(page => (
            <option key={page.value} value={page.value}>
              {page.label}
            </option>
          ))}
        </select>
      </div>

      {/* Success/Error Messages */}
      {success && (
        <AdminAlert variant="success">
          {success}
        </AdminAlert>
      )}

      {error && (
        <AdminAlert variant="error">
          {error}
        </AdminAlert>
      )}

      {/* Content Sections */}
      <div className="space-y-4">
        {pageContent.length === 0 ? (
          <div className="bg-white rounded-lg shadow p-12 text-center">
            <FileText className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">
              No content sections
            </h3>
            <p className="text-gray-600 mb-4">
              Get started by adding your first content section to this page.
            </p>
            <AdminButton onClick={handleCreateSection} variant="outline">
              <Plus className="h-4 w-4 mr-2" />
              Add First Section
            </AdminButton>
          </div>
        ) : (
          pageContent.map(section => {
            const Icon = getSectionIcon(section.section_type)
            return (
              <div
                key={section.id}
                className={`bg-white rounded-lg shadow p-6 border-2 transition-all ${
                  section.is_active ? 'border-gray-200' : 'border-gray-100 opacity-75'
                }`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex items-start space-x-4">
                    <div className="flex-shrink-0">
                      <GripVertical className="h-5 w-5 text-gray-400" />
                    </div>
                    <div className="flex-shrink-0">
                      <div className="p-2 bg-blue-100 rounded-lg">
                        <Icon className="h-5 w-5 text-blue-600" />
                      </div>
                    </div>
                    <div className="flex-1">
                      <h3 className="text-lg font-medium text-gray-900">
                        {section.section_name || getSectionTypeLabel(section.section_type)}
                      </h3>
                      <p className="text-sm text-gray-600 mt-1">
                        {getSectionTypeLabel(section.section_type)}
                      </p>
                      <div className="mt-2 text-xs text-gray-500">
                        Order: {section.order_index} •
                        Created: {formatDateCompact(section.created_at)}
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center space-x-2">
                    <button
                      onClick={() => handleToggleActive(section)}
                      className={`p-2 rounded-lg transition-colors ${
                        section.is_active 
                          ? 'text-green-600 hover:bg-green-50' 
                          : 'text-gray-400 hover:bg-gray-50'
                      }`}
                      title={section.is_active ? 'Deactivate' : 'Activate'}
                    >
                      {section.is_active ? <Eye className="h-4 w-4" /> : <EyeOff className="h-4 w-4" />}
                    </button>

                    <button
                      onClick={() => handleEditSection(section)}
                      className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                      title="Edit section"
                    >
                      <Edit className="h-4 w-4" />
                    </button>

                    <button
                      onClick={() => handleDeleteSection(section.id)}
                      className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                      title="Delete section"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              </div>
            )
          })
        )}
      </div>

      {/* Section Editor Modal */}
      {showModal && (
        <SectionEditorModal
          section={editingSection}
          pageSlug={selectedPage}
          onClose={() => setShowModal(false)}
          onSave={() => {
            setShowModal(false)
            fetchPageContent()
            setSuccess('Section saved successfully')
            setTimeout(() => setSuccess(null), 3000)
          }}
        />
      )}
    </div>
  )
}

// Section Editor Modal Component
interface SectionEditorModalProps {
  section: PageContent | null
  pageSlug: string
  onClose: () => void
  onSave: () => void
}

function SectionEditorModal({ section, pageSlug, onClose, onSave }: SectionEditorModalProps) {
  const [formData, setFormData] = useState({
    section_name: '',
    section_type: 'hero',
    content: {},
    order_index: 0,
    is_active: true
  })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (section) {
      setFormData({
        section_name: section.section_name,
        section_type: section.section_type,
        content: section.content,
        order_index: section.order_index,
        is_active: section.is_active
      })
    }
  }, [section])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setError(null)

    try {
      const url = section 
        ? `/api/admin/pages/${section.id}`
        : '/api/admin/pages'

      const method = section ? 'PUT' : 'POST'

      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          ...formData,
          page_slug: pageSlug,
          created_by: 'admin',
          updated_by: 'admin'
        })
      })

      const data = await response.json()

      if (data.success) {
        onSave()
      } else {
        setError(data.error || 'Failed to save section')
      }
    } catch (err) {
      setError('Error saving section')
    } finally {
      setLoading(false)
    }
  }

  return (
    <AdminModal isOpen={true} onClose={onClose} title={section ? 'Edit Section' : 'Add Section'}>
      <form onSubmit={handleSubmit} className="space-y-6">
        {error && (
          <AdminAlert variant="error">
            {error}
          </AdminAlert>
        )}

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Section Type
          </label>
          <select
            value={formData.section_type}
            onChange={(e) => setFormData({ ...formData, section_type: e.target.value })}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          >
            {SECTION_TYPES.map(type => (
              <option key={type.value} value={type.value}>
                {type.label}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Section Name
          </label>
          <input
            type="text"
            value={formData.section_name}
            onChange={(e) => setFormData({ ...formData, section_name: e.target.value })}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            placeholder="e.g., Hero Section, Features Grid"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Order Index
          </label>
          <input
            type="number"
            value={formData.order_index}
            onChange={(e) => setFormData({ ...formData, order_index: parseInt(e.target.value) })}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            min="0"
          />
        </div>

        <div className="flex items-center">
          <input
            type="checkbox"
            id="is_active"
            checked={formData.is_active}
            onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
            className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
          />
          <label htmlFor="is_active" className="ml-2 block text-sm text-gray-900">
            Section is active
          </label>
        </div>

        <div className="flex justify-end space-x-3 pt-4 border-t">
          <AdminButton type="button" variant="outline" onClick={onClose}>
            Cancel
          </AdminButton>
          <AdminButton type="submit" disabled={loading}>
            {loading ? 'Saving...' : (section ? 'Update' : 'Create')} Section
          </AdminButton>
        </div>
      </form>
    </AdminModal>
  )
}

export default PageContentEditor

'use client'

import { useState, useEffect } from 'react'
import { Plus, Edit, Trash2, Star } from 'lucide-react'
import AdminButton from '@/components/admin/ui/AdminButton'
import AdminModal from '@/components/admin/ui/AdminModal'
import AdminAlert from '@/components/admin/ui/AdminAlert'
import { formatDateCompact } from '@/lib/utils'

interface Testimonial {
  id: string
  guest_name: string
  guest_email: string
  rating: number
  text: string
  is_featured: boolean
  guest_image_url?: string
  created_at: string
  updated_at: string
}

export function TestimonialsManager() {
  const [testimonials, setTestimonials] = useState<Testimonial[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [showModal, setShowModal] = useState(false)
  const [editingTestimonial, setEditingTestimonial] = useState<Testimonial | null>(null)
  const [success, setSuccess] = useState<string | null>(null)
  const [filter, setFilter] = useState<'all' | 'featured'>('all')

  useEffect(() => {
    fetchTestimonials()
  }, [filter])

  const fetchTestimonials = async () => {
    setLoading(true)
    setError(null)

    try {
      const url = filter === 'featured' 
        ? '/api/admin/testimonials?featured=true'
        : '/api/admin/testimonials'

      const response = await fetch(url)
      const data = await response.json()

      if (data.success) {
        setTestimonials(data.data)
      } else {
        setError(data.error || 'Failed to fetch testimonials')
      }
    } catch (err) {
      setError('Error loading testimonials')
    } finally {
      setLoading(false)
    }
  }

  const handleCreateTestimonial = () => {
    setEditingTestimonial(null)
    setShowModal(true)
  }

  const handleEditTestimonial = (testimonial: Testimonial) => {
    setEditingTestimonial(testimonial)
    setShowModal(true)
  }

  const handleDeleteTestimonial = async (id: string) => {
    if (!confirm('Are you sure you want to delete this testimonial?')) return

    try {
      const response = await fetch(`/api/admin/testimonials/${id}`, {
        method: 'DELETE'
      })
      const data = await response.json()

      if (data.success) {
        setSuccess('Testimonial deleted successfully')
        fetchTestimonials()
        setTimeout(() => setSuccess(null), 3000)
      } else {
        setError(data.error || 'Failed to delete testimonial')
      }
    } catch (err) {
      setError('Error deleting testimonial')
    }
  }

  const handleToggleFeatured = async (testimonial: Testimonial) => {
    try {
      const response = await fetch(`/api/admin/testimonials/${testimonial.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          ...testimonial,
          is_featured: !testimonial.is_featured,
          updated_by: 'admin'
        })
      })
      const data = await response.json()

      if (data.success) {
        setSuccess(`Testimonial ${testimonial.is_featured ? 'removed from' : 'added to'} featured`)
        fetchTestimonials()
        setTimeout(() => setSuccess(null), 3000)
      } else {
        setError(data.error || 'Failed to update testimonial')
      }
    } catch (err) {
      setError('Error updating testimonial')
    }
  }

  const exportToCSV = () => {
    const headers = ['Name', 'Email', 'Rating', 'Text', 'Featured', 'Date']
    const rows = testimonials.map(t => [
      t.guest_name,
      t.guest_email || '',
      t.rating,
      `"${t.text.replace(/"/g, '""')}"`,
      t.is_featured ? 'Yes' : 'No',
      formatDateCompact(t.created_at)
    ])

    const csv = [headers, ...rows].map(row => row.join(',')).join('\n')
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = window.URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `testimonials-${new Date().toISOString().split('T')[0]}.csv`
    a.click()
    window.URL.revokeObjectURL(url)
  }

  const renderStars = (rating: number) => {
    return Array.from({ length: 5 }, (_, i) => (
      <Star
        key={i}
        className={`h-4 w-4 ${
          i < rating ? 'text-yellow-400 fill-current' : 'text-gray-300'
        }`}
      />
    ))
  }

  if (loading) {
    return (
      <div className="animate-pulse">
        <div className="h-8 bg-gray-200 rounded w-1/4 mb-6"></div>
        <div className="space-y-4">
          {[1, 2, 3].map(i => (
            <div key={i} className="h-32 bg-gray-200 rounded"></div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Testimonials Manager</h2>
          <p className="text-gray-600 mt-1">Manage guest reviews and testimonials</p>
        </div>
        <div className="flex space-x-3">
          <AdminButton onClick={exportToCSV} variant="outline">
            <Download className="h-4 w-4 mr-2" />
            Export CSV
          </AdminButton>
          <AdminButton onClick={handleCreateTestimonial}>
            <Plus className="h-4 w-4 mr-2" />
            Add Testimonial
          </AdminButton>
        </div>
      </div>

      {/* Filter Tabs */}
      <div className="bg-white rounded-lg shadow">
        <div className="border-b border-gray-200">
          <nav className="flex -mb-px">
            <button
              onClick={() => setFilter('all')}
              className={`py-4 px-6 text-sm font-medium border-b-2 ${
                filter === 'all'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              All Testimonials ({testimonials.length})
            </button>
            <button
              onClick={() => setFilter('featured')}
              className={`py-4 px-6 text-sm font-medium border-b-2 ${
                filter === 'featured'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              Featured ({testimonials.filter(t => t.is_featured).length})
            </button>
          </nav>
        </div>
      </div>

      {/* Success/Error Messages */}
      {success && (
        <AdminAlert variant="success">
          {success}
        </AdminAlert>
      )}

      {error && (
        <AdminAlert variant="error">
          {error}
        </AdminAlert>
      )}

      {/* Testimonials List */}
      <div className="space-y-4">
        {testimonials.length === 0 ? (
          <div className="bg-white rounded-lg shadow p-12 text-center">
            <MessageSquare className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">
              No testimonials
            </h3>
            <p className="text-gray-600 mb-4">
              Start collecting guest reviews and testimonials.
            </p>
            <AdminButton onClick={handleCreateTestimonial} variant="outline">
              <Plus className="h-4 w-4 mr-2" />
              Add First Testimonial
            </AdminButton>
          </div>
        ) : (
          testimonials.map((testimonial) => (
            <div
              key={testimonial.id}
              className={`bg-white rounded-lg shadow p-6 border-2 transition-all ${
                testimonial.is_featured ? 'border-yellow-200' : 'border-gray-200'
              }`}
            >
              <div className="flex items-start justify-between">
                <div className="flex items-start space-x-4">
                  <div className="flex-shrink-0">
                    {testimonial.guest_image_url ? (
                      <img
                        src={testimonial.guest_image_url}
                        alt={testimonial.guest_name}
                        className="h-12 w-12 rounded-full object-cover"
                      />
                    ) : (
                      <div className="h-12 w-12 bg-gray-200 rounded-full flex items-center justify-center">
                        <User className="h-6 w-6 text-gray-400" />
                      </div>
                    )}
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center space-x-2">
                      <h3 className="text-lg font-medium text-gray-900">
                        {testimonial.guest_name}
                      </h3>
                      {testimonial.is_featured && (
                        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800">
                          <Star className="h-3 w-3 mr-1" />
                          Featured
                        </span>
                      )}
                    </div>

                    {testimonial.guest_email && (
                      <div className="flex items-center text-sm text-gray-600 mt-1">
                        <Mail className="h-4 w-4 mr-1" />
                        {testimonial.guest_email}
                      </div>
                    )}

                    <div className="flex items-center mt-2">
                      {renderStars(testimonial.rating)}
                      <span className="ml-2 text-sm text-gray-600">
                        ({testimonial.rating}/5)
                      </span>
                    </div>

                    <p className="mt-3 text-gray-700 leading-relaxed">
                      {testimonial.text}
                    </p>

                    <div className="mt-4 text-xs text-gray-500">
                      Added on {formatDateCompact(testimonial.created_at)}
                    </div>
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  <button
                    onClick={() => handleToggleFeatured(testimonial)}
                    className={`p-2 rounded-lg transition-colors ${
                      testimonial.is_featured 
                        ? 'text-yellow-600 hover:bg-yellow-50' 
                        : 'text-gray-400 hover:bg-gray-50'
                    }`}
                    title={testimonial.is_featured ? 'Remove from featured' : 'Add to featured'}
                  >
                    <Star className="h-4 w-4" />
                  </button>

                  <button
                    onClick={() => handleEditTestimonial(testimonial)}
                    className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                    title="Edit testimonial"
                  >
                    <Edit className="h-4 w-4" />
                  </button>

                  <button
                    onClick={() => handleDeleteTestimonial(testimonial.id)}
                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                    title="Delete testimonial"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Testimonial Editor Modal */}
      {showModal && (
        <TestimonialEditorModal
          testimonial={editingTestimonial}
          onClose={() => setShowModal(false)}
          onSave={() => {
            setShowModal(false)
            fetchTestimonials()
            setSuccess('Testimonial saved successfully')
            setTimeout(() => setSuccess(null), 3000)
          }}
        />
      )}
    </div>
  )
}

// Testimonial Editor Modal Component
interface TestimonialEditorModalProps {
  testimonial: Testimonial | null
  onClose: () => void
  onSave: () => void
}

function TestimonialEditorModal({ testimonial, onClose, onSave }: TestimonialEditorModalProps) {
  const [formData, setFormData] = useState({
    guest_name: '',
    guest_email: '',
    rating: 5,
    text: '',
    is_featured: false,
    guest_image_url: ''
