                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-gray-900 truncate">{activity.name}</p>
                  <p className="text-xs text-gray-500">
                    {activity.category} • {activity.tier}
                    {!activity.is_active && ' • Inactive'}
