  const text = JSON.stringify(bodyRich)
  const wordCount = text.split(/\s+/).length
  return Math.max(1, Math.ceil(wordCount / 200))
}

// Related Posts Algorithm
// Finds posts related to a given post based on category, tags, and content similarity

import { supabase } from '@/lib/supabase'
import type { BlogPost } from './db'

export async function getRelatedPosts(
  postId: string,
  categoryId?: string,
  tagIds?: string[],
  limit: number = 4
): Promise<BlogPost[]> {
  try {
    // Build query for published posts excluding the current post
    let query = supabase
      .from('blog_posts')
      .select(`
        *,
        category:blog_categories(*),
        author:blog_authors(*),
        translations:blog_post_translations!inner(*),
        tags:blog_post_tags(
          tag:blog_tags(*)
        )
      `)
      .eq('status', 'published')
      .eq('translations.locale', 'en')
      .neq('id', postId)

    // If category exists, prioritize posts in same category
    if (categoryId) {
      query = query.eq('category_id', categoryId)
    }

    // Order by published date (most recent first)
    query = query.order('published_at', { ascending: false })

    // Limit results
    query = query.limit(limit * 2) // Get more to filter by tags

    const { data, error } = await query

    if (error) {
      throw error
    }

    // Score and sort posts by relevance
    const scoredPosts = (data || []).map((post: any) => {
      let score = 0

      // Same category = high score
      if (post.category_id === categoryId) {
        score += 10
      }

      // Shared tags = medium score
      if (tagIds && tagIds.length > 0 && post.tags) {
        const sharedTags = post.tags.filter((pt: any) =>
          tagIds.includes(pt.tag?.id)
        ).length
        score += sharedTags * 5
      }

      // Recency bonus (more recent = slightly higher score)
      if (post.published_at) {
        const daysSincePublished = Math.floor(
          (Date.now() - new Date(post.published_at).getTime()) / (1000 * 60 * 60 * 24)
        )
        score += Math.max(0, 5 - daysSincePublished / 30) // Bonus decreases over time
      }

      return { ...post, _score: score }
    })

    // Sort by score and take top results
    const relatedPosts = scoredPosts
      .sort((a, b) => b._score - a._score)
      .slice(0, limit)
      .map(({ _score, ...post }) => ({
        ...post,
        tags: post.tags?.map((pt: any) => pt.tag) || []
      }))

    // If we don't have enough related posts, fill with recent posts
    if (relatedPosts.length < limit) {
      const { data: recentPosts } = await supabase
        .from('blog_posts')
        .select(`
          *,
          category:blog_categories(*),
          author:blog_authors(*),
          translations:blog_post_translations!inner(*),
          tags:blog_post_tags(
            tag:blog_tags(*)
          )
        `)
        .eq('status', 'published')
        .eq('translations.locale', 'en')
        .neq('id', postId)
        .order('published_at', { ascending: false })
        .limit(limit - relatedPosts.length)

      const additionalPosts = (recentPosts || []).map((post: any) => ({
        ...post,
        tags: post.tags?.map((pt: any) => pt.tag) || []
      }))

      // Filter out duplicates
      const existingIds = new Set(relatedPosts.map(p => p.id))
      const newPosts = additionalPosts.filter(p => !existingIds.has(p.id))

      return [...relatedPosts, ...newPosts].slice(0, limit)
    }

    return relatedPosts as BlogPost[]
  } catch (error) {
    console.error('Error fetching related posts:', error)
    return []
  }
}

import { Room, SurfCamp, AddOn } from '@/lib/schemas';
import { differenceInDays } from 'date-fns';

export interface BookingItem {
  id: string;
  type: 'room' | 'surfCamp' | 'addOn';
  itemId: string;
  name: string;
  quantity: number;
  unitPrice: number;
  totalPrice: number;
  startDate?: string;
  endDate?: string;
  nights?: number;
  participants?: number;
}

export interface PriceBreakdown {
  subtotal: number;
  taxes: number;
  fees: number;
  discounts: number;
  total: number;
  items: BookingItem[];
}

/**
 * Check if dates fall in peak season (May-September)
 * Uses UTC to avoid timezone/DST issues
 */
function isPeakSeasonPeriod(startDate: string, endDate: string): boolean {
  const peakSeasonMonths = [5, 6, 7, 8, 9] // May to September
  // Parse as UTC to avoid timezone issues
  const start = new Date(startDate + 'T00:00:00Z')
  const end = new Date(endDate + 'T00:00:00Z')
  const current = new Date(start)

  while (current < end) {
    if (peakSeasonMonths.includes(current.getUTCMonth() + 1)) {
      return true
    }
    current.setUTCDate(current.getUTCDate() + 1)
  }

  return false
}

/**
 * Calculate room price based on dates, quantity, and pricing model
 */
export function calculateRoomPrice(
  room: Room & { id: string },
  startDate?: string,
  endDate?: string,
  quantity: number = 1
): { unitPrice: number; totalPrice: number; nights?: number } {
  // Calculate nights if dates are provided
  let nights = 1;
  if (startDate && endDate) {
    const start = new Date(startDate);
    const end = new Date(endDate);
    nights = Math.max(1, differenceInDays(end, start));
  }

  // Determine seasonal rate based on dates
  // Peak season (May-Sept) uses standard pricing, off-season uses offSeason pricing
  // Note: The schema has standard/offSeason - standard IS the peak rate
  let basePrice = 0;
  if (startDate && endDate) {
    const isPeak = isPeakSeasonPeriod(startDate, endDate);
    basePrice = isPeak
      ? (room.pricing.standard || room.pricing.offSeason || 0)
      : (room.pricing.offSeason || room.pricing.standard || 0);
  } else {
    // No dates provided - use standard rate as default
    basePrice = room.pricing.standard || room.pricing.offSeason || 0;
  }

  // Handle different pricing models based on bookingType and camp pricing
  let unitPrice = basePrice;

  if (room.bookingType === 'perBed') {
    // Use camp pricing for per-bed bookings
    if (typeof room.pricing.camp === 'object' && 'perBed' in room.pricing.camp) {
      unitPrice = room.pricing.camp.perBed * nights;
    } else {
      unitPrice = basePrice * nights;
    }
  } else {
    // Whole room pricing - use camp pricing if available
    if (typeof room.pricing.camp === 'object' && typeof room.pricing.camp === 'object' && !('perBed' in room.pricing.camp)) {
      // Use camp pricing for occupancy-based rates
      const campPricing = room.pricing.camp as Record<number, number>;
      const occupancyRate = campPricing[1] || basePrice; // Default to 1 person rate
      unitPrice = occupancyRate * nights;
    } else {
      unitPrice = basePrice * nights;
    }
  }

  return {
    unitPrice,
    totalPrice: unitPrice * quantity,
    nights
  };
}

/**
 * Calculate surf camp price based on participants and duration
 * Note: SurfCamp schema doesn't include pricing - this would need CampWeek data
 */
export function calculateSurfCampPrice(
  camp: SurfCamp & { id: string },
  participants: number = 1,
  duration?: number,
  basePrice: number = 0 // Base price should be provided from CampWeek or other source
): { unitPrice: number; totalPrice: number } {
  let unitPrice = basePrice;

  // Apply duration multiplier if specified
  if (duration && duration > 1) {
    unitPrice = basePrice * duration;
  }

  // Apply basic group discount based on participants (simplified)
  if (participants > 1) {
    const discountRate = Math.min(0.1 * (participants - 1), 0.3); // Max 30% discount
    unitPrice = unitPrice * (1 - discountRate);
  }

  return {
    unitPrice,
    totalPrice: unitPrice * participants
  };
}

/**
 * Calculate add-on service price
 */
export function calculateAddOnPrice(
  addOn: AddOn & { id: string },
  quantity: number = 1
): { unitPrice: number; totalPrice: number } {
  const unitPrice = addOn.price || 0;

  return {
    unitPrice,
    totalPrice: unitPrice * quantity
  };
}

/**
 * Calculate total amount for all booking items
 */
export function calculateTotalAmount(items: BookingItem[]): number {
  return items.reduce((total, item) => total + item.totalPrice, 0);
}

/**
 * Calculate comprehensive price breakdown with taxes
 * PRICING RULES:
 * 1. Prices are tax-INCLUSIVE (tax is extracted for display, not added)
 * 2. No service fee
 */
export function calculatePriceBreakdown(
  items: BookingItem[],
  taxRate: number = 0.1, // 10% VAT included in prices
  _serviceFeeRate: number = 0, // No service fee (kept for API compatibility)
  discountAmount: number = 0
): PriceBreakdown {
  const subtotal = calculateTotalAmount(items);
  // Tax is INCLUDED in price, extract for display (not added on top)
  const taxes = subtotal * taxRate / (1 + taxRate);
  const fees = 0; // No service fee
  const total = subtotal - discountAmount; // Price already includes tax

  return {
    subtotal,
    taxes,
    fees,
    discounts: discountAmount,
    total: Math.max(0, total), // Ensure total is never negative
    items
  };
}

interface SeasonalRate {
  startMonth: number
  startDay: number
  endMonth: number
  endDay: number
  price: number
}

/**
 * Get seasonal rate for a specific date
 */
function getSeasonalRate(seasonalRates: SeasonalRate[], date: string): number | null {
  if (!seasonalRates || seasonalRates.length === 0) return null;

  const targetDate = new Date(date);
  const month = targetDate.getMonth() + 1; // 1-based month
  const day = targetDate.getDate();

  for (const rate of seasonalRates) {
    if (isDateInRange(month, day, rate.startMonth, rate.startDay, rate.endMonth, rate.endDay)) {
      return rate.price;
    }
  }

  return null;
}

/**
 * Check if a date falls within a seasonal range
 */
function isDateInRange(
  month: number,
  day: number,
  startMonth: number,
  startDay: number,
  endMonth: number,
  endDay: number
): boolean {
  const targetDate = month * 100 + day; // MMDD format
  const startDate = startMonth * 100 + startDay;
  const endDate = endMonth * 100 + endDay;

  if (startDate <= endDate) {
    // Same year range
    return targetDate >= startDate && targetDate <= endDate;
  } else {
    // Cross-year range (e.g., Dec to Feb)
    return targetDate >= startDate || targetDate <= endDate;
  }
}

// formatCurrency is now imported from lib/utils.ts

/**
 * Calculate booking duration in nights
 */
export function calculateNights(startDate: string, endDate: string): number {
  const start = new Date(startDate);
  const end = new Date(endDate);
  return Math.max(1, differenceInDays(end, start));
}

/**
 * Validate booking dates
 * Uses UTC dates to avoid timezone/DST issues
 */
export function validateBookingDates(startDate: string, endDate: string): {
  isValid: boolean;
  error?: string;
} {
  // Parse as UTC to avoid timezone issues
  const start = new Date(startDate + 'T00:00:00Z');
  const end = new Date(endDate + 'T00:00:00Z');

  // Get today in UTC
  const now = new Date();
  const today = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));

  if (start < today) {
    return { isValid: false, error: 'Start date cannot be in the past' };
  }

  if (end <= start) {
    return { isValid: false, error: 'End date must be after start date' };
  }

  const maxAdvanceBooking = new Date(Date.UTC(now.getUTCFullYear() + 2, now.getUTCMonth(), now.getUTCDate()));

  if (start > maxAdvanceBooking) {
    return { isValid: false, error: 'Booking cannot be more than 2 years in advance' };
  }

  return { isValid: true };
}

/**
 * Apply discount to booking total
 */
export function applyDiscount(
  total: number,
  discountType: 'percentage' | 'fixed',
  discountValue: number
): { discountAmount: number; newTotal: number } {
  let discountAmount = 0;

  if (discountType === 'percentage') {
    discountAmount = total * (discountValue / 100);
  } else {
    discountAmount = Math.min(discountValue, total); // Don't exceed total
  }

  return {
    discountAmount,
    newTotal: Math.max(0, total - discountAmount)
  };
}

'use client'

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react'

interface Booking {
  id: string
  clientName: string
  email: string
  phone?: string
  checkIn: string
  checkOut: string
  roomType: string
  roomId?: string
  guests: number
  message?: string
  status: 'pending' | 'confirmed' | 'cancelled'
  totalPrice?: number
  surfWeekId?: string
  bookingType?: 'room' | 'surf-week'
}

interface BookingContextType {
  isBookingOpen: boolean
  openBooking: (surfWeekId?: string) => void
  closeBooking: () => void
  hasActiveBooking: boolean
  setBookingSuccess: (success: boolean) => void
  currentBooking: Booking | null
  setCurrentBooking: (booking: Booking | null) => void
  createBooking: (bookingData: Partial<Booking>) => Promise<{ success: boolean; bookingId?: string; error?: string }>
  checkAvailability: (roomId: string, checkIn: string, checkOut: string) => Promise<{ available: boolean; price?: number; message?: string }>
  selectedSurfWeek: any | null
  setSelectedSurfWeek: (surfWeek: any | null) => void
}

const BookingContext = createContext<BookingContextType | undefined>(undefined)

export function BookingProvider({ children }: { children: ReactNode }) {
  const [isBookingOpen, setIsBookingOpen] = useState(false)
  const [hasActiveBooking, setHasActiveBooking] = useState(false)
  const [currentBooking, setCurrentBooking] = useState<Booking | null>(null)
  const [selectedSurfWeek, setSelectedSurfWeek] = useState<any | null>(null)

  const openBooking = useCallback((surfWeekId?: string | any) => {
    // Handle case where an object is passed instead of a string ID
    let weekId: string | undefined
    if (surfWeekId) {
      if (typeof surfWeekId === 'string') {
        weekId = surfWeekId
      } else if (typeof surfWeekId === 'object' && surfWeekId.id) {
        weekId = surfWeekId.id
      } else {
        console.warn('Invalid surfWeekId provided:', surfWeekId)
        weekId = undefined
      }
    }

    if (weekId) {
      // Fetch surf week data first, then open widget after data is loaded
      fetch(`/api/surf-camps?category=surf-week`)
        .then(res => res.json())
        .then(data => {
          if (data.success) {
            const surfWeek = data.data.surf_camps.find((camp: any) => camp.id === weekId)
            if (surfWeek) {
              // Set surf week first, then open widget
              // React 18+ automatically batches these updates
              setSelectedSurfWeek(surfWeek)
              setIsBookingOpen(true) // Open AFTER setting surf week
            } else {
              console.error('Surf week not found:', weekId)
              setIsBookingOpen(true) // Still open widget even if not found
            }
          } else {
            setIsBookingOpen(true)
          }
        })
        .catch((error) => {
          console.error('Error fetching surf week:', error)
          setIsBookingOpen(true) // Open widget even on error
        })
    } else {
      // React 18+ automatically batches these updates
      setSelectedSurfWeek(null)
      setIsBookingOpen(true)
    }
  }, [])
  const closeBooking = useCallback(() => {
    setIsBookingOpen(false)
    setSelectedSurfWeek(null)
  }, [])
  const setBookingSuccess = useCallback((success: boolean) => setHasActiveBooking(success), [])

  const createBooking = useCallback(async (bookingData: Partial<Booking>) => {
    try {
      const bookingType = selectedSurfWeek ? 'surf-week' : 'room'
      const payload: any = {
        booking_type: bookingType,
        room_id: bookingData.roomId || 'default-room',
        start_date: bookingData.checkIn,
        end_date: bookingData.checkOut,
        participants: [{
          name: bookingData.clientName,
          email: bookingData.email,
          phone: bookingData.phone,
          message: bookingData.message
        }],
        clientName: bookingData.clientName,
        email: bookingData.email,
        phone: bookingData.phone,
        guests: bookingData.guests || 1
      }

      // Add surf week data if selected
      if (selectedSurfWeek) {
        payload.camp_id = selectedSurfWeek.id
        payload.surf_week_name = selectedSurfWeek.name
        payload.surf_week_dates = `${selectedSurfWeek.start_date} to ${selectedSurfWeek.end_date}`
      }

      const response = await fetch('/api/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      })

      const result = await response.json()

      if (result.success) {
        setCurrentBooking({
          id: result.data.booking_id,
          ...bookingData,
          surfWeekId: selectedSurfWeek?.id,
          bookingType,
          status: 'pending'
        } as Booking)
        setHasActiveBooking(true)
        return { success: true, bookingId: result.data.booking_id }
      } else {
        return { success: false, error: result.error }
      }
    } catch (error) {
      console.error('Booking creation error:', error)
      return { success: false, error: 'Failed to create booking' }
    }
  }, [selectedSurfWeek])

  const checkAvailability = useCallback(async (roomId: string, checkIn: string, checkOut: string) => {
    try {
      const response = await fetch(`/api/availability?roomId=${roomId}&checkIn=${checkIn}&checkOut=${checkOut}`)
      const result = await response.json()

      if (result.success) {
        return {
          available: result.data.available,
          price: result.data.totalPrice,
          message: result.data.available ? undefined : 'Room not available for selected dates'
        }
      } else {
        return { available: false, message: result.error }
      }
    } catch (error) {
      console.error('Availability check error:', error)
      return { available: false, message: 'Failed to check availability' }
    }
  }, [])

  return (
    <BookingContext.Provider value={{ 
      isBookingOpen, 
      openBooking, 
      closeBooking, 
      hasActiveBooking, 
      setBookingSuccess,
      currentBooking,
      setCurrentBooking,
      createBooking,
      checkAvailability,
      selectedSurfWeek,
      setSelectedSurfWeek
    }}>
      {children}
    </BookingContext.Provider>
  )
}

export function useBooking() {
  const context = useContext(BookingContext)
  if (context === undefined) {
    throw new Error('useBooking must be used within a BookingProvider')
  }
  return context
}

// Booking submission service for hybrid data access architecture
// Provides high-level booking submission functionality using local API

import type { BookingRequest, BookingResponse, ApiLoadingState } from './types';

export interface BookingSubmission extends BookingRequest {
  // Additional metadata for tracking
  submittedAt?: Date;
  source?: 'website' | 'widget' | 'api';
}

export interface BookingResult extends BookingResponse {
  loading: boolean;
  error?: string;
  submittedAt?: Date;
}

export interface BookingValidationResult {
  isValid: boolean;
  errors: string[];
  warnings: string[];
}

class BookingService {
  /**
   * Submit a booking request with validation and error handling
   */
  async submitBooking(booking: BookingSubmission): Promise<BookingResult> {
    try {
      // Validate booking before submission
      const validation = this.validateBooking(booking);
      if (!validation.isValid) {
        return {
          success: false,
          message: `Validation failed: ${validation.errors.join(', ')}`,
          loading: false,
          submittedAt: new Date(),
        };
      }

      // Submit directly to the local /api/bookings endpoint
      // Using the correct field names expected by the API
      const response = await fetch('/api/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          clientName: booking.clientName,
          email: booking.email,
          phone: booking.phone || '',
          room_id: booking.roomId,
          start_date: booking.checkIn,
          end_date: booking.checkOut,
          guests: booking.guests,
          message: booking.message || '',
          booking_type: 'room',
        }),
      });

      const data = await response.json();

      if (!data.success) {
        return {
          success: false,
          message: data.error || 'Booking submission failed',
          loading: false,
          submittedAt: new Date(),
        };
      }

      return {
        success: true,
        bookingId: data.data?.booking?.id,
        status: data.data?.booking?.status || 'pending',
        message: 'Booking submitted successfully',
        loading: false,
        submittedAt: new Date(),
      };
    } catch (error) {
      console.error('Booking submission failed:', error);

      return {
        success: false,
        message: 'Booking submission failed. Please try again or contact us directly.',
        loading: false,
        submittedAt: new Date(),
      };
    }
  }

  /**
   * Validate booking data before submission
   */
  validateBooking(booking: BookingSubmission): BookingValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Required field validation
    if (!booking.clientName?.trim()) {
      errors.push('Client name is required');
    }

    if (!booking.email?.trim()) {
      errors.push('Email is required');
    } else if (!this.isValidEmail(booking.email)) {
      errors.push('Invalid email format');
    }

    if (!booking.checkIn) {
      errors.push('Check-in date is required');
    }

    if (!booking.checkOut) {
      errors.push('Check-out date is required');
    }

    if (!booking.roomId?.trim()) {
      errors.push('Room selection is required');
    }

    if (!booking.guests || booking.guests < 1) {
      errors.push('Number of guests must be at least 1');
    }

    // Date validation
    if (booking.checkIn && booking.checkOut) {
      const checkInDate = new Date(booking.checkIn);
      const checkOutDate = new Date(booking.checkOut);
      const now = new Date();
      now.setHours(0, 0, 0, 0);

      if (checkInDate < now) {
        errors.push('Check-in date cannot be in the past');
      }

      if (checkOutDate <= checkInDate) {
        errors.push('Check-out date must be after check-in date');
      }

      // Minimum stay validation (2 nights)
      const diffTime = checkOutDate.getTime() - checkInDate.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays < 2) {
        errors.push('Minimum stay is 2 nights');
      }
    }

    // Warnings
    if (booking.guests > 4) {
      warnings.push('Large group bookings may require special arrangements');
    }

    const daysUntilCheckIn = booking.checkIn
      ? Math.ceil((new Date(booking.checkIn).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24))
      : 0;

    if (daysUntilCheckIn < 2) {
      warnings.push('Late bookings may not be confirmed immediately');
    }

    return {
      isValid: errors.length === 0,
      errors,
      warnings,
    };
  }

  /**
   * Check if booking would conflict with existing reservations
   * Note: This is a client-side estimate; final validation happens server-side
   */
  async checkBookingConflicts(booking: BookingSubmission): Promise<{
    hasConflicts: boolean;
    message?: string;
  }> {
    // This would typically call an availability check
    // For now, we'll assume no conflicts (server will validate)
    return {
      hasConflicts: false,
    };
  }

  /**
   * Get booking policies and requirements
   */
  getBookingPolicies() {
    return {
      minimumStay: 2, // nights
      cancellationHours: 48, // hours before check-in
      checkInTime: '15:00', // 3:00 PM
      checkOutTime: '11:00', // 11:00 AM
      paymentRequired: true,
      maxGuestsPerRoom: 4,
    };
  }

  /**
   * Calculate estimated booking cost
   * Note: This is an estimate; final pricing comes from server
   */
  calculateEstimatedCost(
    roomId: string,
    checkIn: string,
    checkOut: string,
    guests: number
  ): {
    estimatedTotal: number
    currency: string
    breakdown: {
      baseRate: number
      nights: number
      subtotal: number
      taxes: number
      total: number
    }
  } {
    // This would typically call the admin API for pricing
    // For now, return a placeholder
    const nights = Math.ceil(
      (new Date(checkOut).getTime() - new Date(checkIn).getTime()) / (1000 * 60 * 60 * 24)
    );

    return {
      estimatedTotal: nights * 100, // Placeholder pricing
      currency: 'EUR',
      breakdown: {
        baseRate: 100,
        nights,
        subtotal: nights * 100,
        taxes: 0,
        total: nights * 100,
      },
    };
  }

  /**
   * Send booking confirmation email
   * Note: This would typically be handled by the admin system
   */
  async sendConfirmationEmail(bookingId: string): Promise<boolean> {
    // This would call an admin API endpoint for sending confirmations
    console.log(`Sending confirmation email for booking ${bookingId}`);
    return true;
  }

  /**
   * Basic email validation
   */
  private isValidEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }
}

