/**
 * Type-safe environment variable validation
 * Centralized location for all environment variable access
 */

import { z } from 'zod';

/**
 * Environment variable schema
 */
const envSchema = z.object({
  // Node environment
  NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),

  // Email service (Resend)
  RESEND_API_KEY: z.string().optional(),
  FROM_EMAIL: z.string().default('Heiwa House <noreply@heiwahouse.com>'),
  ADMIN_EMAIL: z.string().default('info@heiwahouse.com'),
  REPLY_TO_EMAIL: z.string().default('info@heiwahouse.com'),

  // Database
  DATABASE_URL: z.string().optional(),
  SUPABASE_URL: z.string().optional(),
  SUPABASE_ANON_KEY: z.string().optional(),
  SUPABASE_SERVICE_ROLE_KEY: z.string().optional(),

  // Payment processing
  STRIPE_SECRET_KEY: z.string().optional(),
  STRIPE_PUBLISHABLE_KEY: z.string().optional(),
  STRIPE_WEBHOOK_SECRET: z.string().optional(),

  // Other API keys
  GOOGLE_PLACES_API_KEY: z.string().optional(),
  GOOGLE_MAPS_API_KEY: z.string().optional(),
});

/**
 * Validated environment variables
 */
type Env = z.infer<typeof envSchema>;

let validatedEnv: Env | null = null;

/**
 * Get validated environment variables
 * Throws error if required variables are missing in production
 */
export function getEnv(): Env {
  if (validatedEnv) {
    return validatedEnv;
  }

  const rawEnv = {
    NODE_ENV: process.env.NODE_ENV,
    RESEND_API_KEY: process.env.RESEND_API_KEY,
    FROM_EMAIL: process.env.FROM_EMAIL,
    ADMIN_EMAIL: process.env.ADMIN_EMAIL,
    REPLY_TO_EMAIL: process.env.REPLY_TO_EMAIL,
    DATABASE_URL: process.env.DATABASE_URL,
    SUPABASE_URL: process.env.SUPABASE_URL,
    SUPABASE_ANON_KEY: process.env.SUPABASE_ANON_KEY,
    SUPABASE_SERVICE_ROLE_KEY: process.env.SUPABASE_SERVICE_ROLE_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    STRIPE_PUBLISHABLE_KEY: process.env.STRIPE_PUBLISHABLE_KEY,
    STRIPE_WEBHOOK_SECRET: process.env.STRIPE_WEBHOOK_SECRET,
    GOOGLE_PLACES_API_KEY: process.env.GOOGLE_PLACES_API_KEY,
    GOOGLE_MAPS_API_KEY: process.env.GOOGLE_MAPS_API_KEY,
  };

  const result = envSchema.safeParse(rawEnv);

  if (!result.success) {
    const errors = result.error.errors.map(e => `${e.path.join('.')}: ${e.message}`).join(', ');
    const error = new Error(`Invalid environment variables: ${errors}`);

    // Log error but don't crash in development
    if (isProduction()) {
      // In production, log and rethrow
      console.error('[ENV ERROR]', error.message);
      throw error;
    } else {
      // In development, log warning and return defaults
      console.warn('[ENV WARNING]', error.message);
      // Return defaults for development
      validatedEnv = {
        NODE_ENV: 'development',
        FROM_EMAIL: 'Heiwa House <noreply@heiwahouse.com>',
        ADMIN_EMAIL: 'info@heiwahouse.com',
        REPLY_TO_EMAIL: 'info@heiwahouse.com',
        ...rawEnv as any,
      };
      return validatedEnv!;
    }
  }

  validatedEnv = result.data;
  return validatedEnv;
}

/**
 * Get environment variable with validation
 * Use this instead of direct process.env access
 */
export const env = new Proxy({} as Env, {
  get(_target, prop: keyof Env) {
    const env = getEnv();
    return env[prop];
  },
});

/**
 * Check if running in production
 */
export function isProduction(): boolean {
  return getEnv().NODE_ENV === 'production';
}

/**
 * Check if running in development
 */
export function isDevelopment(): boolean {
  return getEnv().NODE_ENV === 'development';
}

/**
 * Health Check Utilities
 * Provides comprehensive health checks for all services
 */

import { supabaseAdmin } from './supabase'

export interface HealthCheckResult {
  service: string
  status: 'healthy' | 'degraded' | 'unhealthy'
  responseTime: number
  message?: string
  details?: any
  timestamp: string
}

export interface OverallHealth {
  status: 'healthy' | 'degraded' | 'unhealthy'
  checks: HealthCheckResult[]
  timestamp: string
  uptime: number
}

// Application start time
const startTime = Date.now()

/**
 * Check database health
 */
export async function checkDatabaseHealth(): Promise<HealthCheckResult> {
  const start = Date.now()

  try {
    // Simple query to check connection
    const { data, error } = await supabaseAdmin
      .from('rooms')
      .select('id')
      .limit(1)

    const responseTime = Date.now() - start

    if (error) {
      return {
        service: 'database',
        status: 'unhealthy',
        responseTime,
        message: 'Database query failed',
        details: { error: error.message },
        timestamp: new Date().toISOString(),
      }
    }

    return {
      service: 'database',
      status: 'healthy',
      responseTime,
      message: 'Database connection successful',
      timestamp: new Date().toISOString(),
    }
  } catch (error) {
    const responseTime = Date.now() - start
    return {
      service: 'database',
      status: 'unhealthy',
      responseTime,
      message: 'Database connection failed',
      details: { error: error instanceof Error ? error.message : 'Unknown error' },
      timestamp: new Date().toISOString(),
    }
  }
}

/**
 * Check Supabase storage health
 */
export async function checkStorageHealth(): Promise<HealthCheckResult> {
  const start = Date.now()

  try {
    // Check if we can list buckets
    const { data, error } = await supabaseAdmin.storage.listBuckets()

    const responseTime = Date.now() - start

    if (error) {
      return {
        service: 'storage',
        status: 'unhealthy',
        responseTime,
        message: 'Storage access failed',
        details: { error: error.message },
        timestamp: new Date().toISOString(),
      }
    }

    return {
      service: 'storage',
      status: 'healthy',
      responseTime,
      message: 'Storage access successful',
      details: { buckets: data.length },
      timestamp: new Date().toISOString(),
    }
  } catch (error) {
    const responseTime = Date.now() - start
    return {
      service: 'storage',
      status: 'unhealthy',
      responseTime,
      message: 'Storage check failed',
      details: { error: error instanceof Error ? error.message : 'Unknown error' },
      timestamp: new Date().toISOString(),
    }
  }
}

/**
 * Check external API health (Stripe, Resend, etc.)
 */
export async function checkExternalAPIHealth(
  name: string,
  url: string
): Promise<HealthCheckResult> {
  const start = Date.now()

  try {
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), 5000) // 5 second timeout

    const response = await fetch(url, {
      method: 'HEAD',
      signal: controller.signal,
    })

    clearTimeout(timeoutId)

    const responseTime = Date.now() - start

    if (response.ok) {
      return {
        service: name,
        status: 'healthy',
        responseTime,
        message: `${name} API is accessible`,
        timestamp: new Date().toISOString(),
      }
    } else {
      return {
        service: name,
        status: 'unhealthy',
        responseTime,
        message: `${name} API returned ${response.status}`,
        timestamp: new Date().toISOString(),
      }
    }
  } catch (error) {
    const responseTime = Date.now() - start
    return {
      service: name,
      status: 'unhealthy',
      responseTime,
      message: `${name} API check failed`,
      details: { error: error instanceof Error ? error.message : 'Unknown error' },
      timestamp: new Date().toISOString(),
    }
  }
}

/**
 * Check memory usage
 */
export function checkMemoryHealth(): HealthCheckResult {
  const start = Date.now()

  // Memory usage is not available in Node.js by default
  // This is a placeholder that would be enhanced with proper monitoring
  const responseTime = Date.now() - start

  return {
    service: 'memory',
    status: 'healthy',
    responseTime,
    message: 'Memory usage normal',
    timestamp: new Date().toISOString(),
  }
}

/**
 * Check disk space
 */
export function checkDiskHealth(): HealthCheckResult {
  const start = Date.now()

  // Disk space is not available in Node.js by default
  // This is a placeholder that would be enhanced with proper monitoring
  const responseTime = Date.now() - start

  return {
    service: 'disk',
    status: 'healthy',
    responseTime,
    message: 'Disk space normal',
    timestamp: new Date().toISOString(),
  }
}

/**
 * Run all health checks
 */
export async function runHealthChecks(): Promise<OverallHealth> {
  const checks: HealthCheckResult[] = []

  // Run all checks in parallel
  const [
    database,
    storage,
    memory,
    disk,
  ] = await Promise.all([
    checkDatabaseHealth(),
    checkStorageHealth(),
    checkMemoryHealth(),
    checkDiskHealth(),
  ])

  checks.push(database, storage, memory, disk)

  // Check external APIs if configured
  if (process.env.STRIPE_SECRET_KEY) {
    // Note: We can't actually check Stripe without a proper endpoint
    // This is a placeholder
    checks.push({
      service: 'stripe',
      status: 'healthy',
      responseTime: 0,
      message: 'Stripe configured',
      timestamp: new Date().toISOString(),
    })
  }

  if (process.env.RESEND_API_KEY) {
    // Check Resend API
    const resend = await checkExternalAPIHealth('resend', 'https://api.resend.com')
    checks.push(resend)
  }

  // Determine overall health
  const unhealthyCount = checks.filter(c => c.status === 'unhealthy').length
  const degradedCount = checks.filter(c => c.status === 'degraded').length

  let overallStatus: 'healthy' | 'degraded' | 'unhealthy'

  if (unhealthyCount > 0) {
    overallStatus = 'unhealthy'
  } else if (degradedCount > 0) {
    overallStatus = 'degraded'
  } else {
    overallStatus = 'healthy'
  }

  return {
    status: overallStatus,
    checks,
    timestamp: new Date().toISOString(),
    uptime: Date.now() - startTime,
  }
}

/**
 * Get health status for API response
 */
export async function getHealthStatus(): Promise<{
  status: 'healthy' | 'degraded' | 'unhealthy'
  checks: HealthCheckResult[]
  uptime: number
}> {
  const health = await runHealthChecks()

  return {
    status: health.status,
    checks: health.checks,
    uptime: health.uptime,
  }
}

/**
 * Check if system is healthy
 */
export async function isHealthy(): Promise<boolean> {
  const health = await runHealthChecks()
  return health.status === 'healthy'
}

import { useEffect, useRef } from 'react'
import { supabase } from '@/lib/supabase'

interface Booking {
  id: string
  guest_name: string
  guest_email: string
  guest_phone: string
  type: 'room' | 'surf_camp'
  item_name: string
  check_in: string
  check_out: string
  guests: number
  total_price: number
  status: 'pending' | 'confirmed' | 'cancelled' | 'completed'
  payment_status: 'pending' | 'paid' | 'refunded'
  created_at: string
  special_requests?: string
}

type BookingEvent = 'INSERT' | 'UPDATE' | 'DELETE'

interface UseBookingsRealtimeOptions {
  onInsert?: (booking: Booking) => void
  onUpdate?: (booking: Booking) => void
  onDelete?: (bookingId: string) => void
  onError?: (error: Error) => void
  onConnect?: (connected: boolean) => void
}

export function useBookingsRealtime(options: UseBookingsRealtimeOptions = {}) {
  // Use refs to store callbacks so they don't trigger re-subscriptions
  const callbacksRef = useRef(options)

  // Update refs when options change (without triggering re-subscription)
  useEffect(() => {
    callbacksRef.current = options
  }, [options])

  useEffect(() => {
    let subscription: any = null
    let isSubscribed = false

    const setupRealtimeSubscription = async () => {
      // Prevent multiple subscriptions
      if (isSubscribed) {
        return
      }

      try {
        // Subscribe to all changes on the bookings table
        subscription = supabase
          .channel('bookings_changes')
          .on(
            'postgres_changes',
            {
              event: '*',
              schema: 'public',
              table: 'bookings',
            },
            (payload: any) => {
              try {
                const event = payload.eventType as BookingEvent
                const callbacks = callbacksRef.current

                if (event === 'INSERT' && payload.new) {
                  const newBooking = transformBookingData(payload.new)
                  callbacks.onInsert?.(newBooking)
                } else if (event === 'UPDATE' && payload.new) {
                  const updatedBooking = transformBookingData(payload.new)
                  callbacks.onUpdate?.(updatedBooking)
                } else if (event === 'DELETE' && payload.old) {
                  callbacks.onDelete?.(payload.old.id)
                }
              } catch (err) {
                const callbacks = callbacksRef.current
                if (process.env.NODE_ENV === 'development') {
                  console.error('Error processing realtime event:', err)
                }
                callbacks.onError?.(err instanceof Error ? err : new Error('Unknown error'))
              }
            }
          )
          .subscribe((status: string) => {
            const callbacks = callbacksRef.current
            // Suppress all status logs - they're too noisy
            if (status === 'SUBSCRIBED') {
              isSubscribed = true
              callbacks.onConnect?.(true)
            } else if (status === 'CLOSED') {
              isSubscribed = false
              callbacks.onConnect?.(false)
              // Don't log CLOSED - it's normal during reconnection
            } else if (status === 'CHANNEL_ERROR') {
              isSubscribed = false
              if (process.env.NODE_ENV === 'development') {
                console.error('❌ Real-time channel error')
              }
              callbacks.onConnect?.(false)
            }
          })
      } catch (err) {
        isSubscribed = false
        const callbacks = callbacksRef.current
        if (process.env.NODE_ENV === 'development') {
          console.error('Failed to setup realtime subscription:', err)
        }
        callbacks.onError?.(err instanceof Error ? err : new Error('Failed to setup subscription'))
        callbacks.onConnect?.(false)
      }
    }

    setupRealtimeSubscription()

    // Cleanup subscription on unmount
    return () => {
      isSubscribed = false
      if (subscription) {
        subscription.unsubscribe()
      }
    }
  }, []) // Empty deps - only setup once, use refs for callbacks
}

/**
 * Transform database booking data to match Booking interface
 */
function transformBookingData(data: any): Booking {
  return {
    id: data.id,
    guest_name: data.guest_name || '',
    guest_email: data.guest_email || '',
    guest_phone: data.guest_phone || '',
    type: data.type || 'room',
    item_name: data.item_name || '',
    check_in: data.check_in || '',
    check_out: data.check_out || '',
    guests: data.guests || 1,
    total_price: data.total_price || 0,
    status: data.status || 'pending',
    payment_status: data.payment_status || 'pending',
    created_at: data.created_at || new Date().toISOString(),
    special_requests: data.special_requests,
  }
}

