/**
 * Image Upload Validation
 * Validates image uploads for security and performance
 */

import { z } from 'zod'

// Allowed image types
export const ALLOWED_IMAGE_TYPES = [
  'image/jpeg',
  'image/jpg',
  'image/png',
  'image/webp',
  'image/gif',
  'image/svg+xml',
] as const

// Maximum file sizes (in bytes)
export const MAX_FILE_SIZES = {
  avatar: 2 * 1024 * 1024, // 2MB
  room: 5 * 1024 * 1024, // 5MB
  surfCamp: 5 * 1024 * 1024, // 5MB
  facility: 5 * 1024 * 1024, // 5MB
  general: 10 * 1024 * 1024, // 10MB
} as const

// Image dimensions
export const IMAGE_DIMENSIONS = {
  avatar: { width: 512, height: 512 },
  room: { width: 1920, height: 1080 },
  surfCamp: { width: 1920, height: 1080 },
  facility: { width: 1920, height: 1080 },
} as const

/**
 * Zod schema for image upload validation
 */
export const ImageUploadSchema = z.object({
  file: z.instanceof(File, {
    message: 'Invalid file upload',
  }),
  type: z.enum(ALLOWED_IMAGE_TYPES, {
    message: 'Invalid image type. Allowed: JPEG, PNG, WebP, GIF, SVG',
  }),
  size: z.number().max(MAX_FILE_SIZES.general, {
    message: `File size must be less than ${MAX_FILE_SIZES.general / 1024 / 1024}MB`,
  }),
  category: z.enum(['avatar', 'room', 'surfCamp', 'facility', 'general']).default('general'),
})

export type ImageUpload = z.infer<typeof ImageUploadSchema>

/**
 * Validate image file
 */
export async function validateImageFile(
  file: File,
  category: keyof typeof MAX_FILE_SIZES = 'general'
): Promise<{
  valid: boolean
  error?: string
  metadata?: {
    width: number
    height: number
    format: string
    size: number
  }
}> {
  try {
    // Check file type
    if (!ALLOWED_IMAGE_TYPES.includes(file.type as any)) {
      return {
        valid: false,
        error: `Invalid file type. Allowed: ${ALLOWED_IMAGE_TYPES.join(', ')}`,
      }
    }

    // Check file size
    const maxSize = MAX_FILE_SIZES[category] || MAX_FILE_SIZES.general
    if (file.size > maxSize) {
      return {
        valid: false,
        error: `File size must be less than ${maxSize / 1024 / 1024}MB`,
      }
    }

    // Check image dimensions
    const dimensions = await getImageDimensions(file)
    if (!dimensions) {
      return {
        valid: false,
        error: 'Failed to read image dimensions',
      }
    }

    // Validate dimensions for specific categories
    if (category === 'avatar') {
      const maxDim = IMAGE_DIMENSIONS.avatar
      if (dimensions.width > maxDim.width || dimensions.height > maxDim.height) {
        return {
          valid: false,
          error: `Avatar must be ${maxDim.width}x${maxDim.height} or smaller`,
        }
      }
    }

    return {
      valid: true,
      metadata: {
        width: dimensions.width,
        height: dimensions.height,
        format: file.type,
        size: file.size,
      },
    }
  } catch (error) {
    return {
      valid: false,
      error: error instanceof Error ? error.message : 'Unknown validation error',
    }
  }
}

/**
 * Get image dimensions
 */
async function getImageDimensions(file: File): Promise<{ width: number; height: number } | null> {
  return new Promise((resolve) => {
    const img = new Image()
    const url = URL.createObjectURL(file)

    img.onload = () => {
      URL.revokeObjectURL(url)
      resolve({ width: img.width, height: img.height })
    }

    img.onerror = () => {
      URL.revokeObjectURL(url)
      resolve(null)
    }

    img.src = url
  })
}

/**
 * Sanitize filename
 */
export function sanitizeFilename(filename: string): string {
  // Remove path separators and special characters
  const sanitized = filename
    .replace(/[\/\\]/g, '_')
    .replace(/[<>:"|?*]/g, '_')
    .replace(/\s+/g, '_')
    .replace(/_{2,}/g, '_')
    .trim()

  // Add timestamp to prevent conflicts
  const timestamp = Date.now()
  const ext = filename.split('.').pop()
  const name = sanitized.replace(`.${ext}`, '')

  return `${name}_${timestamp}.${ext}`
}

/**
 * Generate unique filename
 */
export function generateUniqueFilename(
  originalName: string,
  prefix?: string
): string {
  const sanitized = sanitizeFilename(originalName)
  const timestamp = Date.now()
  const random = Math.random().toString(36).substring(2, 8)

  if (prefix) {
    return `${prefix}_${timestamp}_${random}_${sanitized}`
  }

  return `${timestamp}_${random}_${sanitized}`
}

/**
 * Validate image URL
 */
export function isValidImageUrl(url: string): boolean {
  try {
    const parsed = new URL(url)

    // Check protocol
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      return false
    }

    // Check for common image extensions
    const path = parsed.pathname.toLowerCase()
    const imageExtensions = ['.jpg', '.jpeg', '.png', '.webp', '.gif', '.svg']

    return imageExtensions.some(ext => path.endsWith(ext))
  } catch {
    return false
  }
}

/**
 * Optimize image (client-side)
 * Returns a promise that resolves to an optimized File
 */
export async function optimizeImage(
  file: File,
  options: {
    maxWidth?: number
    maxHeight?: number
    quality?: number
    format?: 'image/jpeg' | 'image/png' | 'image/webp'
  } = {}
): Promise<File> {
  const {
    maxWidth = 1920,
    maxHeight = 1080,
    quality = 0.85,
    format = 'image/webp',
  } = options

  return new Promise((resolve, reject) => {
    const img = new Image()
    const url = URL.createObjectURL(file)

    img.onload = () => {
      URL.revokeObjectURL(url)

      // Calculate dimensions
      let { width, height } = calculateDimensions(
        img.width,
        img.height,
        maxWidth,
        maxHeight
      )

      // Create canvas
      const canvas = document.createElement('canvas')
      canvas.width = width
      canvas.height = height

      const ctx = canvas.getContext('2d')
      if (!ctx) {
        reject(new Error('Failed to get canvas context'))
        return
      }

      // Draw image
      ctx.drawImage(img, 0, 0, width, height)

      // Convert to blob
      canvas.toBlob(
        (blob) => {
          if (!blob) {
            reject(new Error('Failed to optimize image'))
            return
          }

          const optimizedFile = new File([blob], file.name, {
            type: format,
            lastModified: Date.now(),
          })

          resolve(optimizedFile)
        },
        format,
        quality
      )
    }

    img.onerror = () => {
      URL.revokeObjectURL(url)
      reject(new Error('Failed to load image'))
    }

    img.src = url
  })
}

/**
 * Calculate dimensions while maintaining aspect ratio
 */
function calculateDimensions(
  originalWidth: number,
  originalHeight: number,
  maxWidth: number,
  maxHeight: number
): { width: number; height: number } {
  const widthRatio = maxWidth / originalWidth
  const heightRatio = maxHeight / originalHeight
  const ratio = Math.min(widthRatio, heightRatio, 1)

  return {
    width: Math.round(originalWidth * ratio),
    height: Math.round(originalHeight * ratio),
  }
}

/**
 * Validate multiple images
 */
export async function validateMultipleImages(
  files: File[],
  category: keyof typeof MAX_FILE_SIZES = 'general'
): Promise<{
  valid: boolean
  errors: string[]
  validFiles: File[]
  metadata: Array<{ width: number; height: number; format: string; size: number }>
}> {
  const errors: string[] = []
  const validFiles: File[] = []
  const metadata: Array<{ width: number; height: number; format: string; size: number }> = []

  for (let i = 0; i < files.length; i++) {
    const file = files[i]
    const result = await validateImageFile(file, category)

    if (result.valid) {
      validFiles.push(file)
      if (result.metadata) {
        metadata.push(result.metadata)
      }
    } else {
      errors.push(`File ${i + 1}: ${result.error}`)
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    validFiles,
    metadata,
  }
}

/**
 * Centralized logging utility for Heiwa House
 * Provides structured logging with different log levels
 */

export enum LogLevel {
  DEBUG = 'debug',
  INFO = 'info',
  WARN = 'warn',
  ERROR = 'error',
}

interface LogEntry {
  level: LogLevel
  message: string
  timestamp: string
  context?: Record<string, unknown>
  error?: Error
}

class Logger {
  private isDevelopment = process.env.NODE_ENV === 'development'
  private isProduction = process.env.NODE_ENV === 'production'

  private formatMessage(entry: LogEntry): string {
    const { level, message, timestamp, context } = entry
    let formatted = `[${timestamp}] [${level.toUpperCase()}] ${message}`

    if (context && Object.keys(context).length > 0) {
      formatted += ` | Context: ${JSON.stringify(context)}`
    }

    return formatted
  }

  private log(level: LogLevel, message: string, context?: Record<string, unknown>, error?: Error) {
    const entry: LogEntry = {
      level,
      message,
      timestamp: new Date().toISOString(),
      context,
      error,
    }

    // Always log in development
    if (this.isDevelopment) {
      const formatted = this.formatMessage(entry)

      switch (level) {
        case LogLevel.DEBUG:
          console.debug(formatted, error || '')
          break
        case LogLevel.INFO:
          console.info(formatted, error || '')
          break
        case LogLevel.WARN:
          console.warn(formatted, error || '')
          break
        case LogLevel.ERROR:
          console.error(formatted, error || '')
          if (error?.stack) {
            console.error('Stack trace:', error.stack)
          }
          break
      }
    }

    // In production, send to external logging service
    if (this.isProduction && (level === LogLevel.ERROR || level === LogLevel.WARN)) {
      this.sendToExternalService(entry)
    }
  }

  private sendToExternalService(entry: LogEntry) {
    // TODO: Integrate with logging service (e.g., Sentry, LogRocket, Datadog)
    // Example:
    // if (window.Sentry) {
    //   window.Sentry.captureException(entry.error || new Error(entry.message), {
    //     level: entry.level,
    //     extra: entry.context,
    //   })
    // }
  }

  debug(message: string, context?: Record<string, unknown>) {
    this.log(LogLevel.DEBUG, message, context)
  }

  info(message: string, context?: Record<string, unknown>) {
    this.log(LogLevel.INFO, message, context)
  }

  warn(message: string, context?: Record<string, unknown>, error?: Error) {
    this.log(LogLevel.WARN, message, context, error)
  }

  error(message: string, error?: Error, context?: Record<string, unknown>) {
    this.log(LogLevel.ERROR, message, context, error)
  }

  // Specific helpers for common scenarios
  apiError(endpoint: string, error: Error, context?: Record<string, unknown>) {
    this.error(`API Error: ${endpoint}`, error, {
      ...context,
      endpoint,
      errorMessage: error.message,
    })
  }

  bookingError(step: string, error: Error, context?: Record<string, unknown>) {
    this.error(`Booking Error: ${step}`, error, {
      ...context,
      step,
      errorMessage: error.message,
    })
  }

  dataFetchError(resource: string, error: Error, context?: Record<string, unknown>) {
    this.error(`Data Fetch Error: ${resource}`, error, {
      ...context,
      resource,
    })
  }

  validationError(field: string, message: string, context?: Record<string, unknown>) {
    this.error(`Validation Error: ${field}`, undefined, {
      ...context,
      field,
      validationMessage: message,
    })
  }
}

// Export singleton instance
export const logger = new Logger()

// Export default for convenience
export default logger

/**
 * Monitoring and Error Tracking Utilities
 * Centralized error logging and performance monitoring
 */

interface ErrorContext {
  userId?: string
  requestId?: string
  url?: string
  method?: string
  userAgent?: string
  ip?: string
  [key: string]: unknown
}

interface PerformanceMetric {
  name: string
  duration: number
  timestamp: number
  metadata?: Record<string, unknown>
}

class MonitoringService {
  private errors: Array<{ error: Error; context: ErrorContext; timestamp: number }> = []
  private metrics: PerformanceMetric[] = []
  private maxErrors = 100 // Keep last 100 errors in memory
  private maxMetrics = 1000 // Keep last 1000 metrics

  /**
   * Log an error with context
   */
  logError(error: Error | string, context: ErrorContext = {}) {
    const errorObj = typeof error === 'string' ? new Error(error) : error

    const errorEntry = {
      error: errorObj,
      context: {
        ...context,
        timestamp: new Date().toISOString(),
      },
      timestamp: Date.now(),
    }

    this.errors.push(errorEntry)
    if (this.errors.length > this.maxErrors) {
      this.errors.shift()
    }

    // Log to console in development
    if (process.env.NODE_ENV === 'development') {
      console.error('🔴 Error logged:', errorObj.message, context)
    }

    // TODO: Send to external error tracking service (Sentry, LogRocket, etc.)
    // Example: Sentry.captureException(errorObj, { extra: context })
  }

  /**
   * Track performance metrics
   */
  trackMetric(name: string, duration: number, metadata?: Record<string, unknown>) {
    const metric: PerformanceMetric = {
      name,
      duration,
      timestamp: Date.now(),
      metadata,
    }

    this.metrics.push(metric)
    if (this.metrics.length > this.maxMetrics) {
      this.metrics.shift()
    }

    // Log slow operations
    if (duration > 1000) {
      console.warn(`⚠️ Slow operation detected: ${name} took ${duration}ms`, metadata)
    }
  }

  /**
   * Get recent errors
   */
  getRecentErrors(limit = 10) {
    return this.errors.slice(-limit)
  }

  /**
   * Get performance metrics
   */
  getMetrics(name?: string, limit = 100) {
    const filtered = name
      ? this.metrics.filter(m => m.name === name)
      : this.metrics

    return filtered.slice(-limit)
  }

  /**
   * Get average performance for a metric
   */
  getAverageMetric(name: string) {
    const metrics = this.metrics.filter(m => m.name === name)
    if (metrics.length === 0) return null

    const total = metrics.reduce((sum, m) => sum + m.duration, 0)
    return total / metrics.length
  }

  /**
   * Clear all stored data
   */
  clear() {
    this.errors = []
    this.metrics = []
  }
}

// Singleton instance
export const monitoring = new MonitoringService()

/**
 * Performance tracking decorator
 */
export function trackPerformance(name: string) {
  return function (
    target: any,
    propertyKey: string,
    descriptor: PropertyDescriptor
  ) {
    const originalMethod = descriptor.value

    descriptor.value = async function (...args: any[]) {
      const start = Date.now()
      try {
        const result = await originalMethod.apply(this, args)
        const duration = Date.now() - start
        monitoring.trackMetric(`${target.constructor.name}.${propertyKey}`, duration)
        return result
      } catch (error) {
        const duration = Date.now() - start
        monitoring.trackMetric(`${target.constructor.name}.${propertyKey}`, duration, { error: true })
        monitoring.logError(error instanceof Error ? error : new Error(String(error)), {
          method: propertyKey,
          className: target.constructor.name,
        })
        throw error
      }
    }

    return descriptor
  }
}

/**
 * Helper to measure async function performance
 */
export async function measurePerformance<T>(
  name: string,
  fn: () => Promise<T>
): Promise<T> {
  const start = Date.now()
  try {
    const result = await fn()
    const duration = Date.now() - start
    monitoring.trackMetric(name, duration)
    return result
  } catch (error) {
    const duration = Date.now() - start
    monitoring.trackMetric(name, duration, { error: true })
    monitoring.logError(error instanceof Error ? error : new Error(String(error)), {
      operation: name,
    })
    throw error
  }
}

